exampleSpecifications :: [(FilePath, String)]
exampleSpecifications =
  [ ("abilities.lawspec", "unit example.abilities\n\n-- Dependencies are abilities. An ability names operations, the way a\n-- signature names a function; a handler gives them meaning. Code that uses\n-- Gateway says so, and every law about it holds for every lawful handler:\n-- the native one written by hand, and each spec handler below.\n\ntype Payment is one of | Approved  of type Int32 | Declined end type\ntype Receipt is a record{  cents :: Int32} end type\ntype PaymentError is one of | Refused | TooLarge end type\n\n-- A payment gateway. Its laws are obligations on every handler.\nability Gateway is\n  authorize :: Int32 -> Payment\n  capture :: Int32 -> Receipt\n  fee :: Int32\nlaws\n  law \"|a receipt is for the amount captured| is\n    definition : for all (cents :: Int32) => capture cents = Receipt record{ cents = cents} end for all end definition\n  end law\n  law \"|an approval is for the amount asked| is\n    definition :\n      for all (cents :: Int32) =>\n        (first matching case of authorize cents :\n         when Approved approved then approved = cents\n         when Declined then true\n         end case) = true end for all\n    end definition\n  end law\n  law \"|the fee is never negative| is\n    definition : fee >= 0 end definition\n  end law\nend laws\nend ability\n\n-- A fake for tests: it approves small amounts.\nhandler fakeGateway for Gateway is\n  operation authorize cents is if cents <= 10000 then Approved cents else Declined end if end operation\n  operation capture cents is Receipt record{ cents = cents} end operation\n  operation fee is 30 end operation\nend handler\n\n-- A handler with state: it keeps every amount it captured.\nhandler keepingGateway for Gateway with state captured :: List Int32 start [] is\n  operation authorize cents is Approved cents end operation\n  operation capture cents is ~captured := Cons cents captured; Receipt record{ cents = cents} end operation\n  operation fee is 0 end operation\nend handler\n\n-- A checked definition that uses Gateway. Its row, {Gateway}, is inferred.\nprocedure checkout (cents :: Int32) -> Bool is\n  first matching case of authorize cents :\n  when Approved amount then (first matching case of capture amount : when Receipt record{ cents = paid} then paid = cents end case)\n  when Declined then false\n  end case\nend procedure\n\n-- A native adapter that uses Gateway: it gets a handler as its first\n-- argument.\ncharge :: Int32 -> Bool uses Gateway\n\n-- A definition that can fail says what it fails with.\nprocedure pay (cents :: Int32) -> Receipt uses Gateway fails with PaymentError is\n  if cents > 100000 then raise TooLarge else\n    first matching case of authorize cents :\n    when Approved amount then capture amount\n    when Declined then raise Refused\n    end case end if\nend procedure\n\n-- Counting calls is part of the claim, so the law names a recording\n-- handler. Which gateway it records is left to the harness: each lawful one.\nlaw \"|checkout captures once, and only when it succeeds| using recording Gateway is\n  definition :\n    for all (cents :: Int32) =>\n      (if checkout cents then calls of capture with (cents) = 1 else calls of capture = 0 end if) = true end for all\n  end definition\nend law\n\nlaw \"|charge captures once, and only when it succeeds| using recording Gateway is\n  definition :\n    for all (cents :: Int32) =>\n      (if charge cents then calls of capture with (cents) = 1 else calls of capture = 0 end if) = true end for all\n  end definition\nend law\n\n-- This law needs the fake's limit, so the fake is part of the claim.\nlaw \"|large payments fail| using fakeGateway is\n  definition :\n    for all (cents :: Int32 where cents > 100000) => prelude.attempt (pay cents) = Left TooLarge end for all\n  end definition\nend law\n\nlaw \"|a declined payment is refused| using fakeGateway is\n  definition :\n    for all (cents :: Int32 where cents > 10000 && cents <= 100000) =>\n      prelude.attempt (pay cents) = Left Refused end for all\n  end definition\nend law\n\n-- Without `using`, a law runs under each lawful handler in turn.\nlaw \"|the fee is small| is\n  definition : fee <= 100 end definition\nend law\nend unit\n")
  , ("ability_imports.lawspec", "unit example.shop\n\nimport example.abilities as payments\n\n-- Abilities cross units: Gateway and its handlers come from\n-- example.abilities. This unit adds two of its own.\n\n-- A log. Its operation gives nothing back, so code calls it for its effect\n-- and goes on with `;`.\nability Log is\n  note :: Text -> Unit\nend ability\n\n-- A log that keeps what it is told.\nhandler keptLog for Log with state lines :: List Text start [] is\n  operation note message is ~lines := Cons message lines; unitValue end operation\nend handler\n\n-- A store of one value, at any type. This unit uses it at two.\nability Store (a :: Type) is\n  load :: a\n  save :: a -> Unit\nend ability\n\nhandler countStore for Store Int32 with state count :: Int32 start 0 is\n  operation load is count end operation\n  operation save value is ~count := value; unitValue end operation\nend handler\n\nhandler nameStore for Store Text with state name :: Text start \"\" is\n  operation load is name end operation\n  operation save value is ~name := value; unitValue end operation\nend handler\n\n-- A meter whose readings are never negative: every handler owes that.\nability Meter is\n  reading :: (r :: Int32 where r >= 0)\nend ability\n\nhandler fixedMeter for Meter is\n  operation reading is 7 end operation\nend handler\n\n-- A handler whose clauses use another ability: it notes each payment.\nhandler notingGateway for Gateway is\n  operation authorize cents is note \"authorize\"; Approved cents end operation\n  operation capture cents is note \"capture\"; Receipt cents end operation\n  operation fee is 0 end operation\nend handler\n\n-- Effects run in order: `a; b` runs a, then b; `let x = e in body` runs e\n-- once and names its value.\nprocedure buy (cents :: Int32) -> Bool uses Gateway, Log is\n  note \"buying\";\n  let approved = payments.checkout cents in\n  note \"bought\";\n  approved end let\nend procedure\n\n-- handle ... with h end runs its body with h answering h's ability, so the\n-- definition does not use that ability itself.\nfunction trial (cents :: Int32) -> Bool is\n  handle payments.checkout cents with fakeGateway end handle\nend function\n\nprocedure remember (count :: Int32) -> Int32 uses Store Int32 is\n  save count; load\nend procedure\n\nprocedure rename (name :: Text) -> Text uses Store Text is\n  save name; load\nend procedure\n\n-- A native adapter that may fail. Its native code raises the failure\n-- through the runtime's Fail.\nrefund :: Int32 -> Int32 uses Gateway fails with payments.PaymentError\n\nlaw \"|trial approves small amounts| is\n  definition :\n    for all (cents :: Int32 where cents >= 0 && cents <= 10000) => trial cents = true end for all\n  end definition\nend law\n\nlaw \"|buying with a noting gateway approves small amounts| using notingGateway, keptLog is\n  definition :\n    for all (cents :: Int32 where cents >= 0 && cents <= 10000) => buy cents = true end for all\n  end definition\nend law\n\nlaw \"|a stored count comes back| is\n  definition : for all (count :: Int32) => remember count = count end for all end definition\nend law\n\nlaw \"|a stored name comes back| is\n  definition : for all (name :: Text) => rename name = name end for all end definition\nend law\n\nlaw \"|a reading is small| using fixedMeter is\n  definition : reading <= 100 end definition\nend law\n\nlaw \"|refunds of large amounts fail| is\n  definition :\n    for all (cents :: Int32 where cents > 100000) =>\n      prelude.attempt (refund cents) = Left payments.TooLarge end for all\n  end definition\nend law\nend unit\n")
  , ("actors.lawspec", "unit example.actors\n\n-- An actor owns a state and handles one message at a time, in the order\n-- they arrive. Its handlers are plain functions from the state (and the\n-- message's arguments) to a reply and the next state; LawSpec runs them\n-- inside an actor and checks every reply against the model, in sequence and\n-- from several callers at once. Runs also crash the actor between\n-- messages: it restarts from its last state by reopen, and the model's state\n-- follows modelReopen.\ntype Account is a record{  balance :: Int64} end type\n\nopenAccount :: Unit -> Account\ndeposit :: Account -> UInt8 -> Pair Int64 Account\nwithdrawAll :: Account -> Pair Int64 Account\nbalance :: Account -> Pair Int64 Account\nclose :: Account -> Account\n-- After a crash, the account reopens with the balance it had.\nreopen :: Account -> Account\n\nfunction modelDeposit (amount :: UInt8) (n :: Int64 where n >= 0 && n <= 1000000) -> Pair Int64 Int64 is\n  Pair (n + amount) (n + amount)\nend function\n\nfunction modelWithdrawAll (n :: Int64) -> Pair Int64 Int64 is Pair n 0 end function\n\nfunction modelBalance (n :: Int64) -> Pair Int64 Int64 is Pair n n end function\nfunction modelClose (n :: Int64) -> Int64 is 0 end function\nfunction modelReopen (n :: Int64) -> Int64 is n end function\nfunction solvent (n :: Int64) -> Bool is n >= 0 end function\n\nactor account :: Account by Int64 is\n  start openAccount by 0\n  restart from reopen by modelReopen\n  on deposit by modelDeposit\n  on withdrawAll by modelWithdrawAll\n  on balance by modelBalance\n  on close by modelClose\n  invariant solvent\nend actor\n\n-- Implementation code uses the generated typed actor: depositTwice starts an\n-- account and deposits from two callers at once.\ndepositTwice :: UInt8 -> Int64\n\nlaw \"|two callers' deposits both land| is\n  definition : for all (x :: UInt8) => depositTwice x = 2 * x end for all end definition\nend law\n\n-- A supervisor starts its actors and restarts them after a crash: one for\n-- one restarts only the actor that crashed. The account restarts from its\n-- last balance (restart from reopen).\nsupervisor bank is\n  one for one\n  at most 3 restarts in 5s\n  permanent account\nend supervisor\n\n-- survivesCrash starts the bank, deposits, crashes the account, and reads\n-- its balance through the same handle.\nsurvivesCrash :: UInt8 -> Int64\n\nlaw \"|a crashed account keeps its balance| is\n  definition : for all (x :: UInt8) => survivesCrash x = x end for all end definition\nend law\n\n-- A scenario runs the actor's messages from processes that talk over\n-- channels. Some runs crash one process at a random point: a receive from a\n-- process that failed runs its or else instead of waiting forever.\nprotocol Receipt is\n  send Int64\nend protocol\n\nscenario `a deposit's receipt, or the balance if the teller fails` in account is\n  channel receipt :: Receipt\n  par\n    n <- deposit 5\n    send receipt n\n  with\n    receive receipt m or else\n      balance\n    end or else\n    expect m = 5\n  end par\nend scenario\n\n-- A mailbox has many senders and one receiver: two tellers report their\n-- deposits to one auditor, who receives both reports.\nscenario `two tellers report to one auditor` in account is\n  mailbox reports of Int64\n  par\n    n <- deposit 3\n    send reports n\n  with\n    m <- deposit 4\n    send reports m\n  with\n    receive reports first\n    receive reports second\n  end par\nend scenario\nend unit\n")
  , ("algebra.lawspec", "unit example.algebra\n\n-- Integer denotes mathematical integers. Adapter results must remain exact.\nadd           :: Integer -> Integer -> Integer\nmultiply      :: Integer -> Integer -> Integer\nnegateValue   :: Integer -> Integer\nmaximumValue  :: Integer -> Integer -> Integer\nsubtractValue :: Integer -> Integer -> Integer\ndivideLeft    :: Integer -> Integer -> Integer\ndivideRight   :: Integer -> Integer -> Integer\n\nlaw \"|addition is commutative| is\n  definition :\n    apply law \"|commutative| add\n  end definition\n\n  example \"|3 plus 5 and 5 plus 3 both produce 8| :\n    x = 3\n    y = 5\n    expect add x y = 8\n    expect add y x = 8\n  end example\n\n  example \"|addition exceeds the Int32 maximum without wrapping| :\n    x = 2147483647\n    y = 1\n    expect add x y = 2147483648\n    expect add y x = 2147483648\n  end example\n\n  example \"|addition remains exact beyond machine and safe-number bounds| :\n    x = 18446744073709551615\n    y = 2\n    expect add x y = 18446744073709551617\n    expect add y x = 18446744073709551617\n  end example\nend law\n\nlaw \"|addition is associative| is\n  definition :\n    apply law \"|associative| add\n  end definition\n\n  example \"|both groupings of 3 plus 5 plus 7 produce 15| :\n    x = 3\n    y = 5\n    z = 7\n    expect add (add x y) z = 15\n    expect add x (add y z) = 15\n  end example\nend law\n\nlaw \"|zero is left identity for addition| is\n  definition :\n    apply law \"|left identity| add 0\n  end definition\n\n  example \"|adding zero on left preserves 3| :\n    x = 3\n    expect add 0 x = 3\n  end example\nend law\n\nlaw \"|zero is right identity for addition| is\n  definition :\n    apply law \"|right identity| add 0\n  end definition\n\n  example \"|adding zero on right preserves 3| :\n    x = 3\n    expect add x 0 = 3\n  end example\nend law\n\nlaw \"|zero is two-sided identity for addition| is\n  definition :\n    apply law \"|identity| add 0\n  end definition\n\n  example \"|adding zero on both sides preserves 3| :\n    x = 3\n    expect add 0 x = 3\n    expect add x 0 = 3\n  end example\nend law\n\nlaw \"|zero absorbs multiplication left| is\n  definition :\n    apply law \"|left absorbing element| multiply 0\n  end definition\n\n  example \"|zero on left of multiplication produces zero| :\n    x = 3\n    expect multiply 0 x = 0\n  end example\nend law\n\nlaw \"|zero absorbs multiplication right| is\n  definition :\n    apply law \"|right absorbing element| multiply 0\n  end definition\n\n  example \"|zero on right of multiplication produces zero| :\n    x = 3\n    expect multiply x 0 = 0\n  end example\nend law\n\nlaw \"|zero absorbs multiplication on both sides| is\n  definition :\n    apply law \"|absorbing element| multiply 0\n  end definition\n\n  example \"|zero on both sides of multiplication produces zero| :\n    x = 3\n    expect multiply 0 x = 0\n    expect multiply x 0 = 0\n  end example\nend law\n\nlaw \"|multiplication distributes over addition left| is\n  definition :\n    apply law \"|left distributive| multiply add\n  end definition\n\n  example \"|left distribution produces 36| :\n    x = 3\n    y = 5\n    z = 7\n    expect multiply x (add y z) = 36\n    expect add (multiply x y) (multiply x z) = 36\n  end example\n\n  example \"|multiplication preserves products outside Int32| :\n    x = 2147483647\n    y = 2147483647\n    z = 1\n    expect multiply x y = 4611686014132420609\n    expect multiply x (add y z) = 4611686016279904256\n  end example\nend law\n\nlaw \"|multiplication distributes over addition right| is\n  definition :\n    apply law \"|right distributive| multiply add\n  end definition\n\n  example \"|right distribution produces 56| :\n    x = 3\n    y = 5\n    z = 7\n    expect multiply (add x y) z = 56\n    expect add (multiply x z) (multiply y z) = 56\n  end example\nend law\n\nlaw \"|multiplication distributes over addition on both sides| is\n  definition :\n    apply law \"|distributive| multiply add\n  end definition\n\n  example \"|left distribution produces 36; right distribution produces 56| :\n    x = 3\n    y = 5\n    z = 7\n    expect multiply x (add y z) = 36\n    expect add (multiply x y) (multiply x z) = 36\n    expect multiply (add x y) z = 56\n    expect add (multiply x z) (multiply y z) = 56\n  end example\nend law\n\nlaw \"|maximum is an idempotent operation| is\n  definition :\n    apply law \"|idempotent operation| maximumValue\n  end definition\n\n  example \"|the maximum of 3 and itself is 3| :\n    x = 3\n    expect maximumValue x x = 3\n  end example\nend law\n\nlaw \"|negation supplies left additive inverses| is\n  definition :\n    apply law \"|left inverse element| add negateValue 0\n  end definition\n\n  example \"|3 has inverse -3; the left inverse equation produces zero| :\n    x = 3\n    expect negateValue x = -3\n    expect add (negateValue x) x = 0\n  end example\nend law\n\nlaw \"|negation supplies right additive inverses| is\n  definition :\n    apply law \"|right inverse element| add negateValue 0\n  end definition\n\n  example \"|3 has inverse -3; the right inverse equation produces zero| :\n    x = 3\n    expect negateValue x = -3\n    expect add x (negateValue x) = 0\n  end example\nend law\n\nlaw \"|negation supplies both additive inverses| is\n  definition :\n    apply law \"|invertible| add negateValue 0\n  end definition\n\n  example \"|3 has inverse -3; the left and right inverse equation produces zero| :\n    x = 3\n    expect negateValue x = -3\n    expect add (negateValue x) x = 0\n    expect add x (negateValue x) = 0\n  end example\nend law\n\nlaw \"|subtraction has left division| is\n  definition :\n    apply law \"|left division| subtractValue divideLeft\n  end definition\n\n  example \"|left solution is -2 since 3 - (-2) = 5; reversing the operation recovers 5| :\n    x = 3\n    y = 5\n    expect divideLeft x y = -2\n    expect subtractValue x (divideLeft x y) = 5\n    expect divideLeft x (subtractValue x y) = 5\n  end example\nend law\n\nlaw \"|subtraction has right division| is\n  definition :\n    apply law \"|right division| subtractValue divideRight\n  end definition\n\n  example \"|right solution is 8 since 8 - 5 = 3; reversing the operation recovers 3| :\n    x = 3\n    y = 5\n    expect divideRight x y = 8\n    expect subtractValue (divideRight x y) y = 3\n    expect divideRight (subtractValue x y) y = 3\n  end example\nend law\n\nlaw \"|subtraction has divisible| is\n  definition :\n    apply law \"|divisible| subtractValue divideLeft divideRight\n  end definition\n\n  example \"|left solution is -2; right solution is 8; both recovery directions hold| :\n    x = 3\n    y = 5\n    expect divideLeft x y = -2\n    expect subtractValue x (divideLeft x y) = 5\n    expect divideLeft x (subtractValue x y) = 5\n    expect divideRight x y = 8\n    expect subtractValue (divideRight x y) y = 3\n    expect divideRight (subtractValue x y) y = 3\n  end example\nend law\n\nlaw \"|negation is an involution| is\n  definition :\n    apply law \"|involution| negateValue\n  end definition\n\n  example \"|negating -3 twice restores -3| :\n    x = -3\n    expect negateValue x = 3\n    expect negateValue (negateValue x) = -3\n  end example\n\n  example \"|negating the Int32 minimum produces a positive integer| :\n    x = -2147483648\n    expect negateValue x = 2147483648\n    expect negateValue (negateValue x) = -2147483648\n  end example\nend law\nend unit\n")
  , ("approvals.lawspec", "unit example.approvals\n\n-- The workflows example's approve workflow, run under the real clock. Its\n-- own unit, so the adapters can call the workflow on every target (a Haskell\n-- workflow imports its steps' module).\n\n-- Approves order n under the real clock: whether the slow order's two checks\n-- overlapped in time, which they do only when they run at the same time. Run\n-- one after the other they cannot overlap, however loaded the machine is.\nasync approvedQuickly :: Int64 -> Bool\n\nlaw \"|an all group's checks run at the same time| is\n  definition :\n    for all (n :: Int64) => approvedQuickly n = true end for all\n  end definition\n  example \"|the slow order| :\n    n = -1\n    expect approvedQuickly n = true\n  end example\nend law\n\n-- Approves order n: the messages of its failures, as the workflow reports\n-- them. Order -1's credit check finishes first, but is declared second.\nasync approvalErrors :: Int64 -> List Text\n\nlaw \"|failures are reported in declaration order| is\n  definition :\n    for all (n :: Int64) =>\n      approvalErrors n = prelude.select (n < 0) [\"no stock\", \"no credit\"] [] end for all\n  end definition\n  example \"|the slow order| :\n    n = -1\n    expect approvalErrors n = [\"no stock\", \"no credit\"]\n  end example\nend law\nend unit\n")
  , ("async_bindings.lawspec", "unit example.warehouse\n\n-- Asynchronous adapters bound to native code. Each target's bindings name a\n-- native function or method returning the target's asynchronous type (a\n-- coroutine, Promise, CompletableFuture, suspend function, Go task, Rust\n-- future or IO action); the generated bridge awaits it and converts the\n-- result.\n\n-- A price, looked up by a native asynchronous function.\nasync priceOf :: Text -> Int32\n-- The same price, computed by a native synchronous function.\nquoteOf :: Text -> Int32\n\nlaw \"|a looked-up price is the quoted price| is\n  definition : for all (sku :: Text) => priceOf sku = quoteOf sku end for all end definition\n  example \"|a free sample| :\n    sku = \"free\"\n    expect priceOf sku = 0\n  end example\nend law\n\n-- A shelf is a native object; its methods are asynchronous.\nhandle Shelf\n\nnewShelf :: Unit -> Shelf\nasync restock :: Shelf -> (amount :: Int32 where amount >= 0 && amount <= 100) -> Unit\nasync count :: Shelf -> Int64\n\nfunction modelRestock (amount :: Int32 where amount >= 0 && amount <= 100) (total :: Int64 where total >= 0 && total <= 1000000) -> Int64 is\n  total + amount\nend function\n\nfunction modelCount (total :: Int64) -> Pair Int64 Int64 is Pair total total end function\n\nmodel shelf :: shared Shelf by Int64 is\n  start newShelf ~ 0\n  restock ~ modelRestock\n  count ~ modelCount\nend model\nend unit\n")
  , ("async_fetch.lawspec", "unit example.orders\n\n-- An async adapter's result arrives later, as the target's task (a coroutine,\n-- Promise, CompletableFuture, suspend call, Go task, IO action or Future); the\n-- tests await each call where it is made, in order.\n\n-- A product's price, looked up remotely. Prices are never negative.\nasync price :: (sku :: Text) -> (r :: Int32 where r >= 0)\n-- How many are in stock.\nasync stock :: Text -> Int32\n-- A local quote of the same price.\nquote :: Text -> Int32\n\nlaw \"|prices agree with quotes| is\n  definition : for all (sku :: Text) => price sku = quote sku end for all end definition\n  example \"|a free sample| :\n    sku = \"free\"\n    expect price sku = 0\n  end example\nend law\n\n-- Two awaited calls in one clause.\nlaw \"|stock never lowers a price| is\n  definition : for all (sku :: Text) => price sku + stock sku >= stock sku end for all end definition\nend law\n\n-- An awaited call in a guard.\nlaw \"|stocked products have prices| is\n  definition : for all (sku :: Text) => stock sku > 0 implies price sku >= 0 end for all end definition\nend law\nend unit\n")
  , ("atoi_codec.lawspec", "unit example.atoi_codec\n\nitoa :: Int32 -> Text\natoi :: Text -> Int32\n\nlaw \"|itoa and then atoi yields a| is\n  definition :\n    apply law \"|round trip identity is preserved| itoa atoi\n  end definition\n\n  description :\n    \"converting an Int32 to Text with {itoa} and then back with {atoi} yields the original Int32\"\n  end description\n\n  rationale :\n    \"representing an Int32 as Text must not change its value\"\n  end rationale\n\n  example \"|negative integers use a minus sign and round-trip unchanged| :\n    x = -42\n    expect itoa x = \"-42\"\n    expect atoi (itoa x) = -42\n  end example\n\n  example \"|zero renders as 0 and round-trips unchanged| :\n    x = 0\n    expect itoa x = \"0\"\n    expect atoi (itoa x) = 0\n  end example\n\n  references :\n    \"left inverse\"\n    \"round-trip property\"\n  end references\nend law\nend unit\n")
  , ("boolean_flags.lawspec", "unit example.boolean_flags\n\nflipFlag :: Bool -> Bool\n\nlaw \"|flipping twice restores either flag| is\n  definition :\n    apply law \"|left inverse| flipFlag flipFlag\n  end definition\n\n  example \"|disabled becomes enabled and then disabled again| :\n    x = false\n    expect flipFlag x = true\n    expect flipFlag (flipFlag x) = false\n  end example\n\n  example \"|enabled becomes disabled and then enabled again| :\n    x = true\n    expect flipFlag x = false\n    expect flipFlag (flipFlag x) = true\n  end example\nend law\nend unit\n")
  , ("builtins.lawspec", "unit example.builtins\n\n-- The built-in abilities: each unit is imported like any other, and each\n-- ability's production handler is the runtime's default one.\nimport lawspec.time (Instant, advance)\nimport lawspec.randomness\nimport lawspec.host\nimport lawspec.logging (LogLevel)\nimport lawspec.concurrent\n\n-- Time. A deadline is now plus a wait; instants move by durations and are\n-- a duration apart.\nprocedure deadline (wait :: Duration where wait <= 1h) -> Instant uses Clock is now + wait end procedure\n\n-- Under the virtual clock, time moves only when told to.\nlaw \"|a deadline is as far off as the wait| using virtual clock is\n  definition :\n    for all (wait :: Duration where wait <= 1h) => (let d = deadline wait in d - now end let) = wait end for all\n  end definition\nend law\n\nlaw \"|advancing moves the virtual clock| using virtual clock is\n  definition :\n    for all (d :: Duration where d <= 1h) => (let a = now in advance d; let b = now in b - a end let end let) = d end for all\n  end definition\nend law\n\n-- Time in laws: temporal propositions check over the clock, so under the\n-- virtual clock they are deterministic.\nlaw \"|a deadline eventually passes| using virtual clock is\n  definition :\n    for all (wait :: Duration where wait <= 1s) => (let d = deadline wait in eventually within 2 s, now >= d end let) = true end for all\n  end definition\nend law\n\nlaw \"|nothing is late before its deadline| using virtual clock is\n  definition : (let d = deadline 3s in always within 2 s, now < d end let) = true end definition\nend law\n\n-- A performance budget, measured on the real clock.\nlaw \"|a deadline is quick to make| is\n  definition : for all (wait :: Duration where wait <= 1h) => deadline wait takes at most 500 ms end for all end definition\n  example \"|an hour| :\n    wait = 1h\n    expect deadline wait takes at most 500 ms\n  end example\nend law\n\n-- A native adapter gets its handlers as arguments: here the real clock.\nelapsed :: Int32 -> Duration uses Clock\n\nlaw \"|elapsed time is never negative| is\n  definition : for all (n :: Int32 where n >= 0 && n <= 3) => elapsed n >= 0ms end for all end definition\nend law\n\n-- Random draws are reproducible: the same seed gives the same draws, on\n-- every target.\nprocedure roll (sides :: Int64 where sides >= 1) -> Integer uses Random is randomBelow sides + 1 end procedure\n\nlaw \"|a seed fixes the rolls| is\n  definition :\n    for all (sides :: Int64 where sides >= 1) =>\n      handle roll sides with seededRandom end handle = handle roll sides with seededRandom end handle end for all\n  end definition\n  example \"|the first roll from seed 0| :\n    sides = 6\n    expect handle roll sides with seededRandom end handle = 6\n  end example\n  example \"|the first roll from seed 42| :\n    sides = 1000\n    expect handle roll sides with seededRandom 42 end handle = 78\n  end example\nend law\n\nlaw \"|rolls are on the die| using seeded random 42 is\n  definition :\n    for all (sides :: Int64 where sides >= 1) => (let r = roll sides in r >= 1 && r <= sides end let) = true end for all\n  end definition\nend law\n\n-- Secure draws come from SecureRandom, which a seeded source cannot answer.\ntoken :: Int32 -> Bytes uses SecureRandom\n\nlaw \"|a token has the length asked| is\n  definition : for all (n :: Int32 where n >= 0 && n <= 64) => prelude.length (token n) = n end for all end definition\nend law\n\n-- Files, the environment and ports.\nprocedure remember (note :: Bytes) -> Maybe Bytes uses FileSystem is\n  writeBytes \".lawspec-note\" note; let read = readBytes \".lawspec-note\" in removePath \".lawspec-note\"; read end let\nend procedure\n\nlaw \"|a remembered note reads back| is\n  definition : for all (note :: Bytes) => remember note = Present note end for all end definition\nend law\n\nlaw \"|an empty environment has no variables| using emptyEnvironment is\n  definition : for all (name :: Text) => environmentVariable name = Absent end for all end definition\nend law\n\nlistening :: Int32 -> Bool uses Ports\n\nlaw \"|a free port can be listened on| is\n  definition : for all (n :: Int32 where n >= 0 && n <= 2) => listening n = true end for all end definition\nend law\n\n-- Logs. A law that inspects what was logged records the log.\ncharge :: Int32 -> Bool uses Log\n\nlaw \"|a charge is logged once| using recording Log is\n  definition :\n    for all (cents :: Int32 where cents >= 0 && cents <= 1000) =>\n      (if charge cents then calls of logMessage = 1 else calls of logMessage = 0 end if) = true end for all\n  end definition\nend law\n\nprocedure traced (n :: Int32) -> Int32 uses Trace, Async is traceEvent \"traced\"; pause; n end procedure\n\nlaw \"|tracing keeps the value| is\n  definition : for all (n :: Int32) => traced n = n end for all end definition\nend law\nend unit\n")
  , ("calendar.lawspec", "unit guide.calendar\n\nimport lawspec.calendar (Date, Weekday, CivilDate, civilOf, dateOf, weekdayOf,\n  addDays, daysBetween, weekdayNumber, daysFromCivil, isLeapYear, daysInMonth)\n\n-- The next day a weekly meeting falls on, on or after a date.\nfunction nextOn (weekday :: Weekday) (date :: Date) -> Maybe Date is\n  addDays date\n    (prelude.rem (weekdayNumber weekday - weekdayNumber (weekdayOf date) + 7) 7)\nend function\n\nlaw \"|a date's civil form names that date| is\n  definition:\n    for all (date :: Date) =>\n      (let civil = civilOf date in\n        dateOf civil.year civil.month civil.day = Present date end let)\n    end for all\n  end definition\n  example \"|the epoch| :\n    date = Date 0\n    expect civilOf date = CivilDate record{year = 1970, month = 1, day = 1}\n  end example\n  example \"|a leap day| :\n    date = Date 11016\n    expect civilOf date = CivilDate record{year = 2000, month = 2, day = 29}\n  end example\nend law\n\nlaw \"|the first and last dates| is\n  definition:\n    dateOf 1 1 1 = Present (Date (-719162)) and\n      dateOf 9999 12 31 = Present (Date 2932896) and dateOf 0 12 31 = Absent and\n      dateOf 10000 1 1 = Absent and dateOf 2026 2 29 = Absent and\n      dateOf 2026 11 12 = Present (Date 20769)\n  end definition\nend law\n\nlaw \"|the epoch was a Thursday| is\n  definition:\n    weekdayOf (Date 0) = Thursday and weekdayOf (Date (-719162)) = Monday and\n      weekdayOf (Date 2932896) = Friday\n  end definition\nend law\n\nlaw \"|a week later is the same weekday| is\n  definition:\n    for all (date :: Date where valueOfDate date <= 2932889) =>\n      weekdayOf (Date (valueOfDate date + 7)) = weekdayOf date\n    end for all\n  end definition\nend law\n\nlaw \"|a year has 365 days, or 366 when it is a leap year| is\n  definition:\n    for all (year :: Integer where year >= 1 && year <= 9998) =>\n      daysFromCivil (year + 1) 1 1 - daysFromCivil year 1 1 =\n        (if isLeapYear year then 366 else 365 end if)\n    end for all\n  end definition\nend law\n\nlaw \"|a month's last day is followed by the first of the next month| is\n  definition:\n    for all (year :: Integer where year >= 1 && year <= 9999)\n        (month :: Integer where month >= 1 && month <= 11) =>\n      daysFromCivil year (month + 1) 1 - daysFromCivil year month 1 =\n        daysInMonth year month\n    end for all\n  end definition\nend law\n\nlaw \"|adding days moves a date by that many days| is\n  definition:\n    for all (date :: Date) (days :: Integer where days >= -30 && days <= 30) =>\n      first matching case of addDays date days:\n        when Absent then\n          valueOfDate date + days < -719162 or valueOfDate date + days > 2932896\n        when Present moved then daysBetween moved date = days\n      end case\n    end for all\n  end definition\nend law\n\nlaw \"|the next meeting is on its weekday, within a week| is\n  definition:\n    for all (date :: Date where valueOfDate date <= 2932890) =>\n      first matching case of nextOn Friday date:\n        when Absent then false\n        when Present meeting then\n          weekdayOf meeting = Friday and daysBetween meeting date >= 0 and\n            daysBetween meeting date <= 6\n      end case\n    end for all\n  end definition\n  example \"|from a Thursday| :\n    date = Date 20769\n    expect nextOn Friday date = Present (Date 20770)\n  end example\nend law\nend unit\n")
  , ("canonical_url.lawspec", "unit example.canonical_url\n\ncanonicalize :: Text -> Text\n\nlaw \"|canonicalization reaches a fixed point| is\n  definition :\n    apply law \"|idempotent| canonicalize\n  end definition\n  description :\n    \"{canonicalize} removes trailing slashes until the result is stable\"\n  end description\n  example \"|all trailing slashes are removed in one pass| :\n    x = \"https://example.com/path///\"\n    expect canonicalize x = \"https://example.com/path\"\n  end example\n  example \"|a URL without trailing slashes stays unchanged| :\n    x = \"https://example.com/path\"\n    expect canonicalize x = \"https://example.com/path\"\n  end example\n  example \"|empty input remains empty| :\n    x = \"\"\n    expect canonicalize x = \"\"\n  end example\nend law\nend unit\n")
  , ("collections.lawspec", "unit example.collections\n\n-- Built-in collections: Set and KeyVal keep their elements and keys in the\n-- portable total order, without repeats; Queue, Stack and Deque keep their\n-- items in order. prelude.setOf, keyValOf, queueOf, stackOf and dequeOf\n-- build them from lists.\n\n-- The distinct values of a list.\ndedupe :: List Int32 -> SortedSet Int32\n-- How many times each word occurs.\nwordCounts :: List Text -> KeyVal Text Integer\n-- Enqueue every value, first to last.\nfifo :: List Int8 -> Queue Int8\n-- Push every value, first to last: the last is on top.\nlifo :: List Int8 -> Stack Int8\n-- Move the front item to the back.\nrotate :: Deque Int8 -> Deque Int8\n-- The distinct lists among some lists: structured elements.\ndistinctRows :: List (List Int8) -> SortedSet (List Int8)\n\nfunction countWords (words :: List Text) (counts :: KeyVal Text Integer) -> KeyVal Text Integer is\n  first matching case of words :\n  when Nil then counts\n  when Cons w rest then first matching case of prelude.lookup w counts :\n    when Absent then countWords rest (prelude.put w 1 counts)\n    when Present n then countWords rest (prelude.put w ((n + 1) :: Integer) counts)\n    end case\n  end case\nend function\n\nfunction rotated (d :: Deque Int8) -> Deque Int8 is\n  first matching case of prelude.peekFront d :\n  when Absent then d\n  when Present x then prelude.pushBack x (prelude.popFront d)\n  end case\nend function\n\nlaw \"|dedupe agrees with setOf| is\n  definition : for all (xs :: List Int32) => dedupe xs = prelude.sortedSetOf xs end for all end definition\nend law\n\nlaw \"|distinct rows agree with setOf| is\n  definition : for all (rows :: List (List Int8)) => distinctRows rows = prelude.sortedSetOf rows end for all end definition\nend law\n\nlaw \"|word counts agree with the definition| is\n  definition :\n    for all (words :: List Text) => wordCounts words = countWords words (prelude.keyValOf []) end for all\n  end definition\nend law\n\nlaw \"|the queue's front is the first value| is\n  definition :\n    for all (x :: Int8) (xs :: List Int8) => prelude.front (fifo (Cons x xs)) = Present x end for all\n  end definition\nend law\n\nlaw \"|the stack's top is the last value| is\n  definition :\n    for all (x :: Int8) (xs :: List Int8) => prelude.peek (lifo [x]) = Present x end for all\n  end definition\nend law\n\nlaw \"|fifo keeps the order| is\n  definition : for all (xs :: List Int8) => prelude.toList (fifo xs) = xs end for all end definition\nend law\n\nlaw \"|rotate agrees with the definition| is\n  definition : for all (d :: Deque Int8) => rotate d = rotated d end for all end definition\nend law\n\nlaw \"|union is commutative| is\n  definition :\n    for all (s :: SortedSet Int32) (t :: SortedSet Int32) => prelude.sortedSetUnion s t = prelude.sortedSetUnion t s end for all\n  end definition\nend law\n\nlaw \"|a removed value is no member| is\n  definition :\n    for all (x :: Int32) (s :: SortedSet Int32) => prelude.sortedSetMember x (prelude.sortedSetRemove x s) = false end for all\n  end definition\nend law\n\nlaw \"|an inserted value is a member| is\n  definition :\n    for all (x :: Int32) (s :: SortedSet Int32) => prelude.sortedSetMember x (prelude.sortedSetInsert x s) = true end for all\n  end definition\nend law\n\nlaw \"|intersection and difference split a set| is\n  definition :\n    for all (s :: SortedSet Int32) (t :: SortedSet Int32) =>\n      prelude.sortedSetUnion (prelude.sortedSetIntersection s t) (prelude.sortedSetDifference s t) = s end for all\n  end definition\nend law\n\nlaw \"|the latest put wins| is\n  definition :\n    for all (k :: Text) (v :: Integer) (w :: Integer) (m :: KeyVal Text Integer) =>\n      prelude.lookup k (prelude.put k w (prelude.put k v m)) = Present w end for all\n  end definition\nend law\n\nlaw \"|a deleted key is absent| is\n  definition :\n    for all (k :: Text) (m :: KeyVal Text Integer) => prelude.lookup k (prelude.delete k m) = Absent end for all\n  end definition\nend law\n\nlaw \"|keys are distinct| is\n  definition :\n    for all (m :: KeyVal Text Integer) => prelude.size (prelude.sortedSetOf (prelude.keys m)) = prelude.size m end for all\n  end definition\nend law\n\nlaw \"|popping the back leaves the rest| is\n  definition :\n    for all (x :: Int8) (d :: Deque Int8) => prelude.popBack (prelude.pushBack x d) = d end for all\n  end definition\nend law\n\nlaw \"|the empty stack stays empty| is\n  definition :\n    for all (x :: Int8) => prelude.isEmpty (prelude.pop (prelude.stackOf [x])) = true end for all\n  end definition\nend law\n\n-- Size-indexed stacks and queues: a pop, top, dequeue or front needs a\n-- non-empty one (SizedStack (n + 1) a), so it can never fail.\nlaw \"|the top is what was pushed| is\n  definition :\n    for all (x :: Int8) (s :: SizedStack 2 Int8) => prelude.sizedTop (prelude.sizedPush x s) = x end for all\n  end definition\nend law\n\nlaw \"|popping undoes a push| is\n  definition :\n    for all (s :: SizedStack 3 Int8) => prelude.sizedStackItems (prelude.sizedPop (prelude.sizedPush 7 s)) = prelude.sizedStackItems s end for all\n  end definition\nend law\n\nlaw \"|a sized queue keeps arrival order| is\n  definition :\n    for all (x :: Int8) (y :: Int8) => prelude.sizedFront (prelude.sizedEnqueue y (prelude.sizedEnqueue x SizedQueueEmpty)) = x end for all\n  end definition\nend law\n\n-- Text keys and items order by code point on every target. U+1F600 follows\n-- U+FF21 by code point, though in UTF-16 its first surrogate (U+D83D)\n-- precedes U+FF21, so a target ordering text by UTF-16 unit fails here.\n\n-- The items of a set of words, in the set's order.\nfunction orderedItems (s :: SortedSet Text) -> List Text is\n  prelude.toList s\nend function\n\n-- The distinct words, in the order of the keys that count them.\nfunction countedKeys (words :: List Text) -> List Text is\n  prelude.keys (countWords words (prelude.keyValOf []))\nend function\n\nlaw \"|text keys and items order by code point| is\n  definition :\n    for all (words :: List Text) => countedKeys words = orderedItems (prelude.sortedSetOf words) end for all\n  end definition\n  example \"|a fullwidth letter precedes an emoji| :\n    words = [\"\x1f600\&\", \"\xff21\&\", \"\x1f600\&\"]\n    expect countedKeys words = [\"\xff21\&\", \"\x1f600\&\"]\n    expect orderedItems (prelude.sortedSetOf words) = [\"\xff21\&\", \"\x1f600\&\"]\n  end example\nend law\n\n-- How one set of words orders against another.\nfunction compareSets (s :: SortedSet Text) (t :: SortedSet Text) -> Ordering is\n  prelude.compare s t\nend function\n\nlaw \"|sets of text order as their items do| is\n  definition :\n    for all (xs :: List Text) (ys :: List Text) =>\n      compareSets (prelude.sortedSetOf xs) (prelude.sortedSetOf ys) = prelude.compare (orderedItems (prelude.sortedSetOf xs)) (orderedItems (prelude.sortedSetOf ys)) end for all\n  end definition\n  example \"|a set led by a fullwidth letter precedes one led by a later letter| :\n    xs = [\"\x1f600\&\", \"\xff21\&\"]\n    ys = [\"\xff22\&\"]\n    expect compareSets (prelude.sortedSetOf xs) (prelude.sortedSetOf ys) = Less\n  end example\nend law\nend unit\n")
  , ("composition.lawspec", "unit example.composition\n\n-- A log store seen through two abilities, Logs and Reader. One spec handler\n-- answers both from one state, and a set of handlers runs every law over\n-- the spec handlers together. The native handlers share a Store: each case\n-- opens one, and every native handler of the case is made with it.\n\ntype Problem is one of | UnknownLog | EmptyRecord end type\n\ntype Log is a record{\n\n    records :: List Text\n    appends :: Int64}\nend type\n\nhandle Store\n\nopenStore :: Unit -> Store\ncloseStore :: Store -> Unit\n\nresource Store is\n  acquire is openStore unitValue end acquire\n  release store is closeStore store end release\nend resource\n\nability Logs with Store is\n  create :: Text -> Unit\n  append :: Text -> Text -> Int64 fails with Problem\nlaws\n  law \"|a new log takes its first record at offset zero| is\n    definition : for all (t :: Text) (r :: Text where r != \"\") => (create t; append t r) = 0 end for all end definition\n  end law\n  law \"|an unknown log refuses records| is\n    definition : for all (t :: Text) (r :: Text) => append t r fails with UnknownLog end for all end definition\n  end law\nend laws\nend ability\n\nability Reader with Store is\n  size :: Text -> Maybe Int64\nlaws\n  law \"|an unknown log has no size| is\n    definition : for all (t :: Text) => size t = Absent end for all end definition\n  end law\nend laws\nend ability\n\n-- A client over Logs: it keeps the offset of its last write.\nability Writer with Store is\n  write :: Text -> Text -> Bool\n  lastOffset :: Maybe Int64\nlaws\n  law \"|a write to a new log is read back| is\n    definition :\n      for all (t :: Text) (r :: Text where r != \"\") => (create t; write t r; size t) = Present 1 end for all\n    end definition\n  end law\nend laws\nend ability\n\nfunction empty (u :: Unit) -> KeyVal Text Log is prelude.keyValOf [] end function\n\n-- One state for both abilities. It starts from a computed value, and the\n-- clause for append updates it in one branch only.\nhandler store for Logs, Reader with state logs :: KeyVal Text Log start empty unitValue is\n  operation create t is ~logs := prelude.put t (Log record{ records = [] , appends = 0}) logs; unitValue end operation\n  operation append t r is\n    first matching case of prelude.lookup t logs :\n    when Absent then raise UnknownLog\n    when Present log then\n        if r = \"\" then raise EmptyRecord else\n          (~logs := prelude.put t (log with records = Cons r log.records, appends = prelude.saturating (log.appends + 1)) logs;\n           log.appends) end if\n    end case\n  end operation\n  operation size t is\n    first matching case of prelude.lookup t logs :\n    when Absent then Absent\n    when Present log then Present log.appends\n    end case\n  end operation\nend handler\n\n-- A clause may be a definition that gives Pair result state: `op by f`.\nprocedure writeTo (t :: Text) (r :: Text) (last :: Maybe Int64) -> Pair Bool (Maybe Int64) uses Logs is\n  first matching case of prelude.attempt (append t r) :\n  when Left problem then Pair false last\n  when Right offset then Pair true (Present offset)\n  end case\nend procedure\n\nfunction lastOf (last :: Maybe Int64) -> Pair (Maybe Int64) (Maybe Int64) is Pair last last end function\n\nhandler logWriter for Writer with state last :: Maybe Int64 start Absent is\n  operation write by writeTo end operation\n  operation lastOffset by lastOf end operation\nend handler\n\n-- The reference composition: every ability answered by spec handlers.\nhandlers reference is store, logWriter end handlers\n\nlaw \"|sizes count records| is\n  definition :\n    for all (t :: Text) (a :: Text where a != \"\") (b :: Text where b != \"\") =>\n      (create t; append t a; append t b; size t) = Present 2 end for all\n  end definition\nend law\n\nlaw \"|a writer remembers where it wrote| is\n  definition :\n    for all (t :: Text) (r :: Text where r != \"\") => (create t; write t r; lastOffset) = Present 0 end for all\n  end definition\nend law\nend unit\n")
  , ("concurrent_collections.lawspec", "unit example.concurrent\n\n-- Concurrent collections checked against the built-in ones they behave\n-- like. Each adapter uses its target's own concurrent structures; LawSpec\n-- runs the commands in sequence and at the same time, and every history\n-- must be linearizable. Sets and maps are checked key by key.\n\ntype WorkQueue is a record{  id :: Int32} end type\n\nnewQueue :: Unit -> WorkQueue\nasync offer :: WorkQueue -> Int32 -> Unit\nasync poll :: WorkQueue -> Maybe Int32\nasync queueSize :: WorkQueue -> Int64\n\nmodel queue :: shared WorkQueue behaves like Queue Int32 is\n  start newQueue\n  offer as offer\n  poll as poll\n  queueSize as size\nend model\n\ntype Tags is a record{  id :: Int32} end type\n\nnewTags :: Unit -> Tags\nasync tag :: Tags -> Int32 -> Bool\nasync untag :: Tags -> Int32 -> Bool\nasync tagged :: Tags -> Int32 -> Bool\n\nmodel tags :: shared Tags behaves like SortedSet Int32 is\n  start newTags\n  tag as add\n  untag as remove\n  tagged as contains\nend model\n\ntype Cache is a record{  id :: Int32} end type\n\nnewCache :: Unit -> Cache\nasync store :: Cache -> Int8 -> Int64 -> Maybe Int64\nasync fetch :: Cache -> Int8 -> Maybe Int64\nasync evict :: Cache -> Int8 -> Maybe Int64\n\nmodel cache :: shared Cache behaves like KeyVal Int8 Int64 is\n  start newCache\n  store as put\n  fetch as get\n  evict as remove\nend model\nend unit\n")
  , ("consistency.lawspec", "unit example.consistency\n\n-- Weaker consistency for replicated state. A page-view counter keeps one\n-- replica per caller: a hit counts on the caller's replica and returns what\n-- that replica has seen, so callers see stale totals, and the total is the\n-- sum of the replicas. Its histories are not linearizable, but once every\n-- hit is done the total must count them all: it is eventually consistent.\ntype Views is a record{  id :: Int32} end type\n\nnewViews :: Unit -> Views\nhit :: Views -> Int64\ntotal :: Views -> Int64\n\nfunction modelHit (n :: Int64 where n >= 0 && n <= 1000000) -> Pair Int64 Int64 is Pair (n + 1) (n + 1) end function\n\nmodel views :: shared Views by Int64 is\n  consistency eventual\n  start newViews ~ 0\n  hit ~ modelHit\n  abstract total\nend model\nend unit\n")
  , ("contracts.lawspec", "unit example.contracts\n\n-- Shapes contract importers write: handlers whose clauses fail, handlers\n-- over Bytes and Text, refined records, and handlers named like their\n-- abilities.\n\ntype Refusal is one of | Negative | Empty end type\n\nprocedure bump (n :: Int64) (total :: Int64) -> Pair Int64 Int64 fails with Refusal is\n  if n < 0 then raise Negative else\n    if total > 1000000 || n > 1000000 then Pair total total else Pair (prelude.Int64 (total + n)) (prelude.Int64 (total + n)) end if end if\nend procedure\n\n-- A definition that may fail but does not.\nprocedure peek (total :: Int64) -> Pair Int64 Int64 fails with Refusal is Pair total total end procedure\n\nability Counter is\n  add :: Int64 -> Int64 fails with Refusal\n  current :: Int64 fails with Refusal\nend ability\n\n-- Named like its ability.\nhandler counter for Counter with state total :: Int64 start 0 is\n  operation add by bump end operation\n  operation current by peek end operation\nend handler\n\n-- A state with no typed form keeps this handler on the dynamic path.\ntype Scaled is a record{  count :: Int64 scale :: Float64} end type\n\nprocedure bumpScaled (n :: Int64) (s :: Scaled) -> Pair Int64 Scaled fails with Refusal is\n  if n < 0 then raise Negative else\n    if s.count > 1000000 || n > 1000000 then Pair s.count s else\n      Pair (prelude.Int64 (s.count + n)) (s with count = prelude.Int64 (s.count + n)) end if end if\nend procedure\n\nprocedure peekScaled (s :: Scaled) -> Pair Int64 Scaled fails with Refusal is Pair s.count s end procedure\n\nhandler scaledCounter for Counter with state s :: Scaled start Scaled record{ count = 0 , scale = 1.0} is\n  operation add by bumpScaled end operation\n  operation current by peekScaled end operation\nend handler\n\n-- Bytes and Text inside handler clauses, on both paths.\nability Codec is\n  octetCount :: Text -> Int64\n  label :: Text -> Int32 -> Text\nend ability\n\nhandler codec for Codec is\n  operation octetCount t is prelude.length (prelude.octets (prelude.utf8 t)) end operation\n  operation label t n is prelude.join \"-\" [t, prelude.textOf n] ++ prelude.slice 0 0 t end operation\nend handler\n\nhandler scaledCodec for Codec with state s :: Float64 start 1.0 is\n  operation octetCount t is prelude.length (prelude.bytesOf (prelude.octets (prelude.utf8 t))) end operation\n  operation label t n is prelude.take (prelude.length t + 9) (t ++ \"-\" ++ prelude.textOf n) end operation\nend handler\n\n-- A failed operation leaves the handler's state as it was, on the typed\n-- path (counter) and the dynamic one (scaledCounter).\nlaw \"|a refused add changes nothing| using counter is\n  definition :\n    for all (n :: Int64 where n >= 0 && n <= 1000) =>\n      (let refused = prelude.attempt (add (0 - 1)) in add n end let) = n end for all\n  end definition\nend law\n\nlaw \"|a refused add changes nothing, dynamically| using scaledCounter is\n  definition :\n    for all (n :: Int64 where n >= 0 && n <= 1000) =>\n      (let refused = prelude.attempt (add (0 - 1)) in add n end let) = n end for all\n  end definition\nend law\n\nlaw \"|a text's octets count its UTF-8 bytes| using codec is\n  definition :\n    for all (n :: Int32 where n >= 0 && n <= 1000) =>\n      octetCount (prelude.textOf n ++ \"\xe9\&\") = prelude.length (prelude.textOf n) + 2 end for all\n  end definition\nend law\n\nlaw \"|a text's octets count its UTF-8 bytes, dynamically| using scaledCodec is\n  definition :\n    for all (n :: Int32 where n >= 0 && n <= 1000) =>\n      octetCount (prelude.textOf n ++ \"\xe9\&\") = prelude.length (prelude.textOf n) + 2 end for all\n  end definition\nend law\n\nlaw \"|a label joins its parts| using codec is\n  definition : label \"member\" 3 = \"member-3\" end definition\nend law\n\nlaw \"|a label joins its parts, dynamically| using scaledCodec is\n  definition : label \"member\" 3 = \"member-3\" end definition\nend law\n\n-- Refined records.\ntype Pet is a record{\n\n    id :: Maybe Int64\n    name :: (v :: Text where v matches regex \"[a-z]+\")}\nend type\n\nfunction validName (name :: Text) -> Bool is name matches regex \"[a-z]+\" end function\n\ntype Badge is a record{\n\n    label :: (v :: Text where validName v)}\nend type\n\nfunction withId (body :: Pet) (key :: Int64) -> Pet is body with id = Present key end function\n\nfunction validPet (p :: Pet) -> Bool is p.name matches regex \"[a-z]{2,8}\" end function\n\nlaw \"|an id is set by a record update| is\n  definition :\n    for all (p :: Pet where validPet p) (key :: Int64) => (withId p key).id = Present key and (withId p key).name = p.name end for all\n  end definition\nend law\n\nlaw \"|a badge keeps its label| is\n  definition : for all (t :: Badge) => validName t.label = true end for all end definition\nend law\nend unit\n")
  , ("crypto.lawspec", "unit example.crypto\n\n-- Post-quantum cryptography by default: ML-KEM-768 key exchange, ML-DSA-65\n-- signatures, SHA3-256, and AES-256-GCM. Their laws hold for every lawful\n-- handler; the defaults are also checked against NIST's vectors.\nimport lawspec.crypto (ExchangeKeyPair, ExchangePublicKey, Encapsulated, SigningKeyPair)\n\n-- A handshake from the building blocks. The server signs its exchange key\n-- with its long-term key; the client checks the signature, encapsulates a\n-- secret to the exchange key, and both sides derive the same AEAD key from\n-- it. The client's message then crosses sealed.\nprocedure handshake (message :: Bytes) (context :: Bytes) -> Maybe Bytes uses KeyExchange, Signature, Aead is\n  first matching case of signingKeyPair :\n  when SigningKeyPair verifying signing then\n      (first matching case of exchangeKeyPair :\n       when ExchangeKeyPair public secret then\n           (let offer = sign signing (valueOfExchangePublicKey public) in\n            if verify verifying (valueOfExchangePublicKey public) offer then\n              (first matching case of encapsulate public :\n               when Encapsulated sent shared then\n                   (let client = deriveAeadKey shared context in\n                    let server = deriveAeadKey (decapsulate secret sent) context in\n                    unseal server (seal client message context) context end let end let)\n               end case)\n            else Absent end if end let)\n       end case)\n  end case\nend procedure\n\nlaw \"|a handshake carries the message| is\n  definition : for all (message :: Bytes) (context :: Bytes) => handshake message context = Present message end for all end definition\nend law\n\n-- A native adapter: a short fingerprint of a public key, from its SHA3-256\n-- digest.\nfingerprint :: Bytes -> Bytes uses Hash\n\nlaw \"|a fingerprint is 8 bytes| is\n  definition : for all (key :: Bytes) => prelude.length (fingerprint key) = 8 end for all end definition\nend law\n\nlaw \"|a key has one fingerprint| is\n  definition : for all (key :: Bytes) => fingerprint key = fingerprint key end for all end definition\nend law\n\n-- A native adapter that seals with a fresh key and opens again.\nroundTrip :: Bytes -> Bool uses Aead\n\nlaw \"|sealed messages open| is\n  definition : for all (message :: Bytes) => roundTrip message = true end for all end definition\nend law\nend unit\n")
  , ("ctc.lawspec", "unit tensorflow.ctc\n\n  type Frame is one of\n    | Blank\n    | H\n    | E\n    | L\n    | O\n  end type\n\n  function decodeAfter\n    (previous of type Frame)\n    (frames of type List Frame) -> List Frame is\n    first matching case of frames:\n      when Nil then []\n      when Cons Blank remaining then\n        decodeAfter Blank remaining\n      when Cons frame remaining then\n        if frame = previous then\n          decodeAfter frame remaining\n        else\n          Cons frame (decodeAfter frame remaining)\n        end if\n    end case\n  end function\n\n  function \"|decode frames| (frames of type List Frame) -> List Frame is\n    decodeAfter Blank frames\n  end function\n\n  function encodeFrames (letters of type List Frame) -> List Frame is\n    first matching case of letters:\n      when Nil then []\n      when Cons letter remaining then\n        Cons letter (Cons Blank (encodeFrames remaining))\n    end case\n  end function\n\n  law \"|empty input produces empty output| is\n    definition:\n      \"|decode frames| [] must be ([] :: List Frame)\n    end definition\n  end law\n\n  law \"|a single letter survives| is\n    definition:\n      for all (letter of type Frame) =>\n        letter != Blank implies\n          \"|decode frames| [letter] must be [letter]\n      end for all\n    end definition\n  end law\n\n  law \"|decoded output contains no blanks| is\n    description:\n      \"Blanks separate repeated letters but never appear in decoded output.\"\n    end description\n    definition:\n      for all (frames of type List Frame) =>\n        not (Blank in \"|decode frames| frames)\n      end for all\n    end definition\n    expect \"|decode frames| frames = expected\n    in table (frames, expected):\n      row [], []\n      row [L, L], [L]\n      row [L, Blank, L], [L, L]\n      row [Blank, Blank], []\n      row [H, H, E, L, L, Blank, L, O, O], [H, E, L, L, O]\n    end table\n  end law\n\n  law \"|padding with blanks changes nothing| is\n    definition:\n      for all (frames of type List Frame) =>\n        \"|decode frames| ([Blank] ++ frames ++ [Blank])\n          must be \"|decode frames| frames\n      end for all\n    end definition\n  end law\n\n  law \"|repeating a frame changes nothing| is\n    definition:\n      for all\n        (before of type List Frame)\n        (frame of type Frame)\n        (after of type List Frame) =>\n        \"|decode frames| (before ++ [frame, frame] ++ after)\n          must be \"|decode frames| (before ++ [frame] ++ after)\n      end for all\n    end definition\n  end law\n\n  law \"|a blank preserves a doubled letter| is\n    definition:\n      for all (letter of type Frame) =>\n        letter != Blank implies\n          \"|decode frames| [letter, Blank, letter] must be [letter, letter]\n      end for all\n    end definition\n  end law\n\n  law \"|distinct letters retain their order| is\n    definition:\n      for all (left of type Frame) (right of type Frame) =>\n        left != Blank and right != Blank and left != right implies\n          \"|decode frames| [left, right] must be [left, right]\n      end for all\n    end definition\n  end law\n\n  law \"|a blank separates independently decoded segments| is\n    definition:\n      for all (left of type List Frame) (right of type List Frame) =>\n        \"|decode frames| (left ++ [Blank] ++ right) must be\n          (\"|decode frames| left) ++ (\"|decode frames| right)\n      end for all\n    end definition\n  end law\n\n  law \"|decoding never lengthens the input| is\n    definition:\n      for all (frames of type List Frame) =>\n        prelude.length (\"|decode frames| frames) <= prelude.length frames\n      end for all\n    end definition\n  end law\n\n  law \"|every blank-free output has an encoding| is\n    description:\n      \"Every sequence of letters can be represented, including doubled letters.\"\n    end description\n    definition:\n      for all (letters of type List Frame) =>\n        not (Blank in letters) implies\n          there exists (frames of type List Frame) such that\n            \"|decode frames| frames must be letters\n          end exists\n      end for all\n    end definition\n  end law\n\n  harness tensorflow.ctc.testing for tensorflow.ctc is\n    for law \"|every blank-free output has an encoding|\n      witness encodeFrames letters for letters.frames\n    end for law\n  end harness\nend unit\n")
  , ("currying.lawspec", "unit example.currying\n\nsumFour :: Integer -> Integer -> Integer -> Integer -> Integer\nformat  :: Text -> Bool -> Int32 -> Text -> Text\nreferenceFormat :: Text -> Bool -> Int32 -> Text -> Text\ntrim    :: Text -> Text\n\nlaw \"|a four-argument function partially applied twice is commutative| is\n  definition :\n    apply law \"|commutative| (sumFour 1 2)\n  end definition\n\n  example \"|the fixed 1 and 2 plus 3 and 4 sum to 10 in either order| :\n    x = 3\n    y = 4\n    expect sumFour 1 2 x y = 10\n    expect sumFour 1 2 y x = 10\n  end example\nend law\n\nlaw \"|staged formatter|\n  (render :: Int32 -> Text -> Text)\n  (reference :: Int32 -> Text -> Text)\nis\n  definition :\n    for all (port :: Int32) (suffix :: Text) =>\n      render port suffix = reference port suffix end for all\n  end definition\nend law\n\nlaw \"|partial application preserves heterogeneous argument order| is\n  definition :\n    apply law \"|staged formatter| (format \"port:\" true) (referenceFormat \"port:\" true)\n  end definition\n\n  example \"|port 443 with a tcp suffix formats as port:443/tcp| :\n    port = 443\n    suffix = \"/tcp\"\n    expect format \"port:\" true port suffix = \"port:443/tcp\"\n    expect referenceFormat \"port:\" true port suffix = \"port:443/tcp\"\n  end example\n\n  example \"|a disabled numeric field keeps the prefix and suffix| :\n    port = 443\n    suffix = \"/tcp\"\n    expect format \"port:\" false port suffix = \"port:/tcp\"\n    expect referenceFormat \"port:\" false port suffix = \"port:/tcp\"\n  end example\nend law\n\nlaw \"|composition accepts a partially applied function| is\n  definition :\n    apply law \"|equivalent| ((format \"port:\" true 443) . trim) ((referenceFormat \"port:\" true 443) . trim)\n  end definition\n\n  example \"|trim runs before the remaining formatter argument| :\n    x = \"  /tcp  \"\n    expect ((format \"port:\" true 443) . trim) x = \"port:443/tcp\"\n  end example\nend law\nend unit\n")
  , ("data_types.lawspec", "unit example.data_types\n\ntype Pair (a :: Type) (b :: Type) is a record{\n\n    first :: a\n    second :: b}\nend type\n\ntype Tree (a :: Type) is one of\n  Leaf  of type a\n  Branch  of type List (Tree a)\nend type\n\nlaw \"|products preserve every field| is\n  definition :\n    for all (pair :: Pair Int8 Bool) =>\n      (first matching case of pair :\n        when Pair record{ first = first , second = second} then Pair record{ first = first , second = second}\n      end case) = pair end for all\n  end definition\n  example \"|maximum integer and false| :\n    pair = Pair record{ first = 127 , second = false}\n    expect pair = Pair record{ first = 127 , second = false}\n  end example\nend law\n\nlaw \"|sums preserve constructor identity and payloads| is\n  definition :\n    for all (tree :: Tree Int8) =>\n      (first matching case of tree :\n        when Leaf value then Leaf value\n        when Branch children then Branch children\n      end case) = tree end for all\n  end definition\n  example \"|nested branches| :\n    tree = Branch [Leaf 127, Branch [], Leaf -128]\n    expect tree = Branch [Leaf 127, Branch [], Leaf -128]\n  end example\nend law\n\n\n-- A refined type argument constrains the corresponding stored fields. This\n-- predicate becomes a scoped Core traversal, shared by all eight backends.\nrefinement Positive is (value :: Int8 where value > 0) end refinement\n\nfunction positivePair (value :: Positive) -> Pair Positive Bool is\n  Pair record{ first = value , second = true}\nend function\n\nfunction reciprocalFirst (pair :: Pair Positive Bool) -> Rational is\n  first matching case of pair :\n    when Pair record{ first = first , second = second} then 1 / first\n  end case\nend function\n\nlaw \"|named payload contracts justify exact division| is\n  definition :\n    for all (value :: Positive) =>\n      reciprocalFirst (positivePair value) = 1 / value end for all\n  end definition\n  example \"|one half| :\n    value = 2\n    expect positivePair value = Pair record{ first = 2 , second = true}\n    expect reciprocalFirst (positivePair value) = rational(1, 2)\n  end example\nend law\nend unit\n")
  , ("distribution.lawspec", "unit example.distribution\n\n-- Nodes are secure: this import brings the secure network handler (node\n-- identities, the post-quantum handshake, sealed frames) and its crypto\n-- libraries. Without it, only the in-memory transport made for tests can\n-- make a node.\nimport lawspec.network\n\n-- Distribution. Nodes reach each other's actors, channels and checked\n-- definitions over a transport: in memory (with faults, for testing), TCP or\n-- HTTP. Values cross in the canonical wire encoding, the same bytes on every\n-- target, so a node on one target can talk to a node on another.\n\n-- The wire encoding's conformance vectors: values generated from a type\n-- descriptor and a seed, then encoded, in hexadecimal.\nencoded :: Text -> UInt64 -> Int32 -> Int32 -> List Text\nroundTrips :: Text -> UInt64 -> Int32 -> Int32 -> Bool\n\nlaw \"|integers on the wire| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (encoded \"(int Integer _ _)\" seed 4 4) = 4 end for all\n  end definition\n  example \"|seed 7| :\n    seed = 7\n    expect encoded \"(int Integer _ _)\" seed 4 4 = [\"9ddc4f\", \"eefb17\", \"8fc703\", \"8ee709\"]\n    expect encoded \"(int Int8 -128 127)\" 42 4 5 = [\"f901\", \"28\", \"00\", \"48\", \"5c\"]\n  end example\nend law\n\nlaw \"|text, lists, Maybe and Either on the wire| is\n  definition :\n    for all (seed :: UInt64) => roundTrips \"(list (maybe (either (int UInt8 0 255) (text))))\" seed 4 8 = true end for all\n  end definition\n  example \"|vectors| :\n    seed = 3\n    expect encoded \"(text)\" seed 4 3 = [\"037b5b2c\", \"0134\", \"024d54\"]\n    expect encoded \"(list (maybe (bool)))\" 5 3 3 = [\"02000101\", \"0100\", \"010100\"]\n    expect encoded \"(either (int UInt8 0 255) (text))\" 9 3 4 = [\"00ec02\", \"0000\", \"00d201\", \"0100\"]\n  end example\nend law\n\nlaw \"|data types on the wire| is\n  definition :\n    for all (seed :: UInt64) => roundTrips \"(data Shape (ctor Shape::Circle (int Int32 0 100)) (ctor Shape::Box (int Int32 0 100) (int Int32 0 100)) (ctor Shape::Group (list (ref Shape))))\" seed 4 8 = true end for all\n  end definition\n  example \"|vectors| :\n    seed = 11\n    expect encoded \"(data Shape (ctor Shape::Circle (int Int32 0 100)) (ctor Shape::Box (int Int32 0 100) (int Int32 0 100)) (ctor Shape::Group (list (ref Shape))))\" seed 3 3 = [\"0030\", \"020201b80100015ac801\", \"014808\"]\n  end example\nend law\n\n-- A checked definition that another node evaluates by its content hash.\nfunction shifted (x :: Int32) -> Int64 is x + 1000 end function\n\n-- Calls that cross a network wait for it, so they are asynchronous.\nasync remoteShifted :: Int32 -> Int64\n\nlaw \"|a definition evaluated on another node| is\n  definition : for all (x :: Int32) => remoteShifted x = shifted x end for all end definition\nend law\n\n-- An actor served on one node and called from another.\ntype Tally is a record{  count :: Int64} end type\n\nopenTally :: Unit -> Tally\nadd :: Tally -> UInt8 -> Pair Int64 Tally\n\nfunction modelAdd (n :: UInt8) (total :: Int64 where total >= 0 && total <= 1000000) -> Pair Int64 Int64 is\n  Pair (total + n) (total + n)\nend function\n\nactor tally :: Tally by Int64 is\n  start openTally by 0\n  on add by modelAdd\nend actor\n\nasync remoteAdds :: UInt8 -> Int64\n\nlaw \"|two calls from another node| is\n  definition : for all (x :: UInt8) => remoteAdds x = 2 * x end for all end definition\nend law\n\n-- A protocol between two nodes: the first end sends a number and receives\n-- its double.\nprotocol Doubling is\n  send Int32\n  receive Int64\nend protocol\n\nasync remoteDoubling :: Int32 -> Int64\n\nlaw \"|a conversation between nodes| is\n  definition : for all (x :: Int32) => remoteDoubling x = 2 * x end for all end definition\nend law\n\n-- A mailbox offered on one node and sent to from another: each send waits\n-- until the mailbox has the message.\nmailbox ledger of Int64\n\nasync remoteLedger :: Int32 -> Int64\n\nlaw \"|messages reach a mailbox on another node| is\n  definition : for all (x :: Int32) => remoteLedger x = 2 * x end for all end definition\nend law\n\n-- A channel end sent to another node. A local end stays where it is and\n-- the sending node relays its conversation, so the end works on its new\n-- node as it did on the old one.\nprotocol Handoff is\n  send Doubling\nend protocol\n\nasync remoteHandoff :: Int32 -> Int64\n\nlaw \"|a channel end handed to another node| is\n  definition : for all (x :: Int32) => remoteHandoff x = 2 * x end for all end definition\nend law\n\n-- An end that is already between nodes moves: its state goes to the new\n-- node, with any values that reached it, and its peer is told the new\n-- address. Here an end whose peer is on node C goes from A to B and on to D\n-- over a network that loses, duplicates and delays frames, while C is\n-- already sending to it; then A and B close, and the conversation between C\n-- and D still completes.\nprotocol Answering is\n  receive Int32\n  send Int64\nend protocol\n\nprotocol Passing is\n  send Answering\nend protocol\n\nasync remoteHandoffOnward :: Int32 -> Int64\n\nlaw \"|a channel end moved on twice| is\n  definition : for all (x :: Int32) => remoteHandoffOnward x = 2 * x end for all end definition\nend law\n\n-- The network is secure by default. Each node has an ML-DSA-65 identity;\n-- the first frame between two nodes waits for a handshake (a signed\n-- ML-KEM-768 exchange), and every frame then crosses sealed with\n-- AES-256-GCM. A node on the in-memory transport made for tests can skip\n-- it; no other transport can.\nasync sealedOnTheWire :: Int32 -> Bool\n\nlaw \"|frames cross sealed by default| is\n  definition : for all (x :: Int32) => sealedOnTheWire x = true end for all end definition\nend law\n\n-- Every target computes the same handshake: from these seeds and this\n-- ciphertext, the same hashes of the hello and welcome, the same session\n-- key, and the same sealed frame. The fields are, in order: the two\n-- identities' seeds, the ephemeral ML-KEM seed, the session, the two\n-- addresses, the ciphertext, the nonce, the frame, then the expected hashes,\n-- key and sealed record (dev/handshake-vector.py makes them).\nhandshakeAgrees :: Text -> Bool\n\nlaw \"|the secure handshake agrees across targets| is\n  definition : handshakeAgrees \"000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f 202122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f 404142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f606162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f 808182838485868788898a8b8c8d8e8f tcp://10.0.0.1:7000 tcp://10.0.0.2:7000  c8c9cacbcccdcecfd0d1d2d3 046368616e05656e642d33137463703a2f2f31302e302e302e313a373030300e0300022a da31284386e2b951348bda30557cf4b5abb4ad9a1ac15582e99c3b938573a254 9c78ba836e9dcaf2845dceaa7a02c9aad0fe0fd29bb9a5b948635c65aa4b2676 c595a58a85aebe6fb8009a0ca6afc9eb614c7ab4711c08c4f7d34c38420c4abd 4c53010310808182838485868788898a8b8c8d8e8f0040c8c9cacbcccdcecfd0d1d2d314713b317e0cd4b10f4d5b885bc8bc1fa7aae4f824a30442ed569d3eab22fcce44c274bd139e84e8a9960d14a17722544ee187c1\" = true end definition\nend law\nend unit\n")
  , ("domain_modeling.lawspec", "unit example.ordering\n\n-- Constrained primitives. Each wrapper is a distinct type whose constructor\n-- checks the value, so an out-of-range quantity cannot be constructed,\n-- generated or decoded from native code. valueOf<Name> unwraps a value.\nwrapper UnitQuantity is Int32 where value >= 1 && value <= 1000 end wrapper\nwrapper OrderId is Text where prelude.length value > 0 end wrapper\nwrapper NonEmptyList (a :: Type) is List a where prelude.length value > 0 end wrapper\n\n-- Each workflow state is its own type. A ValidatedOrder can only hold checked\n-- values, so no later step needs to validate again.\ntype UnvalidatedOrder is a record{  id :: Text quantity :: Int32} end type\ntype ValidatedOrder is a record{  id :: OrderId quantity :: UnitQuantity} end type\ntype PricedOrder is a record{  id :: OrderId quantity :: UnitQuantity total :: Int64} end type\ntype OrderError is one of | InvalidOrderId | InvalidQuantity | PriceTooHigh end type\n\n-- The compiler checks that each step accepts the previous step's state and\n-- generates placeOrder on every target: the steps run in order and the first\n-- Left is the workflow's result. Only the steps are written by hand. The steps\n-- share OrderError, so it is the workflow's error type; laws say the workflow\n-- succeeds when every step does and stops at the first failing step.\nworkflow placeOrder :: UnvalidatedOrder -> Either OrderError PricedOrder is\n  validateOrder :: UnvalidatedOrder -> Either OrderError ValidatedOrder\n  priceOrder :: ValidatedOrder -> Either OrderError PricedOrder\nend workflow\n\nfirstLine :: NonEmptyList Int32 -> Int32\n\n-- An order is placed when it is valid and its total is at most 20000.\nlaw \"|placing an order prices it| is\n  definition :\n    for all (input :: UnvalidatedOrder) =>\n      prelude.isRight (placeOrder input) = (first matching case of input :\n        when UnvalidatedOrder record{ id = id , quantity = quantity} then\n            prelude.length id > 0 && quantity >= 1 && quantity <= 800\n        end case) end for all\n  end definition\n  example \"|a hundred units| :\n    input = UnvalidatedOrder record{ id = \"A-1\" , quantity = 100}\n    expect prelude.isRight (placeOrder input) = true\n  end example\n  example \"|the last quantity within the price limit| :\n    input = UnvalidatedOrder record{ id = \"A-2\" , quantity = 800}\n    expect prelude.isRight (placeOrder input) = true\n  end example\n  example \"|the first quantity over the price limit| :\n    input = UnvalidatedOrder record{ id = \"A-3\" , quantity = 801}\n    expect prelude.isRight (placeOrder input) = false\n  end example\nend law\n\nlaw \"|validation accepts exactly the valid orders| is\n  definition :\n    for all (input :: UnvalidatedOrder) =>\n      (first matching case of validateOrder input :\n        when Left e then false\n        when Right v then true\n        end case) = (first matching case of input :\n        when UnvalidatedOrder record{ id = id , quantity = quantity} then\n            prelude.length id > 0 && quantity >= 1 && quantity <= 1000\n        end case) end for all\n  end definition\n  example \"|the largest valid quantity is accepted| :\n    input = UnvalidatedOrder record{ id = \"A-4\" , quantity = 1000}\n    expect prelude.isRight (validateOrder input) = true\n  end example\n  example \"|a quantity above the declared range is rejected| :\n    input = UnvalidatedOrder record{ id = \"A-5\" , quantity = 1001}\n    expect prelude.isRight (validateOrder input) = false\n  end example\n  example \"|zero is not a unit quantity| :\n    input = UnvalidatedOrder record{ id = \"A-6\" , quantity = 0}\n    expect prelude.isRight (validateOrder input) = false\n  end example\nend law\n\nlaw \"|quantities are always in range| is\n  definition :\n    for all (q :: UnitQuantity) =>\n      valueOfUnitQuantity q >= 1 && valueOfUnitQuantity q <= 1000 end for all\n  end definition\n  example \"|largest quantity| :\n    q = UnitQuantity 1000\n    expect valueOfUnitQuantity q = 1000\n  end example\nend law\n\nlaw \"|a non-empty list has a first element| is\n  definition :\n    for all (xs :: NonEmptyList Int32) =>\n      (first matching case of valueOfNonEmptyList xs :\n        when Nil then false\n        when Cons head tail then firstLine xs = head\n        end case) = true end for all\n  end definition\nend law\nend unit\n")
  , ("durations.lawspec", "unit example.durations\n\n-- A Duration is a whole number of microseconds, from 0 to about 146 years.\n-- Literals name a unit (us, ms, s, min, h, d), prelude.milliseconds and its\n-- siblings build one from a number, and prelude.toMicroseconds reads one.\n-- +, -, comparisons, * and prelude.quot by whole numbers stay in range or\n-- fail, as division by zero does.\n\n-- A checked definition: the totality audit proves the result in range.\nfunction timeoutFor (retries :: Int32 where retries >= 0 && retries <= 5) -> Duration is\n  2s + 500ms * retries\nend function\n\n-- An adapter: the time left of a budget, never negative.\nremaining :: Duration -> Duration -> Duration\n\nlaw \"|units relate| is\n  definition :\n    for all (b :: Bool) => (1us * 1000 = 1ms && 1000ms = 1s && 60s = 1min && 60min = 1h && 24h = 1d) = true end for all\n  end definition\nend law\n\nlaw \"|subtraction undoes addition| is\n  definition :\n    for all (n :: Int32 where n >= 0) (m :: Int32 where m >= 0) =>\n      prelude.milliseconds (prelude.Integer n) + prelude.milliseconds (prelude.Integer m) - prelude.milliseconds (prelude.Integer m) =\n        prelude.milliseconds (prelude.Integer n) end for all\n  end definition\nend law\n\nlaw \"|timeouts grow by half a second| is\n  definition :\n    for all (r :: Int32 where r >= 0 && r <= 4) => timeoutFor (r + 1) - timeoutFor r = 500ms end for all\n  end definition\n  example \"|no retries| :\n    r = 0\n    expect prelude.toMicroseconds (timeoutFor r) = 2000000\n  end example\nend law\n\nlaw \"|spending everything leaves nothing| is\n  definition :\n    for all (d :: Duration) => remaining d d = 0us and remaining d 0us = d end for all\n  end definition\nend law\n\nlaw \"|what remains of a budget| is\n  definition :\n    for all (budget :: Duration) (spent :: Duration) =>\n      prelude.toMicroseconds (remaining budget spent) =\n        prelude.select (spent <= budget) (prelude.toMicroseconds budget - prelude.toMicroseconds spent) 0 end for all\n  end definition\n  example \"|part of a second| :\n    budget = 1s\n    spent = 250ms\n    expect remaining budget spent = 750ms\n  end example\n  example \"|an overrun leaves nothing| :\n    budget = 1s\n    spent = 2s\n    expect remaining budget spent = 0us\n  end example\nend law\nend unit\n")
  , ("equivalent.lawspec", "unit example.alternatives\n\nrender :: Int32 -> Text\nreferenceRender :: Int32 -> Text\nclamp :: Int32 -> Int32\nreferenceClamp :: Int32 -> Int32\n\nlaw \"|decimal renderers agree| is\n  definition :\n    apply law \"|equivalent| render referenceRender\n  end definition\n  description :\n    \"{render} agrees with {referenceRender} on decimal formatting\"\n  end description\n  rationale :\n    \"changing the formatting implementation must preserve its result\"\n  end rationale\n  example \"|both renderers produce \"-42\"| :\n    x = -42\n    expect render x = \"-42\"\n    expect referenceRender x = \"-42\"\n  end example\n  example \"|both renderers produce \"0\"| :\n    x = 0\n    expect render x = \"0\"\n    expect referenceRender x = \"0\"\n  end example\nend law\n\nlaw \"|nonnegative clamps agree| is\n  definition :\n    apply law \"|equivalent| clamp referenceClamp\n  end definition\n  description :\n    \"{clamp} agrees with {referenceClamp} when clamping negative inputs to zero\"\n  end description\n  example \"|both clamps return 0 for -2147483648| :\n    x = -2147483648\n    expect clamp x = 0\n    expect referenceClamp x = 0\n  end example\n  example \"|both clamps return 2147483647 for 2147483647| :\n    x = 2147483647\n    expect clamp x = 2147483647\n    expect referenceClamp x = 2147483647\n  end example\nend law\nend unit\n")
  , ("failures.lawspec", "unit example.failures\n\n-- Typed failures. A definition that can fail says what it fails with, and a\n-- law says which failure it expects: `fails with` takes a constructor\n-- pattern, where _ matches any field, and may also check the failure's\n-- message.\n\ntype Decision is one of\n  | Approve\n  | Decline  of type Text\n  | Block\nend type\n\ntype PaymentError is one of\n  | Declined of type record{ message :: Text}\n  | Blocked\n  | TooLarge  of type Int32\nend type\n\n-- The payment provider decides; its native handler is written by hand.\nability Gateway is\n  decide :: Int32 -> Decision\nend ability\n\nprocedure charge (cents :: Int32) -> Int32 uses Gateway fails with PaymentError is\n  if cents > 100000 then raise (TooLarge 100000) else\n    first matching case of decide cents :\n    when Approve then cents\n    when Decline reason then raise (Declined record{ message = reason})\n    when Block then raise Blocked\n    end case end if\nend procedure\n\nlaw \"|large charges fail as too large| is\n  definition :\n    for all (cents :: Int32 where cents > 100000) => charge cents fails with TooLarge 100000 end for all\n  end definition\nend law\n\nlaw \"|odd amounts are declined, and say why| is\n  definition :\n    for all (cents :: Int32 where cents >= 0 && cents <= 100000 && prelude.rem cents 2 = 1) =>\n      charge cents fails with Declined record{ message = _} message contains \"odd\" end for all\n  end definition\nend law\n\nlaw \"|negative amounts are blocked| is\n  definition :\n    for all (cents :: Int32 where cents < 0) => charge cents fails with Blocked end for all\n  end definition\n  example \"|minus one| :\n    cents = -1\n    expect charge cents fails with Blocked\n    expect !(charge cents fails with Declined record{ message = _})\n  end example\nend law\n\nlaw \"|even amounts go through| is\n  definition :\n    for all (cents :: Int32 where cents >= 0 && cents <= 100000 && prelude.rem cents 2 = 0) =>\n      prelude.attempt (charge cents) = Right cents end for all\n  end definition\nend law\n\n-- Native adapters fail too: their native code raises the runtime's Fail\n-- with a PaymentError, synchronously or from an async adapter.\nrefund :: Int32 -> Int32 fails with PaymentError\nasync settle :: Int32 -> Int32 fails with PaymentError\n\nlaw \"|refunds over the limit are too large| is\n  definition :\n    for all (cents :: Int32 where cents > 5000) => refund cents fails with TooLarge 5000 end for all\n  end definition\nend law\n\nlaw \"|refunds within the limit go through| is\n  definition :\n    for all (cents :: Int32 where cents >= 0 && cents <= 5000) => prelude.attempt (refund cents) = Right cents end for all\n  end definition\nend law\n\nlaw \"|settling a negative amount is blocked| is\n  definition :\n    for all (cents :: Int32 where cents < 0) => settle cents fails with Blocked end for all\n  end definition\nend law\n\nlaw \"|settling nothing is declined, and says why| is\n  definition : settle 0 fails with Declined record{ message = _} message contains \"nothing\" end definition\nend law\n\nlaw \"|settling a positive amount goes through| is\n  definition :\n    for all (cents :: Int32 where cents > 0) => prelude.attempt (settle cents) = Right cents end for all\n  end definition\nend law\nend unit\n")
  , ("finite_data.lawspec", "unit example.finite_data\n\ntype Choice is one of Yes | No end type\n\ntype Pair (a :: Type) (b :: Type) is a record{\n   first :: a second :: b}\nend type\n\nlaw \"|sum constructors remain distinct| is\n  definition :\n    for all (choice :: Choice) =>\n      (first matching case of choice :\n        when Yes then Yes\n        when No then No\n      end case) = choice end for all\n  end definition\n  example \"|yes| : choice = Yes expect choice = Yes end example\nend law\n\nlaw \"|products preserve both fields| is\n  definition :\n    for all (pair :: Pair Bool Bool) =>\n      (first matching case of pair :\n        when Pair record{ first = first , second = second} then Pair record{ first = first , second = second}\n      end case) = pair end for all\n  end definition\n  example \"|different fields| :\n    pair = Pair record{ first = true , second = false}\n    expect pair = Pair record{ first = true , second = false}\n  end example\nend law\n\nlaw \"|nested optional products keep presence states| is\n  definition :\n    for all (value :: Maybe (Pair Choice (Nullable Bool))) => value = value end for all\n  end definition\nend law\nend unit\n")
  , ("flow_stack.lawspec", "unit example.flow\n\ntype Stack (n :: Whole) is one of\n  | Empty where n = 0\n  | Push of type record{ top :: Int8 rest :: Stack m} where n = m + 1\nend type\n\n-- A / A' is a flow parameter: the call takes the stack from A to A'. Each\n-- adapter returns its result with the stack it leaves, as a generated\n-- product (PushFlow, PopFlow, PeekFlow); the stack's index is checked.\npush :: (x :: Int8) -> Stack n / Stack (n + 1) -> Unit\npop :: Stack (n + 1) / Stack n -> Int8\npeek :: Stack (n + 1) / Stack (n + 1) -> Int8\n\n-- A reference definition updates its flow parameter with ~s := e.\nfunction pushed (x :: Int8) (s :: Stack n / Stack (n + 1)) -> Unit is\n  ~s := Push record{ top = x , rest = s}\nend function\n\n-- ~s passes s to a flow parameter and rebinds s to the stack the call\n-- leaves; e1; e2 sequences, left to right. pop needs Stack (m + 1): after\n-- push, s is a Stack (n + 1), so the pop below type-checks.\nlaw \"|pop returns what push pushed| is\n  definition :\n    for all (x :: Int8) (s :: Stack n) => (push x ~s; pop ~s) = x end for all\n  end definition\nend law\n\nlaw \"|push grows the stack| is\n  definition :\n    for all (x :: Int8) (s :: Stack n) => (push x ~s; nOfStack s) = n + 1 end for all\n  end definition\nend law\n\nlaw \"|pops come back in reverse| is\n  definition :\n    for all (x :: Int8) (y :: Int8) (s :: Stack n) =>\n      (push x ~s; push y ~s; pop ~s; pop ~s) = x end for all\n  end definition\nend law\n\n-- The quantifier's index k + 1 lets peek and pop take s.\nlaw \"|peek and pop agree| is\n  definition :\n    for all (s :: Stack (k + 1)) => peek ~s = pop ~s end for all\n  end definition\nend law\n\nlaw \"|pop shrinks the stack| is\n  definition :\n    for all (s :: Stack (k + 1)) => (pop ~s; nOfStack s) = k end for all\n  end definition\nend law\n\nlaw \"|push agrees with the reference| is\n  definition :\n    for all (x :: Int8) (s :: Stack n) => (pushed x ~s; pop ~s) = x end for all\n  end definition\nend law\n\n-- A function may take several flow parameters: pushBoth takes two stacks and\n-- leaves each one higher. A call passes ~a ~b, rebinding each.\nfunction pushBoth (x :: Int8) (a :: Stack n / Stack (n + 1)) (b :: Stack m / Stack (m + 1)) -> Unit is\n  ~a := Push record{ top = x , rest = a}; ~b := Push record{ top = x , rest = b}\nend function\n\nlaw \"|both stacks get the value| is\n  definition :\n    for all (x :: Int8) (a :: Stack n) (b :: Stack m) => (pushBoth x ~a ~b; pop ~a; pop ~b) = x end for all\n  end definition\nend law\n\n-- A flow call may sit in a branch of an if or a match, when every branch\n-- leaves the stack at the same type: here each branch pushes once.\nlaw \"|a push in each branch| is\n  definition :\n    for all (x :: Int8) (s :: Stack n) =>\n      ((if x > 0 then push x ~s else push 0 ~s end if); pop ~s) = (if x > 0 then x else 0 end if) end for all\n  end definition\nend law\n\nlaw \"|a push chosen by a match| is\n  definition :\n    for all (m :: Maybe Int8) (s :: Stack n) =>\n      ((first matching case of m :\n        when Present v then push v ~s\n        when Absent then push 0 ~s\n        end case); pop ~s) = (first matching case of m :\n                          when Present v then v\n                          when Absent then prelude.Int8 0\n                          end case) end for all\n  end definition\nend law\nend unit\n")
  , ("function_parameters.lawspec", "unit example.functionParameters\n\n-- Definitions that take a function. Each call names the function, and the\n-- generated code has one plain function per function named.\n\nfunction double (n :: Integer) -> Integer is n * 2 end function\n\nfunction increment (n :: Integer) -> Integer is n + 1 end function\n\nfunction scaled (factor :: Integer) (n :: Integer) -> Integer is factor * n end function\n\nfunction isEven (n :: Integer) -> Bool is prelude.rem n 2 = 0 end function\n\nfunction applyTwice (f :: a -> a) (x :: a) -> a is f (f x) end function\n\n-- The function parameter is passed on unchanged to the recursive call.\nfunction each (f :: a -> b) (xs :: List a) -> List b is\n  first matching case of xs:\n    when Nil then []\n    when Cons x rest then Cons (f x) (each f rest)\n  end case\nend function\n\nfunction keeping (keep :: a -> Bool) (xs :: List a) -> List a is\n  first matching case of xs:\n    when Nil then []\n    when Cons x rest then if keep x then Cons x (keeping keep rest) else keeping keep rest end if\n  end case\nend function\n\n-- A function parameter passed on to other definitions.\nfunction eachTwice (f :: a -> a) (xs :: List a) -> List a is\n  each f (each f xs)\nend function\n\nfunction evensDoubled (xs :: List Integer) -> List Integer is\n  each double (keeping isEven xs)\nend function\n\nfunction scaledBy (factor :: Integer) (xs :: List Integer) -> List Integer is\n  each (scaled factor) xs\nend function\n\nlaw \"|a named function is applied| is\n  definition :\n    applyTwice double 3 = 12\n    and applyTwice increment 3 = 5\n    and each double [1, 2, 3] = [2, 4, 6]\n    and each isEven [1, 2] = [false, true]\n    and keeping isEven [1, 2, 3, 4] = [2, 4]\n    and eachTwice increment [1, 2] = [3, 4]\n  end definition\nend law\n\nlaw \"|a partial application or a composition is a function| is\n  definition :\n    each (scaled 3) [1, 2] = [3, 6]\n    and each (double . increment) [1, 2] = [4, 6]\n    and scaledBy 5 [1, 2] = [5, 10]\n  end definition\nend law\n\nlaw \"|each agrees with map| is\n  definition :\n    for all (xs :: List Integer) =>\n      each double xs = prelude.map double xs\n    end for all\n  end definition\nend law\n\nlaw \"|keeping agrees with filter| is\n  definition :\n    for all (xs :: List Integer) =>\n      keeping isEven xs = prelude.filter isEven xs\n    end for all\n  end definition\nend law\n\nlaw \"|each keeps the length| is\n  definition :\n    for all (factor :: Integer) (xs :: List Integer) =>\n      prelude.length (scaledBy factor xs) = prelude.length xs\n    end for all\n  end definition\nend law\n\nlaw \"|evens doubled are even| is\n  definition :\n    for all (xs :: List Integer) =>\n      prelude.all isEven (evensDoubled xs)\n    end for all\n  end definition\nend law\nend unit\n")
  , ("gadt_expressions.lawspec", "unit example.gadt\n\ntype Pair (a :: Type) (b :: Type) is a record{  first :: a second :: b} end type\n\n-- An expression indexed by the type of its value. Each constructor's `where`\n-- fixes that type, so a value of Expr Bool is never a number literal. The\n-- types b and c of Both are existential: Expr (Pair b c) determines them.\ntype Expr (a :: Type) is one of\n  | Number  of type Integer where a = Integer\n  | Truth  of type Bool where a = Bool\n  | Plus of type record{ left :: Expr Integer right :: Expr Integer} where a = Integer\n  | Same of type record{ left :: Expr Integer right :: Expr Integer} where a = Bool\n  | Negate  of type Expr Bool where a = Bool\n  | Both of type record{ first :: Expr b second :: Expr c} where a = Pair b c\nend type\n\n-- Matching Number refines a to BigInt in that branch, so v is a value of a.\n-- eval calls itself at other types (Expr BigInt inside Expr Bool): each type\n-- it is used at becomes a checked instance, and unreachable branches vanish.\nfunction eval (e :: Expr a) -> a is\n  first matching case of e :\n  when Number v then v\n  when Truth b then b\n  when Plus record{ left = l , right = r} then eval l + eval r\n  when Same record{ left = l , right = r} then eval l = eval r\n  when Negate x then !(eval x)\n  when Both record{ first = l , second = r} then Pair record{ first = (eval l) , second = (eval r)}\n  end case\nend function\n\nevalNumber :: Expr Integer -> Integer\nevalTruth :: Expr Bool -> Bool\nevalPair :: Expr (Pair Integer Bool) -> Pair Integer Bool\n-- Constant folding: a single number with the same value.\nfold :: Expr Integer -> Expr Integer\n\n-- A shown value's type is existential and only the value says what it is:\n-- each value carries its type, as a witness, to native code.\ntype Shown is one of\n  | Shown  of type b\nend type\n\n-- The name of the type a shown value holds.\ndescribe :: Shown -> Text\n\nlaw \"|numbers agree with eval| is\n  definition : for all (e :: Expr Integer) => evalNumber e = eval e end for all end definition\nend law\n\nlaw \"|truths agree with eval| is\n  definition : for all (e :: Expr Bool) => evalTruth e = eval e end for all end definition\nend law\n\nlaw \"|pairs agree with eval| is\n  definition : for all (e :: Expr (Pair Integer Bool)) => evalPair e = eval e end for all end definition\nend law\n\nlaw \"|folding keeps the value| is\n  definition : for all (e :: Expr Integer) => eval (fold e) = eval e end for all end definition\nend law\n\nlaw \"|a shown number names its type| is\n  definition : for all (x :: Int32) => describe (Shown x) = \"Int32\" end for all end definition\nend law\n\nlaw \"|a shown flag names its type| is\n  definition : for all (b :: Bool) => describe (Shown b) = \"Bool\" end for all end definition\nend law\n\nlaw \"|every shown value is described| is\n  definition : for all (s :: Shown) => prelude.length (describe s) > 0 end for all end definition\nend law\n\nlaw \"|two plus three| is\n  definition : for all (x :: Integer) => eval (Plus record{ left = (Number 2) , right = (Number 3)}) = 5 end for all end definition\nend law\nend unit\n")
  , ("generation.lawspec", "unit example.generation\n\n-- Conformance of every target's portable generator with the same vectors:\n-- the values generated from a type descriptor and a SplitMix64 seed, and the\n-- shrink candidates of the first, rendered canonically.\n\ngenerated :: Text -> UInt64 -> Int32 -> Int32 -> List Text\nshrunk :: Text -> UInt64 -> Int32 -> List Text\n\nlaw \"|int8| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (generated \"(int Int8 -128 127)\" seed 4 5) = 5 end for all\n  end definition\n  example \"|seed 42| :\n    seed = 42\n    expect generated \"(int Int8 -128 127)\" seed 4 5 = [\"-125\", \"20\", \"0\", \"36\", \"46\"]\n    expect shrunk \"(int Int8 -128 127)\" seed 4 = [\"0\", \"-63\", \"-124\"]\n  end example\nend law\n\nlaw \"|unbounded integers| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (generated \"(int Integer _ _)\" seed 4 4) = 4 end for all\n  end definition\n  example \"|seed 7| :\n    seed = 7\n    expect generated \"(int Integer _ _)\" seed 4 4 = [\"-653071\", \"196343\", \"-29128\", \"80327\"]\n    expect shrunk \"(int Integer _ _)\" seed 4 = [\"0\", \"-326536\", \"-653070\"]\n  end example\nend law\n\nlaw \"|a lower bound| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (generated \"(int Int32 5 _)\" seed 4 4) = 4 end for all\n  end definition\n  example \"|seed 7| :\n    seed = 7\n    expect generated \"(int Int32 5 _)\" seed 4 4 = [\"346934\", \"1196348\", \"970877\", \"1080332\"]\n    expect shrunk \"(int Int32 5 _)\" seed 4 = [\"5\", \"173470\", \"346933\"]\n  end example\nend law\n\nlaw \"|the full UInt64 range| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (generated \"(int UInt64 0 18446744073709551615)\" seed 4 3) = 3 end for all\n  end definition\n  example \"|seed 1| :\n    seed = 1\n    expect generated \"(int UInt64 0 18446744073709551615)\" seed 4 3 = [\"13757245211066428519\", \"1\", \"0\"]\n    expect shrunk \"(int UInt64 0 18446744073709551615)\" seed 4 = [\"0\", \"6878622605533214260\", \"13757245211066428518\"]\n  end example\nend law\n\nlaw \"|booleans| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (generated \"(bool)\" seed 4 6) = 6 end for all\n  end definition\n  example \"|seed 3| :\n    seed = 3\n    expect generated \"(bool)\" seed 4 6 = [\"true\", \"true\", \"true\", \"true\", \"false\", \"true\"]\n    expect shrunk \"(bool)\" seed 4 = [\"false\"]\n  end example\nend law\n\nlaw \"|text| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (generated \"(text)\" seed 6 3) = 3 end for all\n  end definition\n  example \"|seed 9| :\n    seed = 9\n    expect generated \"(text)\" seed 6 3 = [\"\\\"I(\\\"\", \"\\\"\\\"\", \"\\\"4<*6F\\\"\"]\n    expect shrunk \"(text)\" seed 6 = [\"\\\"\\\"\", \"\\\"I\\\"\", \"\\\"(\\\"\"]\n  end example\nend law\n\nlaw \"|unit| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (generated \"(unit)\" seed 1 2) = 2 end for all\n  end definition\n  example \"|seed 1| :\n    seed = 1\n    expect generated \"(unit)\" seed 1 2 = [\"()\", \"()\"]\n    expect shrunk \"(unit)\" seed 1 = []\n  end example\nend law\n\nlaw \"|lists| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (generated \"(list (int Int32 0 _))\" seed 4 3) = 3 end for all\n  end definition\n  example \"|seed 42| :\n    seed = 42\n    expect generated \"(list (int Int32 0 _))\" seed 4 3 = [\"[0, 1745563, 275752]\", \"[1325093, 742426, 493279]\", \"[2000000]\"]\n    expect shrunk \"(list (int Int32 0 _))\" seed 4 = [\"[]\", \"[0]\", \"[1745563, 275752]\", \"[0, 275752]\", \"[0, 1745563]\", \"[0, 0, 275752]\", \"[0, 872782, 275752]\", \"[0, 1745562, 275752]\", \"[0, 1745563, 0]\", \"[0, 1745563, 137876]\", \"[0, 1745563, 275751]\"]\n  end example\nend law\n\nlaw \"|maybe| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (generated \"(maybe (bool))\" seed 4 4) = 4 end for all\n  end definition\n  example \"|seed 5| :\n    seed = 5\n    expect generated \"(maybe (bool))\" seed 4 4 = [\"Present(false)\", \"Present(true)\", \"Present(false)\", \"Present(true)\"]\n    expect shrunk \"(maybe (bool))\" seed 4 = [\"Absent\"]\n  end example\nend law\n\nlaw \"|either| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (generated \"(either (text) (int Int8 -128 127))\" seed 4 4) = 4 end for all\n  end definition\n  example \"|seed 11| :\n    seed = 11\n    expect generated \"(either (text) (int Int8 -128 127))\" seed 4 4 = [\"Right(-19)\", \"Left(\\\"\\\\\\\"{U\\\")\", \"Left(\\\"j\\\")\", \"Right(1)\"]\n    expect shrunk \"(either (text) (int Int8 -128 127))\" seed 4 = [\"Right(0)\", \"Right(-10)\", \"Right(-18)\"]\n  end example\nend law\n\nlaw \"|a recursive tree| is\n  definition :\n    for all (seed :: UInt64) => prelude.length (generated \"(data Tree (ctor t::type::Tree::Leaf) (ctor t::type::Tree::Node (ref Tree) (int Int8 -128 127) (ref Tree))) (ref Tree)\" seed 3 2) = 2 end for all\n  end definition\n  example \"|seed 13| :\n    seed = 13\n    expect generated \"(data Tree (ctor t::type::Tree::Leaf) (ctor t::type::Tree::Node (ref Tree) (int Int8 -128 127) (ref Tree))) (ref Tree)\" seed 3 2 = [\"Node(Node(Leaf, -29, Leaf), -44, Node(Node(Leaf, -110, Leaf), 58, Leaf))\", \"Leaf\"]\n    expect shrunk \"(data Tree (ctor t::type::Tree::Leaf) (ctor t::type::Tree::Node (ref Tree) (int Int8 -128 127) (ref Tree))) (ref Tree)\" seed 3 = [\"Leaf\", \"Node(Leaf, -29, Leaf)\", \"Node(Node(Leaf, -110, Leaf), 58, Leaf)\", \"Node(Leaf, -44, Node(Node(Leaf, -110, Leaf), 58, Leaf))\", \"Node(Node(Leaf, 0, Leaf), -44, Node(Node(Leaf, -110, Leaf), 58, Leaf))\", \"Node(Node(Leaf, -15, Leaf), -44, Node(Node(Leaf, -110, Leaf), 58, Leaf))\", \"Node(Node(Leaf, -28, Leaf), -44, Node(Node(Leaf, -110, Leaf), 58, Leaf))\", \"Node(Node(Leaf, -29, Leaf), 0, Node(Node(Leaf, -110, Leaf), 58, Leaf))\", \"Node(Node(Leaf, -29, Leaf), -22, Node(Node(Leaf, -110, Leaf), 58, Leaf))\", \"Node(Node(Leaf, -29, Leaf), -43, Node(Node(Leaf, -110, Leaf), 58, Leaf))\", \"Node(Node(Leaf, -29, Leaf), -44, Leaf)\", \"Node(Node(Leaf, -29, Leaf), -44, Node(Leaf, -110, Leaf))\", \"Node(Node(Leaf, -29, Leaf), -44, Node(Leaf, 58, Leaf))\", \"Node(Node(Leaf, -29, Leaf), -44, Node(Node(Leaf, 0, Leaf), 58, Leaf))\", \"Node(Node(Leaf, -29, Leaf), -44, Node(Node(Leaf, -55, Leaf), 58, Leaf))\", \"Node(Node(Leaf, -29, Leaf), -44, Node(Node(Leaf, -109, Leaf), 58, Leaf))\", \"Node(Node(Leaf, -29, Leaf), -44, Node(Node(Leaf, -110, Leaf), 0, Leaf))\", \"Node(Node(Leaf, -29, Leaf), -44, Node(Node(Leaf, -110, Leaf), 29, Leaf))\", \"Node(Node(Leaf, -29, Leaf), -44, Node(Node(Leaf, -110, Leaf), 57, Leaf))\"]\n  end example\nend law\n\n-- A refinement's bounds narrow generation: an amount from 1 to 1000 is\n-- drawn from that range, not filtered out of every Int32, alongside a value\n-- of a data type.\ntype Purse is a record{  coins :: Int64} end type\n\nfunction spend (p :: Purse) (amount :: Int32 where amount >= 1 && amount <= 1000) -> Int32 is amount end function\n\nlaw \"|refined amounts are drawn from their range| is\n  definition :\n    for all (p :: Purse) (amount :: Int32 where amount >= 1 && amount <= 1000) => spend p amount >= 1 end for all\n  end definition\nend law\n\n-- if c then a else b evaluates only the branch c selects, and each branch is\n-- checked knowing which way c went: the division is safe because n > 0.\nfunction share (total :: Int32 where total >= 0 && total <= 1000) (n :: Int32 where n >= 0 && n <= 10) -> Int32 is\n  if n > 0 then prelude.quot total n else 0 end if\nend function\n\nlaw \"|a share is at most the total| is\n  definition :\n    for all (t :: Int32 where t >= 0 && t <= 1000) (n :: Int32 where n >= 0 && n <= 10) => share t n <= t end for all\n  end definition\n  example \"|nobody to share with| :\n    t = 7\n    n = 0\n    expect share t n = 0\n  end example\n  example \"|three people| :\n    t = 7\n    n = 3\n    expect share t n = 2\n  end example\nend law\n\n-- A text refined to be non-empty is drawn from its refinement, at every\n-- size: four of them, one also unlike another, are met at the first case,\n-- not filtered out of draws that are mostly empty while the size is small.\nlaw \"|several non-empty texts are drawn| is\n  definition :\n    for all (a :: Text where a != \"\") (b :: Text where b != \"\") (c :: Text where c != \"\")\n      (d :: Text where d != \"\" && d != c) =>\n      prelude.length a + prelude.length b + prelude.length c + prelude.length d >= 4 end for all\n  end definition\nend law\nend unit\n")
  , ("handler_bindings.lawspec", "unit example.till\n\n-- An ability whose production handler is application code, named in\n-- lawspec.edn under handlers. Money is bound to a native type there too, so\n-- the handler's operations take and give that type.\n\ntype Money is a record{  cents :: Int64} end type\ntype PayError is one of | Declined | Rejected of type record{ message :: Text} end type\n\n-- A till's drawer. Every handler of it gives back what it takes.\nability Drawer is\n  take :: Money -> Money\n  opening :: Money\nlaws\n  law \"|a till gives back what it takes| is\n    definition :\n      for all (cents :: Int64 where cents >= 0 && cents <= 1000) => take (Money record{ cents = cents}) = Money record{ cents = cents} end for all\n    end definition\n  end law\nend laws\nend ability\n\nhandler fakeDrawer for Drawer is\n  operation take money is money end operation\n  operation opening is Money record{ cents = 0} end operation\nend handler\n\n-- A native adapter that fails. Its native code raises the application's own\n-- exceptions; lawspec.edn maps them to PayError's constructors.\npay :: Int64 -> Money uses Drawer fails with PayError\n\nlaw \"|small payments go through| is\n  definition :\n    for all (cents :: Int64 where cents >= 0 && cents <= 1000) =>\n      prelude.attempt (pay cents) = Right (Money record{ cents = cents}) end for all\n  end definition\nend law\n\nlaw \"|large payments are declined| is\n  definition :\n    for all (cents :: Int64 where cents > 1000 && cents <= 100000) =>\n      prelude.attempt (pay cents) = Left Declined end for all\n  end definition\nend law\n\nlaw \"|negative payments are rejected| is\n  definition :\n    for all (cents :: Int64 where cents >= -1000 && cents < 0) =>\n      prelude.attempt (pay cents) = Left (Rejected record{ message = \"negative\"}) end for all\n  end definition\nend law\n\n-- The same failures, as a law expects them: `fails with` matches the\n-- constructor a mapped exception became, and its message.\nlaw \"|large payments fail as declined| is\n  definition :\n    for all (cents :: Int64 where cents > 1000 && cents <= 100000) => pay cents fails with Declined end for all\n  end definition\nend law\n\nlaw \"|negative payments say why they are rejected| is\n  definition :\n    for all (cents :: Int64 where cents >= -1000 && cents < 0) =>\n      pay cents fails with Rejected record{ message = _} message contains \"negative\" end for all\n  end definition\nend law\nend unit\n")
  , ("handles.lawspec", "unit example.handles\n\n-- A handle is a value only adapters create, such as a library's concurrent\n-- queue. LawSpec passes it along unopened: it never generates, builds or\n-- looks inside one, and two handles are equal only when they are the same.\n-- Here the queue is the target's own concurrent queue, bound directly where\n-- the target has one (see each target's bindings) and wrapped elsewhere.\nhandle Jobs\n\nnewJobs :: Unit -> Jobs\nsubmit :: Jobs -> Int32 -> Unit\ntake :: Jobs -> Maybe Int32\npending :: Jobs -> Int32\n\nmodel jobs :: shared Jobs behaves like Queue Int32 is\n  start newJobs\n  submit as offer\n  take as poll\n  pending as size\nend model\nend unit\n")
  , ("harness.lawspec", "unit example.harness\n\n-- The laws of a small shop. How they are tested (which inputs, which\n-- handlers, how many cases are enough) is not said here: that is the\n-- harness's business, in harness_testing.lawspec.\n\n-- An order: how many items it has, and its total in cents.\ntype Order is a record{  items :: Int32 total :: Int32} end type\n\nfunction itemsOf (order :: Order) -> Int32 is first matching case of order : when Order record{ items = items , total = total} then items end case end function\nfunction totalOf (order :: Order) -> Int32 is first matching case of order : when Order record{ items = items , total = total} then total end case end function\nfunction isEmpty (order :: Order) -> Bool is itemsOf order = 0 end function\n\n-- The discount an order gets, and a price rounded to tens of cents.\ndiscount :: Order -> Int32\nroundCents :: Int32 -> Int32\n\nlaw \"|a discount is never more than the total| is\n  definition :\n    for all (order :: Order where itemsOf order >= 0 && totalOf order >= 0) =>\n      (discount order <= totalOf order) = true end for all\n  end definition\nend law\n\nlaw \"|rounding is idempotent| is\n  definition :\n    for all (cents :: Int32 where cents >= 0 && cents <= 1000000) =>\n      roundCents (roundCents cents) = roundCents cents end for all\n  end definition\nend law\n\nlaw \"|rounding never lowers a price| is\n  definition :\n    for all (cents :: Int32 where cents >= 0 && cents <= 1000000) =>\n      (roundCents cents >= cents) = true end for all\n  end definition\nend law\n\n-- A ledger records payments. Every law about booking holds for every\n-- lawful ledger; the harness chooses which ones the tests use.\nability Ledger is\n  accept :: Int32 -> Bool\nlaws\n  law \"|positive amounts are accepted| is\n    definition : for all (cents :: Int32 where cents > 0) => accept cents = true end for all end definition\n  end law\nend laws\nend ability\n\nhandler fakeLedger for Ledger is\n  operation accept cents is cents > 0 end operation\nend handler\n\nbook :: Int32 -> Bool uses Ledger\n\nlaw \"|booking a positive amount succeeds| is\n  definition :\n    for all (cents :: Int32 where cents > 0) => book cents = true end for all\n  end definition\nend law\n\nlaw \"|a refund is never booked twice| is\n  definition :\n    for all (cents :: Int32 where cents > 0) => book cents = book cents end for all\n  end definition\nend law\n\n-- A scratch area the laws may use; it can be emptied between laws, and\n-- laws running at the same time cannot interfere through it.\ntype Scratch is a record{  used :: Int32} end type\n\nresource Scratch is concurrent\n  acquire is Scratch record{ used = 0} end acquire\n  release scratch is unitValue end release\n  reset scratch is unitValue end reset\nend resource\nend unit\n")
  , ("harness_testing.lawspec", "-- The harness of example.harness: how its laws are tested. A harness\n-- cannot change what a law means; it chooses inputs, handlers, adequacy and\n-- how the tests run.\nharness example.harness.testing for example.harness is\n  -- Small orders: up to three items at a dollar each.\n  strategy smallOrder :: Order is\n    bind items :: Int32 from (one of 0, 1, 2, 3) in one of Order record{ items = items , total = (items * 100)} end bind\n  end strategy\n  -- Bulk orders: more than ten items with realistic totals, built directly\n  -- (well below the largest Int32, where adding to a total overflows).\n  strategy bulkItems :: (n :: Int32 where n >= 11 && n <= 1000) is any end strategy\n  strategy bulkTotal :: (n :: Int32 where n >= 0 && n <= 999999) is any end strategy\n  strategy bulkOrder :: Order is\n    bind items :: Int32 from bulkItems in bind total :: Int32 from bulkTotal in one of Order record{ items = items , total = total} end bind end bind\n  end strategy\n  strategy orders :: Order is frequency 9 smallOrder, 1 bulkOrder end strategy\n\n  tags pricing\n  test with fakeLedger\n  order random\n  parallel\n\n  for law \"|a discount is never more than the total|\n    use orders for order\n    cover 5% \"empty order\" when isEmpty order\n    classify totalOf order > 1000 as \"large\"\n    label if isEmpty order then \"empty\" else \"some items\" end if\n    timeout 10 s\n  end for law\n\n  for law \"|rounding is idempotent|\n    target maximize cents\n    repeat 2\n    retry flaky 1\n\n  end for law\n  for law \"|rounding never lowers a price|\n    known discrepancy \"rounds half down; see PRICE-12\"\n\n  end for law\n  for law \"|a refund is never booked twice|\n    skip \"refunds are not booked yet\"\n\n  end for law\n  for laws \"|booking a positive amount succeeds|, \"|positive amounts are accepted|\n    tags ledger\n\n  end for laws\n  share Scratch per unit\n  benchmark `discount of a bulk order` is discount (Order record{ items = 30 , total = 50000}) end benchmark\n  -- book uses Ledger: the benchmark runs under its production handler.\n  benchmark `booking a payment` is book 500 end benchmark\nend harness\n")
  , ("indexed_arithmetic.lawspec", "unit example.arithmetic\n\n-- Index equations may use natural arithmetic: + - * div mod ^. Subtraction\n-- never truncates, so `m - 1` requires m >= 1 of every value. A variable bound\n-- by several fields makes those fields' indices equal.\ntype Row (n :: Whole) is one of\n  | End where n = 0\n  | Cell of type record{ head :: Int8 tail :: Row m} where n = m + 1\nend type\n\n-- A perfect tree: both subtrees share one height.\ntype Perfect (n :: Whole) is one of\n  | Leaf of type Int8 where n = 0\n  | Node of type record{ left :: Perfect m right :: Perfect m} where n = m + 1\nend type\n\n-- A grid's index is its number of cells.\ntype Grid (n :: Whole) is one of\n  | Grid of type record{ rows :: Row r columns :: Row c} where n = r * c\nend type\n\n-- Two halves of one length.\ntype Halves (n :: Whole) is one of\n  | Halves of type record{ front :: Row m back :: Row m} where n = m + m\nend type\n\n-- The number of whole pairs, and the length after the first element.\ntype Pairs (n :: Whole) is one of\n  | Pairs of type Row m where n = m div 2\nend type\n\ntype Rest (n :: Whole) is one of\n  | Rest of type Row m where n = m - 1\nend type\n\nmirror :: (tree :: Perfect n) -> (r :: Perfect n)\narea :: (grid :: Grid n) -> Integer\nduplicate :: (xs :: Row m) -> (r :: Halves (m + m))\ncountPairs :: (xs :: Row m) -> (r :: Pairs (m div 2))\n-- `k + 1` binds k to one less than the argument's length.\ndropFirst :: (xs :: Row (k + 1)) -> (r :: Rest k)\n\n-- Checked definitions. Matching a Node tells the prover its subtrees share a\n-- height, so mirrorP's result height is proved; so is transposeG's, as r * c\n-- and c * r are the same product. stackRows' claim, (r + r) * c = 2 * (r * c),\n-- is beyond linear arithmetic: it is checked on each result instead.\nfunction mirrorP (tree :: Perfect n) -> Perfect n is\n  first matching case of tree :\n    when Leaf v then Leaf v\n    when Node record{ left = l , right = r} then Node record{ left = (mirrorP r)\n        , right = (mirrorP l)}\n  end case\nend function\n\nfunction transposeG (grid :: Grid n) -> Grid n is\n  first matching case of grid :\n    when Grid record{ rows = rows , columns = columns} then Grid record{ rows =\n        columns , columns = rows}\n  end case\nend function\n\nfunction appendRow (xs :: Row n) (ys :: Row m) -> Row (n + m) is\n  first matching case of xs :\n    when End then ys\n    when Cell record{ head = h , tail = t} then Cell record{ head = h , tail =\n        (appendRow t ys)}\n  end case\nend function\n\nfunction stackRows (grid :: Grid n) -> Grid (2 * n) is\n  first matching case of grid :\n    when Grid record{ rows = rows , columns = columns} then Grid record{ rows =\n        (appendRow rows rows) , columns = columns}\n  end case\nend function\n\nlaw \"|mirror agrees with the proved definition| is\n  definition :\n    for all (tree :: Perfect 3) => mirror tree = mirrorP tree end for all\n  end definition\nend law\n\nlaw \"|transposing keeps the area| is\n  definition :\n    for all (grid :: Grid 12) => area (transposeG grid) = 12 end for all\n  end definition\nend law\n\nlaw \"|stacking doubles the area| is\n  definition :\n    for all (grid :: Grid 6) => area (stackRows grid) = 12 end for all\n  end definition\nend law\n\n-- Without a fixed height, ordinary checked generation retains the balance\n-- guards. The harness constructs the fixed-height cases below.\nlaw \"|mirroring twice restores a tree| is\n  definition :\n    for all (tree :: Perfect n) => mirror (mirror tree) = tree end for all\n  end definition\nend law\n\nlaw \"|mirroring keeps the height| is\n  definition :\n    for all (tree :: Perfect 3) => nOfPerfect (mirror tree) = 3 end for all\n  end definition\nend law\n\nlaw \"|a grid of six cells| is\n  definition :\n    for all (grid :: Grid 6) => area grid = 6 end for all\n  end definition\nend law\n\n-- The harness chooses every factorization of twelve.\nlaw \"|the area is the index| is\n  definition :\n    for all (grid :: Grid 12) => area grid = nOfGrid grid end for all\n  end definition\nend law\n\nlaw \"|duplicating makes equal halves| is\n  definition :\n    for all (xs :: Row m) => nOfHalves (duplicate xs) = m + m end for all\n  end definition\nend law\n\n-- The harness constructs equal-length halves with independent cell values.\nlaw \"|halves of six| is\n  definition :\n    for all (halves :: Halves 6) => nOfHalves halves = 6 end for all\n  end definition\nend law\n\nlaw \"|seven elements make three pairs| is\n  definition :\n    for all (xs :: Row 7) => nOfPairs (countPairs xs) = 3 end for all\n  end definition\nend law\n\n-- A child may have a larger index than its parent: Pairs 2 holds four or five.\nlaw \"|two pairs| is\n  definition :\n    for all (p :: Pairs 2) => nOfPairs p = 2 end for all\n  end definition\nend law\n\nlaw \"|the rest is one shorter| is\n  definition :\n    for all (xs :: Row (k + 1)) => nOfRest (dropFirst xs) = k end for all\n  end definition\nend law\n\nlaw \"|the rest of three| is\n  definition :\n    for all (r :: Rest 3) => nOfRest r = 3 end for all\n  end definition\nend law\n\nharness example.arithmetic.shapes for example.arithmetic is\n\n  strategy row0 of type Row 0 is\n    one of End\n  end strategy\n\n  strategy row1 of type Row 1 is\n    bind tail of type Row 0 from row0 in\n      bind head of type Int8 from any in\n        one of Cell record{head = head, tail = tail}\n      end bind\n    end bind\n  end strategy\n\n  strategy row2 of type Row 2 is\n    bind tail of type Row 1 from row1 in\n      bind head of type Int8 from any in\n        one of Cell record{head = head, tail = tail}\n      end bind\n    end bind\n  end strategy\n\n  strategy row3 of type Row 3 is\n    bind tail of type Row 2 from row2 in\n      bind head of type Int8 from any in\n        one of Cell record{head = head, tail = tail}\n      end bind\n    end bind\n  end strategy\n\n  strategy row4 of type Row 4 is\n    bind tail of type Row 3 from row3 in\n      bind head of type Int8 from any in\n        one of Cell record{head = head, tail = tail}\n      end bind\n    end bind\n  end strategy\n\n  strategy row5 of type Row 5 is\n    bind tail of type Row 4 from row4 in\n      bind head of type Int8 from any in\n        one of Cell record{head = head, tail = tail}\n      end bind\n    end bind\n  end strategy\n\n  strategy row6 of type Row 6 is\n    bind tail of type Row 5 from row5 in\n      bind head of type Int8 from any in\n        one of Cell record{head = head, tail = tail}\n      end bind\n    end bind\n  end strategy\n\n  strategy row7 of type Row 7 is\n    bind tail of type Row 6 from row6 in\n      bind head of type Int8 from any in\n        one of Cell record{head = head, tail = tail}\n      end bind\n    end bind\n  end strategy\n\n  strategy perfect0 of type Perfect 0 is\n    bind value of type Int8 from any in\n      one of Leaf value\n    end bind\n  end strategy\n\n  strategy perfect1 of type Perfect 1 is\n    bind left of type Perfect 0 from perfect0 in\n      bind right of type Perfect 0 from perfect0 in\n        one of Node record{left = left, right = right}\n      end bind\n    end bind\n  end strategy\n\n  strategy perfect2 of type Perfect 2 is\n    bind left of type Perfect 1 from perfect1 in\n      bind right of type Perfect 1 from perfect1 in\n        one of Node record{left = left, right = right}\n      end bind\n    end bind\n  end strategy\n\n  strategy perfect3 of type Perfect 3 is\n    bind left of type Perfect 2 from perfect2 in\n      bind right of type Perfect 2 from perfect2 in\n        one of Node record{left = left, right = right}\n      end bind\n    end bind\n  end strategy\n\n  strategy grid1by6 of type Grid 6 is\n    bind rows of type Row 1 from row1 in\n      bind columns of type Row 6 from row6 in\n        one of Grid record{rows = rows, columns = columns}\n      end bind\n    end bind\n  end strategy\n\n  strategy grid2by3 of type Grid 6 is\n    bind rows of type Row 2 from row2 in\n      bind columns of type Row 3 from row3 in\n        one of Grid record{rows = rows, columns = columns}\n      end bind\n    end bind\n  end strategy\n\n  strategy grid3by2 of type Grid 6 is\n    bind rows of type Row 3 from row3 in\n      bind columns of type Row 2 from row2 in\n        one of Grid record{rows = rows, columns = columns}\n      end bind\n    end bind\n  end strategy\n\n  strategy grid6by1 of type Grid 6 is\n    bind rows of type Row 6 from row6 in\n      bind columns of type Row 1 from row1 in\n        one of Grid record{rows = rows, columns = columns}\n      end bind\n    end bind\n  end strategy\n\n  strategy grid6 of type Grid 6 is\n    frequency 1 grid1by6, 1 grid2by3, 1 grid3by2, 1 grid6by1\n  end strategy\n\n  strategy row12 of type Row 12 is\n    bind value0 of type Int8 from any in\n      bind value1 of type Int8 from any in\n        bind value2 of type Int8 from any in\n          bind value3 of type Int8 from any in\n            bind value4 of type Int8 from any in\n              bind value5 of type Int8 from any in\n                bind value6 of type Int8 from any in\n                  bind value7 of type Int8 from any in\n                    bind value8 of type Int8 from any in\n                      bind value9 of type Int8 from any in\n                        bind value10 of type Int8 from any in\n                          bind value11 of type Int8 from any in\n                            one of (Cell record{head = value0, tail = (Cell record{head = value1, tail = (Cell record{head = value2, tail = (Cell record{head = value3, tail = (Cell record{head = value4, tail = (Cell record{head = value5, tail = (Cell record{head = value6, tail = (Cell record{head = value7, tail = (Cell record{head = value8, tail = (Cell record{head = value9, tail = (Cell record{head = value10, tail = (Cell record{head = value11, tail = End})})})})})})})})})})})})\n                          end bind\n                        end bind\n                      end bind\n                    end bind\n                  end bind\n                end bind\n              end bind\n            end bind\n          end bind\n        end bind\n      end bind\n    end bind\n  end strategy\n\n  strategy grid1by12 of type Grid 12 is\n    bind rows of type Row 1 from row1 in\n      bind columns of type Row 12 from row12 in\n        one of Grid record{rows = rows, columns = columns}\n      end bind\n    end bind\n  end strategy\n\n  strategy grid2by6 of type Grid 12 is\n    bind rows of type Row 2 from row2 in\n      bind columns of type Row 6 from row6 in\n        one of Grid record{rows = rows, columns = columns}\n      end bind\n    end bind\n  end strategy\n\n  strategy grid3by4 of type Grid 12 is\n    bind rows of type Row 3 from row3 in\n      bind columns of type Row 4 from row4 in\n        one of Grid record{rows = rows, columns = columns}\n      end bind\n    end bind\n  end strategy\n\n  strategy grid4by3 of type Grid 12 is\n    bind rows of type Row 4 from row4 in\n      bind columns of type Row 3 from row3 in\n        one of Grid record{rows = rows, columns = columns}\n      end bind\n    end bind\n  end strategy\n\n  strategy grid6by2 of type Grid 12 is\n    bind rows of type Row 6 from row6 in\n      bind columns of type Row 2 from row2 in\n        one of Grid record{rows = rows, columns = columns}\n      end bind\n    end bind\n  end strategy\n\n  strategy grid12by1 of type Grid 12 is\n    bind rows of type Row 12 from row12 in\n      bind columns of type Row 1 from row1 in\n        one of Grid record{rows = rows, columns = columns}\n      end bind\n    end bind\n  end strategy\n\n  strategy grid12 of type Grid 12 is\n    frequency 1 grid1by12, 1 grid2by6, 1 grid3by4, 1 grid4by3, 1 grid6by2, 1\n    grid12by1\n  end strategy\n\n  strategy equalHalves of type Halves 6 is\n    bind front of type Row 3 from row3 in\n      bind back of type Row 3 from row3 in\n        one of Halves record{front = front, back = back}\n      end bind\n    end bind\n  end strategy\n\n  strategy pairs4 of type Pairs 2 is\n    bind row of type Row 4 from row4 in\n      one of Pairs row\n    end bind\n  end strategy\n\n  strategy pairs5 of type Pairs 2 is\n    bind row of type Row 5 from row5 in\n      one of Pairs row\n    end bind\n  end strategy\n\n  strategy twoPairs of type Pairs 2 is frequency 1 pairs4, 1 pairs5 end strategy\n\n  strategy rest3 of type Rest 3 is\n    bind row of type Row 4 from row4 in\n      one of Rest row\n    end bind\n  end strategy\n\n  for law \"|mirror agrees with the proved definition|\n    use perfect3 for tree\n  end for law\n  for law \"|mirroring keeps the height|\n    use perfect3 for tree\n  end for law\n  for law \"|transposing keeps the area|\n    use grid12 for grid\n  end for law\n  for law \"|stacking doubles the area|\n    use grid6 for grid\n  end for law\n  for law \"|a grid of six cells|\n    use grid6 for grid\n  end for law\n  for law \"|the area is the index|\n    use grid12 for grid\n  end for law\n  for law \"|halves of six|\n    use equalHalves for halves\n  end for law\n  for law \"|seven elements make three pairs|\n    use row7 for xs\n  end for law\n  for law \"|two pairs|\n    use twoPairs for p\n  end for law\n  for law \"|the rest of three|\n    use rest3 for r\n  end for law\n\nend harness\nend unit\n")
  , ("indexed_families.lawspec", "unit example.indexed\n\n-- A list indexed by its length. Each constructor states how it changes the\n-- index; nOfVec is the checked measure that recomputes it from a value.\ntype Vec (n :: Whole) (a :: Type) is one of\n  | VNil where n = 0\n  | VCons of type record{ head :: a tail :: Vec m a} where n = m + 1\nend type\n\n-- A binary tree indexed by its number of values.\ntype Tree (n :: Whole) (a :: Type) is one of\n  | Tip where n = 0\n  | Bin of type record{ left :: Tree l a value :: a right :: Tree r a} where n =\n  l + r + 1\nend type\n\n-- Result indices are checked contracts over the native implementations.\nreplicate :: (n :: Whole where n < 64) -> (x :: Int8) -> (r :: Vec n Int8)\nappend :: (xs :: Vec n Int8) -> (ys :: Vec m Int8) -> (r :: Vec (n + m) Int8)\nzip :: (xs :: Vec n Int8) -> (ys :: Vec n Bool) -> (r :: Vec n Bool)\nflatten :: (tree :: Tree n Int8) -> (r :: Vec n Int8)\n\n-- Checked definitions whose result indices are proved statically, by\n-- structural induction over the constructor equations. They need no runtime\n-- postcondition, and serve as reference models for the native adapters.\nfunction concatV (xs :: Vec n Int8) (ys :: Vec m Int8) -> Vec (n + m) Int8 is\n  first matching case of xs :\n    when VNil then ys\n    when VCons record{ head = h , tail = t} then VCons record{ head = h , tail =\n        (concatV t ys)}\n  end case\nend function\n\nfunction flattenV (tree :: Tree n Int8) -> Vec n Int8 is\n  first matching case of tree :\n    when Tip then VNil\n    when Bin record{ left = l , value = v , right = r} then concatV (flattenV l)\n      (VCons record{ head = v , tail = (flattenV r)})\n  end case\nend function\n\nlaw \"|append agrees with the proved definition| is\n  definition :\n    for all (xs :: Vec n Int8) (ys :: Vec m Int8) => append xs ys = concatV xs\n      ys end for all\n  end definition\nend law\n\nlaw \"|flatten agrees with the proved definition| is\n  definition :\n    for all (tree :: Tree 4 Int8) => flatten tree = flattenV tree end for all\n  end definition\nend law\n\nlaw \"|replicate has the requested length| is\n  definition :\n    for all (n :: Whole where n < 16) (x :: Int8) => nOfVec (replicate n x) = n\n    end for all\n  end definition\n  example \"|three copies| :\n    n = 3\n    x = 7\n    expect nOfVec (replicate n x) = 3\n  end example\nend law\n\nlaw \"|append adds lengths| is\n  definition :\n    for all (xs :: Vec n Int8) (ys :: Vec m Int8) =>\n      nOfVec (append xs ys) = n + m end for all\n  end definition\nend law\n\n-- The harness constructs the fixed shape with independent scalar draws.\nlaw \"|vectors of three elements| is\n  definition :\n    for all (xs :: Vec 3 Int8) => nOfVec (append xs xs) = 6 end for all\n  end definition\nend law\n\n-- A shared index constrains the second input by the first.\nlaw \"|zip preserves a shared length| is\n  definition :\n    for all (xs :: Vec n Int8) (ys :: Vec n Bool) => nOfVec (zip xs ys) = n\n    end for all\n  end definition\nend law\n\n-- The harness samples every binary shape of this fixed size.\nlaw \"|flattening five values| is\n  definition :\n    for all (tree :: Tree 5 Int8) => nOfVec (flatten tree) = 5 end for all\n  end definition\nend law\n\nfunction branch (left of type Tree n Int8) (item of type Int8)\n  (right of type Tree m Int8) -> Tree (n + m + 1) Int8 is\n  Bin record{left = left, value = item, right = right}\nend function\n\nharness example.indexed.shapes for example.indexed is\n\n  strategy threeValues of type Vec 3 Int8 is\n    bind value0 of type Int8 from any in\n      bind value1 of type Int8 from any in\n        bind value2 of type Int8 from any in\n          one of (VCons record{head = value0, tail = (VCons record{head = value1, tail = (VCons record{head = value2, tail = VNil})})})\n        end bind\n      end bind\n    end bind\n  end strategy\n\n  strategy tree4 of type Tree 4 Int8 is\n    bind value0 of type Int8 from any in\n      bind value1 of type Int8 from any in\n        bind value2 of type Int8 from any in\n          bind value3 of type Int8 from any in\n            one of (branch Tip value0 (branch Tip value1 (branch Tip value2 (branch Tip value3 Tip)))),\n            (branch Tip value0 (branch Tip value1 (branch (branch Tip value3 Tip) value2 Tip))),\n            (branch Tip value0 (branch (branch Tip value2 Tip) value1 (branch Tip value3 Tip))),\n            (branch Tip value0 (branch (branch Tip value2 (branch Tip value3 Tip)) value1 Tip)),\n            (branch Tip value0 (branch (branch (branch Tip value3 Tip) value2 Tip) value1 Tip)),\n            (branch (branch Tip value1 Tip) value0 (branch Tip value2 (branch Tip value3 Tip))),\n            (branch (branch Tip value1 Tip) value0 (branch (branch Tip value3 Tip) value2 Tip)),\n            (branch (branch Tip value1 (branch Tip value2 Tip)) value0 (branch Tip value3 Tip)),\n            (branch (branch (branch Tip value2 Tip) value1 Tip) value0 (branch Tip value3 Tip)),\n            (branch (branch Tip value1 (branch Tip value2 (branch Tip value3 Tip))) value0 Tip),\n            (branch (branch Tip value1 (branch (branch Tip value3 Tip) value2 Tip)) value0 Tip),\n            (branch (branch (branch Tip value2 Tip) value1 (branch Tip value3 Tip)) value0 Tip),\n            (branch (branch (branch Tip value2 (branch Tip value3 Tip)) value1 Tip) value0 Tip),\n            (branch (branch (branch (branch Tip value3 Tip) value2 Tip) value1 Tip) value0 Tip)\n          end bind\n        end bind\n      end bind\n    end bind\n  end strategy\n\n  strategy tree5 of type Tree 5 Int8 is\n    bind value0 of type Int8 from any in\n      bind value1 of type Int8 from any in\n        bind value2 of type Int8 from any in\n          bind value3 of type Int8 from any in\n            bind value4 of type Int8 from any in\n              one of (branch Tip value0 (branch Tip value1 (branch Tip value2 (branch Tip value3 (branch Tip value4 Tip))))),\n              (branch Tip value0 (branch Tip value1 (branch Tip value2 (branch (branch Tip value4 Tip) value3 Tip)))),\n              (branch Tip value0 (branch Tip value1 (branch (branch Tip value3 Tip) value2 (branch Tip value4 Tip)))),\n              (branch Tip value0 (branch Tip value1 (branch (branch Tip value3 (branch Tip value4 Tip)) value2 Tip))),\n              (branch Tip value0 (branch Tip value1 (branch (branch (branch Tip value4 Tip) value3 Tip) value2 Tip))),\n              (branch Tip value0 (branch (branch Tip value2 Tip) value1 (branch Tip value3 (branch Tip value4 Tip)))),\n              (branch Tip value0 (branch (branch Tip value2 Tip) value1 (branch (branch Tip value4 Tip) value3 Tip))),\n              (branch Tip value0 (branch (branch Tip value2 (branch Tip value3 Tip)) value1 (branch Tip value4 Tip))),\n              (branch Tip value0 (branch (branch (branch Tip value3 Tip) value2 Tip) value1 (branch Tip value4 Tip))),\n              (branch Tip value0 (branch (branch Tip value2 (branch Tip value3 (branch Tip value4 Tip))) value1 Tip)),\n              (branch Tip value0 (branch (branch Tip value2 (branch (branch Tip value4 Tip) value3 Tip)) value1 Tip)),\n              (branch Tip value0 (branch (branch (branch Tip value3 Tip) value2 (branch Tip value4 Tip)) value1 Tip)),\n              (branch Tip value0 (branch (branch (branch Tip value3 (branch Tip value4 Tip)) value2 Tip) value1 Tip)),\n              (branch Tip value0 (branch (branch (branch (branch Tip value4 Tip) value3 Tip) value2 Tip) value1 Tip)),\n              (branch (branch Tip value1 Tip) value0 (branch Tip value2 (branch Tip value3 (branch Tip value4 Tip)))),\n              (branch (branch Tip value1 Tip) value0 (branch Tip value2 (branch (branch Tip value4 Tip) value3 Tip))),\n              (branch (branch Tip value1 Tip) value0 (branch (branch Tip value3 Tip) value2 (branch Tip value4 Tip))),\n              (branch (branch Tip value1 Tip) value0 (branch (branch Tip value3 (branch Tip value4 Tip)) value2 Tip)),\n              (branch (branch Tip value1 Tip) value0 (branch (branch (branch Tip value4 Tip) value3 Tip) value2 Tip)),\n              (branch (branch Tip value1 (branch Tip value2 Tip)) value0 (branch Tip value3 (branch Tip value4 Tip))),\n              (branch (branch Tip value1 (branch Tip value2 Tip)) value0 (branch (branch Tip value4 Tip) value3 Tip)),\n              (branch (branch (branch Tip value2 Tip) value1 Tip) value0 (branch Tip value3 (branch Tip value4 Tip))),\n              (branch (branch (branch Tip value2 Tip) value1 Tip) value0 (branch (branch Tip value4 Tip) value3 Tip)),\n              (branch (branch Tip value1 (branch Tip value2 (branch Tip value3 Tip))) value0 (branch Tip value4 Tip)),\n              (branch (branch Tip value1 (branch (branch Tip value3 Tip) value2 Tip)) value0 (branch Tip value4 Tip)),\n              (branch (branch (branch Tip value2 Tip) value1 (branch Tip value3 Tip)) value0 (branch Tip value4 Tip)),\n              (branch (branch (branch Tip value2 (branch Tip value3 Tip)) value1 Tip) value0 (branch Tip value4 Tip)),\n              (branch (branch (branch (branch Tip value3 Tip) value2 Tip) value1 Tip) value0 (branch Tip value4 Tip)),\n              (branch (branch Tip value1 (branch Tip value2 (branch Tip value3 (branch Tip value4 Tip)))) value0 Tip),\n              (branch (branch Tip value1 (branch Tip value2 (branch (branch Tip value4 Tip) value3 Tip))) value0 Tip),\n              (branch (branch Tip value1 (branch (branch Tip value3 Tip) value2 (branch Tip value4 Tip))) value0 Tip),\n              (branch (branch Tip value1 (branch (branch Tip value3 (branch Tip value4 Tip)) value2 Tip)) value0 Tip),\n              (branch (branch Tip value1 (branch (branch (branch Tip value4 Tip) value3 Tip) value2 Tip)) value0 Tip),\n              (branch (branch (branch Tip value2 Tip) value1 (branch Tip value3 (branch Tip value4 Tip))) value0 Tip),\n              (branch (branch (branch Tip value2 Tip) value1 (branch (branch Tip value4 Tip) value3 Tip)) value0 Tip),\n              (branch (branch (branch Tip value2 (branch Tip value3 Tip)) value1 (branch Tip value4 Tip)) value0 Tip),\n              (branch (branch (branch (branch Tip value3 Tip) value2 Tip) value1 (branch Tip value4 Tip)) value0 Tip),\n              (branch (branch (branch Tip value2 (branch Tip value3 (branch Tip value4 Tip))) value1 Tip) value0 Tip),\n              (branch (branch (branch Tip value2 (branch (branch Tip value4 Tip) value3 Tip)) value1 Tip) value0 Tip),\n              (branch (branch (branch (branch Tip value3 Tip) value2 (branch Tip value4 Tip)) value1 Tip) value0 Tip),\n              (branch (branch (branch (branch Tip value3 (branch Tip value4 Tip)) value2 Tip) value1 Tip) value0 Tip),\n              (branch (branch (branch (branch (branch Tip value4 Tip) value3 Tip) value2 Tip) value1 Tip) value0 Tip)\n            end bind\n          end bind\n        end bind\n      end bind\n    end bind\n  end strategy\n\n  for law \"|vectors of three elements|\n    use threeValues for xs\n  end for law\n  for law \"|flatten agrees with the proved definition|\n    use tree4 for tree\n  end for law\n  for law \"|flattening five values|\n    use tree5 for tree\n  end for law\n\nend harness\nend unit\n")
  , ("keywords.lawspec", "unit example.keywords\n\n-- A name that is a keyword of a target language is emitted there with a\n-- leading underscore: short is _short in Java, lambda is _lambda in Python,\n-- and class is _class wherever class is reserved. Other targets keep the name.\n\nfunction short (x :: Integer) -> Bool is x < 10 end function\nfunction double (x :: Integer) -> Integer is x + x end function\nfunction lambda (x :: Integer) -> Integer is x + 1 end function\nfunction fun (x :: Integer) -> Integer is x + 2 end function\nfunction loop (x :: Integer) -> Integer is x + 3 end function\nfunction deriving (x :: Integer) -> Integer is x + 4 end function\nfunction delete (x :: Integer) -> Integer is x + 5 end function\n\n-- An adapter, written by hand on each target as _class or class.\nclass :: Integer -> Integer\n\nlaw \"|keyword names are callable| is\n  definition :\n    for all (x :: Integer) =>\n      double x - x + lambda x + fun x + loop x + deriving x + delete x = 6 * x + 15 end for all\n  end definition\n  example \"|short| :\n    x = 3\n    expect short x = true\n  end example\nend law\n\nlaw \"|the class adapter doubles| is\n  definition :\n    for all (x :: Integer) => class x = double x end for all\n  end definition\nend law\nend unit\n")
  , ("limits.lawspec", "unit example.limits\n\n-- A workflow with a rate limit, for the resilience suite: two calls per\n-- second, rejecting the rest. Its own unit, so the suite's checks can call it\n-- on every target (a Haskell workflow imports its steps' module).\ntype Ticket is a record{  number :: Int64} end type\n\nadmitTicket :: Ticket -> Either Text Ticket\n\nworkflow limited :: Ticket -> Either _ Ticket is\n  admitTicket :: Ticket -> Either Text Ticket\n    rateLimit tokenBucket 2 1s reject\nend workflow\n\n-- A workflow that compensates: when charging fails, the reserved seat is\n-- released.\nreserveSeat :: Ticket -> Either Text Ticket\nchargeCard :: Ticket -> Either Text Ticket\nreleaseSeat :: Ticket -> Bool\n\nworkflow book :: Ticket -> Either _ Ticket is\n  reserveSeat :: Ticket -> Either Text Ticket\n    compensate releaseSeat\n  chargeCard :: Ticket -> Either Text Ticket\nend workflow\n\n-- An asynchronous step within a timeout: the quote for ticket -1 is slow\n-- (600ms), so its stage times out.\nasync fetchQuote :: Ticket -> Either Text Ticket\n\nworkflow quoted :: Ticket -> Either _ Ticket is\n  fetchQuote :: Ticket -> Either Text Ticket\n    timeout 200ms\nend workflow\n\n-- An asynchronous step with a hedge: ticket -2's first quote stalls,\n-- so a second starts after 50ms and answers first.\nasync hedgeQuote :: Ticket -> Either Text Ticket\n\nworkflow hedged :: Ticket -> Either _ Ticket is\n  hedgeQuote :: Ticket -> Either Text Ticket\n    hedge 50ms\nend workflow\nend unit\n")
  , ("list_contracts.lawspec", "unit example.list_contracts\n\nfunction keep (xs :: List (value :: Int8 where value > 0))\n  -> List (value :: Int8 where value > 0)\nis xs end function\n\nfunction stronger (xs :: List (value :: Int8 where value > 10)) -> List Int8 is\n  keep (copypositive xs)\nend function\n\nfunction positive (value :: a) -> Bool requires Integer a is value > 0 end function\n\nfunction keephelper (xs :: List (value :: a where positive value))\n  -> List a requires Integer a\nis xs end function\n\nfunction reuse (xs :: List (value :: Int8 where positive value)) -> List Int8 is\n  keephelper xs\nend function\n\nfunction empty (value :: Int8) -> List (element :: Int8 where false) is [] end function\n\nfunction singleton (value :: Int8 where value > 0)\n  -> List (element :: Int8 where element > 0)\nis [value] end function\n\n\nlaw \"|stronger domains satisfy the callee| is\n  definition : for all (xs :: List (value :: Int8 where value > 10)) =>\n    stronger xs = xs end for all\n  end definition\n  example \"|positive input| : xs = [11, 127] expect stronger xs = [11, 127] end example\nend law\n\nlaw \"|generic predicates keep their scope| is\n  definition : for all (xs :: List (value :: Int8 where value > 0)) =>\n    reuse xs = xs end for all\n  end definition\n  example \"|empty| : xs = [] expect reuse xs = [] end example\n  example \"|nonempty| : xs = [1, 2] expect reuse xs = [1, 2] end example\nend law\n\nlaw \"|empty output satisfies an impossible element domain| is\n  definition : for all (value :: Int8) => empty value = [] end for all end definition\n  example \"|zero| : value = 0 expect empty value = [] end example\nend law\n\nlaw \"|constructed output satisfies its contract| is\n  definition : for all (value :: Int8 where value > 0) => singleton value = [value] end for all end definition\n  example \"|maximum| : value = 127 expect singleton value = [127] end example\nend law\n\n\nfunction sumreciprocal (xs :: List (value :: Int8 where value != 0)) -> Rational is\n  first matching case of xs :\n  when Nil then 0\n  when Cons first rest then unwrapnonzero (wrapnonzero (nonzero first)) + sumreciprocal rest\n  end case\nend function\n\nfunction sumrows (rows :: List (List (value :: Int8 where value != 0))) -> Rational is\n  first matching case of rows :\n  when Nil then 0\n  when Cons first rest then sumreciprocal first + sumrows rest\n  end case\nend function\n\nfunction positivetail (xs :: List (value :: Int8 where value > 0))\n  -> List (value :: Int8 where value > 0)\nis\n  first matching case of xs : when Nil then [] when Cons first rest then rest end case\nend function\n\nfunction positivefirst (xs :: List (value :: Int8 where value > 0))\n  -> (result :: Int8 where result > 0)\nis\n  first matching case of xs : when Nil then 1 when Cons first rest then first end case\nend function\n\n\nlaw \"|reciprocal sum uses each nonzero head| is\n  definition : for all (value :: Int8 where value != 0) =>\n    sumreciprocal [value] = 1 / value end for all\n  end definition\n  example \"|half| : value = 2 expect sumreciprocal [value] = rational(1, 2) end example\nend law\n\nlaw \"|nested membership keeps row contracts| is\n  definition : for all (value :: Int8 where value != 0) =>\n    sumrows [[], [value]] = 1 / value end for all\n  end definition\n  example \"|negative half| : value = -2 expect sumrows [[], [value]] = rational(-1, 2) end example\nend law\n\nlaw \"|tail preserves its positive elements| is\n  definition : for all (first :: Int8 where first > 0)\n    (second :: Int8 where second > 0) => positivetail [first, second] = [second] end for all\n  end definition\n  example \"|two values| : first = 1 second = 2 expect positivetail [first, second] = [2] end example\nend law\n\n-- Recursive calls supply their verified result contract by structural induction.\nfunction copypositive (xs :: List (value :: Int8 where value > 0))\n  -> List (value :: Int8 where value > 0)\nis\n  first matching case of xs :\n  when Nil then []\n  when Cons first rest then Cons first (copypositive rest)\n  end case\nend function\n\nfunction nonzero (value :: Int8 where value != 0)\n  -> (result :: Int8 where result != 0)\nis value end function\n\nfunction wrapnonzero (value :: Int8 where value != 0)\n  -> Maybe (result :: Int8 where result != 0)\nis Present value end function\n\nfunction unwrapnonzero (value :: Maybe (element :: Int8 where element != 0))\n  -> Rational\nis\n  first matching case of value :\n  when Absent then 0\n  when Present element then selectnonzero (Left element)\n  end case\nend function\n\nfunction selectnonzero (value :: Either (element :: Int8 where element != 0) Bool)\n  -> Rational\nis\n  first matching case of value :\n  when Left element then 1 / element\n  when Right ignored then 0\n  end case\nend function\nend unit\n")
  , ("list_folds.lawspec", "unit example.listFolds\n\n-- Folds over a list. A left fold takes the elements first to last, a right\n-- fold last to first, and each target runs them with its own loop or fold.\n\nfunction add (a :: Integer) (b :: Integer) -> Integer is a + b end function\n\nfunction minus (a :: Integer) (b :: Integer) -> Integer is a - b end function\n\nfunction double (n :: Integer) -> Integer is n * 2 end function\n\nfunction isEven (n :: Integer) -> Bool is prelude.rem n 2 = 0 end function\n\nfunction before (x :: Integer) (xs :: List Integer) -> List Integer is Cons x xs end function\n\nfunction after (xs :: List Integer) (x :: Integer) -> List Integer is Cons x xs end function\n\nfunction weighted (factor :: Integer) (total :: Integer) (x :: Integer) -> Integer is\n  total + factor * x\nend function\n\nfunction tally (count :: Integer) (flag :: Bool) -> Integer is\n  if flag then count + 1 else count end if\nend function\n\n-- Folds inside definitions that take the list.\nfunction total (xs :: List Integer) -> Integer is prelude.foldLeft add 0 xs end function\n\nfunction difference (start :: Integer) (xs :: List Integer) -> Integer is\n  prelude.foldRight minus start xs\nend function\n\nfunction weightedTotal (factor :: Integer) (xs :: List Integer) -> Integer is\n  prelude.foldLeft (weighted factor) 0 xs\nend function\n\nfunction reversed (xs :: List Integer) -> List Integer is prelude.foldLeft after [] xs end function\n\nfunction copied (xs :: List Integer) -> List Integer is prelude.foldRight before [] xs end function\n\nfunction evenDoublesTotal (xs :: List Integer) -> Integer is\n  prelude.foldRight add 0 (prelude.map double (prelude.filter isEven xs))\nend function\n\n-- The same results written by hand, by structural recursion.\nfunction totalByHand (xs :: List Integer) -> Integer is\n  first matching case of xs:\n    when Nil then 0\n    when Cons x rest then x + totalByHand rest\n  end case\nend function\n\nfunction differenceByHand (start :: Integer) (xs :: List Integer) -> Integer is\n  first matching case of xs:\n    when Nil then start\n    when Cons x rest then x - differenceByHand start rest\n  end case\nend function\n\nfunction reversedOnto (done :: List Integer) (xs :: List Integer) -> List Integer is\n  first matching case of xs:\n    when Nil then done\n    when Cons x rest then reversedOnto (Cons x done) rest\n  end case\nend function\n\nfunction weightedOnto (factor :: Integer) (sofar :: Integer) (xs :: List Integer) -> Integer is\n  first matching case of xs:\n    when Nil then sofar\n    when Cons x rest then weightedOnto factor (sofar + factor * x) rest\n  end case\nend function\n\nlaw \"|a left fold groups from the first element and a right fold from the last| is\n  definition :\n    prelude.foldLeft minus 10 [1, 2, 3] = 4\n    and prelude.foldRight minus 10 [1, 2, 3] = -8\n    and prelude.foldLeft add 0 [1, 2, 3] = 6\n    and prelude.foldRight add 0 [1, 2, 3] = 6\n  end definition\nend law\n\nlaw \"|a right fold rebuilds the list and a left fold reverses it| is\n  definition :\n    prelude.foldRight before [] [1, 2, 3] = [1, 2, 3]\n    and prelude.foldLeft after [] [1, 2, 3] = [3, 2, 1]\n    and reversed [1, 2, 3] = [3, 2, 1]\n    and copied [1, 2, 3] = [1, 2, 3]\n  end definition\nend law\n\nlaw \"|an empty list gives the initial value| is\n  definition :\n    prelude.foldLeft add 7 [] = 7\n    and prelude.foldRight minus 7 [] = 7\n    and prelude.foldRight before [4] [] = [4]\n    and total [] = 0\n    and difference 5 [] = 5\n  end definition\nend law\n\nlaw \"|the accumulator may have a type other than the element's| is\n  definition :\n    prelude.foldLeft tally 0 [true, false, true] = 2\n    and prelude.foldLeft tally 3 [false] = 3\n  end definition\nend law\n\nlaw \"|a step may be a partial application or a composition| is\n  definition :\n    prelude.foldLeft (weighted (1 + 1)) 0 [1, 2, 3] = 12\n    and weightedTotal 3 [1, 2] = 9\n    and prelude.foldLeft (add . double) 1 [1, 1] = 7\n  end definition\nend law\n\nlaw \"|a mapped and filtered list is folded| is\n  definition :\n    prelude.foldLeft minus 0 (prelude.map double [1, 2, 3]) = -12\n    and prelude.foldRight before [] (prelude.filter isEven [1, 2, 3, 4]) = [2, 4]\n    and evenDoublesTotal [1, 2, 3, 4] = 12\n  end definition\nend law\n\nlaw \"|a left fold agrees with the sum written by hand| is\n  definition :\n    for all (xs :: List Integer) =>\n      total xs = totalByHand xs\n    end for all\n  end definition\nend law\n\nlaw \"|a right fold agrees with the difference written by hand| is\n  definition :\n    for all (start :: Integer) (xs :: List Integer) =>\n      difference start xs = differenceByHand start xs\n    end for all\n  end definition\nend law\n\nlaw \"|a left fold agrees with the reversal written by hand| is\n  definition :\n    for all (xs :: List Integer) =>\n      reversed xs = reversedOnto [] xs and copied xs = xs\n    end for all\n  end definition\nend law\n\nlaw \"|a weighted fold agrees with the loop written by hand| is\n  definition :\n    for all (factor :: Integer) (xs :: List Integer) =>\n      weightedTotal factor xs = weightedOnto factor 0 xs\n    end for all\n  end definition\nend law\n\n-- concat joins the lists of a list in order.\nfunction flattened (xss :: List (List Integer)) -> List Integer is prelude.concat xss end function\n\nfunction flattenedByHand (xss :: List (List Integer)) -> List Integer is\n  first matching case of xss:\n    when Nil then []\n    when Cons xs rest then xs ++ flattenedByHand rest\n  end case\nend function\n\nlaw \"|concat joins the lists in order| is\n  definition :\n    prelude.concat [[1, 2], [], [3]] = [1, 2, 3]\n    and flattened [] = []\n    and flattened [[4], [5, 6]] = [4, 5, 6]\n  end definition\nend law\n\nlaw \"|concat agrees with the joining written by hand| is\n  definition :\n    for all (xss :: List (List Integer)) =>\n      flattened xss = flattenedByHand xss\n    end for all\n  end definition\nend law\n\n-- One definition for every type with the capability.\nfunction evensOf (values :: m Integer) -> m Integer requires Filterable m is\n  prelude.filter isEven values\nend function\n\nfunction summed (values :: m Integer) -> Integer requires Foldable m is\n  prelude.foldLeft add 0 values\nend function\n\nfunction repeated (x :: a) -> a requires Appendable a is x ++ x end function\n\nlaw \"|a definition may require a collection capability| is\n  definition :\n    evensOf [1, 2, 3, 4] = [2, 4]\n    and summed [1, 2, 3] = 6\n    and repeated [1, 2] = [1, 2, 1, 2]\n    and repeated \"ab\" = \"abab\"\n  end definition\nend law\nend unit\n")
  , ("list_mapping.lawspec", "unit example.listMapping\n\n-- One map and one filter over a list, the same on every target.\n\nfunction double (n :: Integer) -> Integer is n * 2 end function\n\nfunction isEven (n :: Integer) -> Bool is prelude.rem n 2 = 0 end function\n\nfunction scaled (factor :: Integer) (n :: Integer) -> Integer is factor * n end function\n\nfunction doubled (xs :: List Integer) -> List Integer is\n  prelude.map double xs\nend function\n\nfunction evens (xs :: List Integer) -> List Integer is\n  prelude.filter isEven xs\nend function\n\nfunction tripled (xs :: List Integer) -> List Integer is\n  prelude.map (scaled 3) xs\nend function\n\nfunction isPositive (n :: Integer) -> Bool is n > 0 end function\n\nfunction positives (xs :: List Integer) -> List Integer is\n  prelude.filter isPositive xs\nend function\n\n-- One definition for every type `map` works on: a list, or the success\n-- value of an Either.\nfunction quadrupled (values :: m Integer) -> m Integer requires Mappable m is\n  prelude.map double (prelude.map double values)\nend function\n\nfunction halved (n :: Integer) -> Either Text Integer is\n  if prelude.rem n 2 = 0 then Right (prelude.quot n 2) else Left \"odd\" end if\nend function\n\n-- An outline: an item, and the items under it.\ntype Outline is a record{\n  label :: Text,\n  children :: List Outline\n}\nend type\n\nfunction total (xs :: List Integer) -> Integer is\n  first matching case of xs:\n    when Nil then 0\n    when Cons x rest then x + total rest\n  end case\nend function\n\n-- An item counts itself and everything under it. The definition maps itself\n-- over the children, each of which is smaller than the item.\nfunction size (item :: Outline) -> Integer is\n  first matching case of item:\n    when record{children = children} then 1 + total (prelude.map size children)\n  end case\nend function\n\nfunction lengths (texts :: List Text) -> List Integer is\n  prelude.map prelude.length (prelude.map prelude.words texts)\nend function\n\nlaw \"|map keeps the order and the length| is\n  definition :\n    doubled [1, 2, 3] = [2, 4, 6] and doubled [] = [] and\n    prelude.map (scaled 3) [1, 2] = [3, 6]\n  end definition\nend law\n\nlaw \"|filter keeps the accepted elements in order| is\n  definition :\n    evens [1, 2, 3, 4] = [2, 4] and evens [1, 3] = [] and evens [] = []\n  end definition\nend law\n\nlaw \"|a map has as many elements as its list| is\n  definition :\n    for all (xs :: List Integer) =>\n      prelude.length (tripled xs) = prelude.length xs end for all\n  end definition\nend law\n\nlaw \"|every kept element is accepted| is\n  definition :\n    for all (xs :: List Integer) =>\n      prelude.all isEven (evens xs) end for all\n  end definition\nend law\n\nlaw \"|only positive elements are kept| is\n  definition :\n    for all (xs :: List Integer) =>\n      prelude.all isPositive (positives xs) end for all\n  end definition\nend law\n\nlaw \"|one definition maps a list and an Either| is\n  definition :\n    quadrupled [1, 2] = [4, 8] and quadrupled (halved 6) = Right 12 and quadrupled (halved 1) = Left \"odd\"\n  end definition\nend law\n\nlaw \"|mapping an Either keeps a failure| is\n  definition :\n    for all (n :: Integer) =>\n      quadrupled (halved (2 * n + 1)) = Left \"odd\" end for all\n  end definition\nend law\n\nlaw \"|an outline counts every item| is\n  definition :\n    size (Outline record{label = \"root\", children = [\n      Outline record{label = \"first\", children = [Outline record{label = \"leaf\", children = []}]},\n      Outline record{label = \"second\", children = []}\n    ]}) = 4\n  end definition\nend law\n\nlaw \"|map changes the element type| is\n  definition : lengths [\"a b\", \"\", \"one two three\"] = [2, 0, 3] end definition\nend law\nend unit\n")
  , ("list_refinements.lawspec", "unit example.list_refinements\n\nfunction above (floor :: Int8) (xs :: List Int8) -> Bool is\n  first matching case of xs :\n  when Nil then true\n  when Cons first rest then first > floor && above floor rest\n  end case\nend function\n\nfunction positiveRows (rows :: List (List Int8)) -> Bool is\n  first matching case of rows :\n  when Nil then true\n  when Cons first rest then above 0 first && positiveRows rest\n  end case\nend function\n\nlaw \"|each element is positive| is\n  definition : for all (xs :: List (value :: Int8 where value > 0)) =>\n    above 0 xs = true end for all\n  end definition\n  example \"|empty| : xs = [] expect above 0 xs = true end example\n  example \"|positive values| : xs = [1, 127] expect above 0 xs = true end example\nend law\n\nlaw \"|nested element domains| is\n  definition : for all (rows :: List (List (value :: Int8 where value > 0))) =>\n    positiveRows rows = true end for all\n  end definition\n  example \"|empty rows| : rows = [[], [1, 2]] expect positiveRows rows = true end example\nend law\n\nlaw \"|dependent elements| is\n  definition : for all (lawspecElement :: Int8)\n    (xs :: List (value :: Int8 where value > lawspecElement)) =>\n    above lawspecElement xs = true end for all\n  end definition\n  example \"|maximum prefix still permits empty| :\n    lawspecElement = 127 xs = [] expect above lawspecElement xs = true\n  end example\n  example \"|nonempty continuation| :\n    lawspecElement = 0 xs = [1, 2] expect above lawspecElement xs = true\n  end example\nend law\n\nlaw \"|division stays behind its guard| is\n  definition : for all\n    (xs :: List (value :: Int8 where value != 0 && 1 / value > 0)) =>\n    above 0 xs = true end for all\n  end definition\n  example \"|positive denominator| : xs = [1] expect above 0 xs = true end example\nend law\nend unit\n")
  , ("lists.lawspec", "unit example.lists\n\nreverse :: List Int32 -> List Int32\nsort :: List Int32 -> List Int32\nsorted :: List Int32 -> Bool\npermutation :: List Int32 -> List Int32 -> Bool\nechoMaybe :: Maybe (Maybe Bool) -> Maybe (Maybe Bool)\nechoEither :: Either (List Int32) (Maybe Bool) -> Either (List Int32) (Maybe Bool)\nechoNested :: List (Maybe (Either CodeUnit16 Bytes)) -> List (Maybe (Either CodeUnit16 Bytes))\n\nlaw \"|list involution| (f :: List a -> List a) requires Eq a is\n  definition : apply law \"|involution| f end definition\nend law\n\nlaw \"|reverse twice restores the list| is\n  definition : apply law \"|list involution| reverse end definition\n  example \"|ordered input| :\n    x = [3, 1, 2]\n    expect reverse x = [2, 1, 3]\n  end example\n  example \"|empty input| : x = [] expect reverse x = [] end example\nend law\n\nlaw \"|sorting is idempotent| is\n  definition : apply law \"|idempotent| sort end definition\n  example \"|duplicates| : x = [3, 1, 3] expect sort x = [1, 3, 3] end example\nend law\n\nlaw \"|sort produces sorted output| is\n  definition : for all (xs :: List Int32) => sorted (sort xs) end for all end definition\nend law\n\nlaw \"|sort preserves length| is\n  definition : for all (xs :: List Int32) => prelude.length (sort xs) = prelude.length xs end for all end definition\nend law\n\nlaw \"|sort preserves elements| is\n  definition : for all (xs :: List Int32) => permutation (sort xs) xs end for all end definition\nend law\n\nlaw \"|nonempty reversal preserves length| is\n  definition :\n    for all (xs :: List Int32 where prelude.length xs > 0) =>\n      prelude.length (reverse xs) = prelude.length xs end for all\n  end definition\nend law\n\nlaw \"|Maybe preserves nested absence| is\n  definition : for all (x :: Maybe (Maybe Bool)) => echoMaybe x = x end for all end definition\n  example \"|outer absence| : x = Absent expect echoMaybe x = Absent end example\n  example \"|inner absence| : x = Present Absent expect echoMaybe x = Present Absent end example\n  example \"|present| : x = Present (Present true) expect echoMaybe x = Present (Present true) end example\nend law\n\nlaw \"|Either preserves branches| is\n  definition : for all (x :: Either (List Int32) (Maybe Bool)) => echoEither x = x end for all end definition\n  example \"|left list| : x = Left [3, 1, 3] expect echoEither x = Left [3, 1, 3] end example\n  example \"|right absence| : x = Right Absent expect echoEither x = Right Absent end example\nend law\n\nlaw \"|nested raw values survive| is\n  definition : for all (xs :: List (Maybe (Either CodeUnit16 Bytes))) => echoNested xs = xs end for all end definition\n  example \"|surrogate and octets| :\n    xs = [Absent, Present (Left codeUnit16(55296)), Present (Right bytes([0, 255]))]\n    expect echoNested xs = [Absent, Present (Left codeUnit16(55296)), Present (Right bytes([0, 255]))]\n  end example\nend law\nend unit\n")
  , ("masking.lawspec", "unit example.masking\n\n-- A masking block says how a record's fields are shown wherever a value is\n-- rendered for people: in maskedCard, in violation messages and in LawSpec's\n-- own failure output. LawSpec generates a law for each masked field: what\n-- its mask hides shows in no rendering and no message.\n\ntype Card is a record{\n  holder :: (v :: Text where prelude.length v >= 1),\n  number :: (v :: Text where v matches regex \"[0-9]{13,19}\"),\n  contact :: (v :: Text where v matches format email),\n  limit :: (v :: Int32 where 0 <= v && v <= 50000),\n  pin :: Int32}\nend type\n\nmasking Card is\n  holder shown as hidden\n  number shown as last 4\n  contact shown as email\n  pin shown as hidden\nend masking\n\nfunction sample (u :: Unit) -> CardDraft is\n  CardDraft record{holder = \"Ann Lee\", number = \"4111111111111111\", contact = \"ann@example.org\", limit = 900, pin = 1234}\nend function\n\nlaw \"|a card is shown masked| is\n  definition :\n    maskedCardDraft (sample ()) = \"Card{holder=***, number=***1111, contact=a***@example.org, limit=900, pin=***}\"\n  end definition\nend law\n\nlaw \"|a violation shows the masked value| is\n  definition :\n    violationsOfCard (sample () with number = \"4111-1111\") = [Violation record{rule = \"number.pattern\", field = Present \"number\", message = \"number must match the regex \\\"[0-9]{13,19}\\\", but was ***1111\"}]\n  end definition\nend law\n\n-- `hash` shows a keyed BLAKE3 hash in a target's native rendering, where\n-- the application has set a key. maskedSession is a pure definition and has\n-- no key, so it hides the field. maskedSessionWith takes the key\n-- (acceptance/contracts-primitives/keyed_masking.lawspec); it is not here\n-- because only some targets have the keyed hash.\ntype Session is a record{\n  user :: Text,\n  token :: (v :: Text where prelude.length v >= 8)}\nend type\n\nmasking Session is\n  token shown as hash\nend masking\n\nlaw \"|a hashed field is hidden where there is no key| is\n  definition :\n    maskedSessionDraft (SessionDraft record{user = \"ann\", token = \"tok-12345678\"}) = \"Session{user=ann, token=***}\"\n  end definition\nend law\n\nlaw \"|a valid card is shown as its draft is| is\n  definition :\n    for all (card :: Card) => maskedCard card = maskedCardDraft (draftOfCard card) end for all\n  end definition\nend law\nend unit\n")
  , ("matchers.lawspec", "unit example.matchers\n\n-- Matchers are typed predicates that read like sentences. Each one is a\n-- Bool, so a law may combine them with && and ||, and an example may expect\n-- one to hold.\n\ntype Order is one of\n  | Pending  of type Int32\n  | Shipped of type record{ id :: Int32 carrier :: Text}\n  | Cancelled of type record{ id :: Int32 reason :: Maybe Text}\nend type\n\n-- Native adapters, written on each target.\nsortItems :: List Int32 -> List Int32\nuniqueTags :: List Text -> List Text\naverage :: Int32 -> Int32 -> Float64\nslug :: Text -> Text\nship :: Int32 -> Order\n\nlaw \"|sorting keeps every item| is\n  definition :\n    for all (xs :: List Int32) => sortItems xs has same items as xs end for all\n  end definition\n  example \"|duplicates stay| :\n    xs = [3, 1, 3]\n    expect sortItems xs = [1, 3, 3]\n  end example\nend law\n\nlaw \"|unique tags come from the input| is\n  definition :\n    for all (tags :: List Text) =>\n      uniqueTags tags is subset of tags && tags contains all of uniqueTags tags end for all\n  end definition\nend law\n\nlaw \"|unique tags keep each tag| is\n  definition :\n    for all (tags :: List Text) (tag :: Text) =>\n      tags contains tag implies uniqueTags tags contains tag end for all\n  end definition\nend law\n\nlaw \"|the average lies between the two| is\n  definition :\n    for all (a :: Int32) (b :: Int32) =>\n      average a b is within 0.5 of prelude.Float64 (prelude.quot (a + b) 2) end for all\n  end definition\nend law\n\nlaw \"|a slug is lowercase words joined by dashes| is\n  definition :\n    for all (title :: Text) =>\n      slug title matches regex \"([a-z0-9]+(-[a-z0-9]+)*)?\" end for all\n  end definition\n  example \"|a title| :\n    title = \"Hello World\"\n    expect slug title = \"hello-world\"\n    expect slug title starts with \"hello\"\n    expect slug title ends with \"world\"\n    expect slug title contains \"o-w\"\n  end example\nend law\n\nlaw \"|shipping gives a shipped order| is\n  definition :\n    for all (id :: Int32) => ship id matches Shipped record{ id = _ , carrier = _} end for all\n  end definition\n  example \"|the carrier is never empty| :\n    id = 7\n    expect ship id matches Shipped record{ id = 7 , carrier = _}\n    expect !(ship id matches Shipped record{ id = _ , carrier = \"\"})\n  end example\nend law\n\n-- Laws of the matchers themselves.\nlaw \"|having the same items is symmetric| is\n  definition :\n    for all (xs :: List Int8) (ys :: List Int8) =>\n      (xs has same items as ys) = (ys has same items as xs) end for all\n  end definition\nend law\n\nlaw \"|a list contains each of its items| is\n  definition :\n    for all (x :: Int8) (xs :: List Int8) => Cons x xs contains x end for all\n  end definition\nend law\n\nlaw \"|a list is a subset of itself| is\n  definition :\n    for all (xs :: List Int8) => xs is subset of xs && xs contains all of xs end for all\n  end definition\nend law\n\nlaw \"|a text starts and ends with itself| is\n  definition :\n    for all (t :: Text) => t starts with t && t ends with t && t contains t && t contains \"\" end for all\n  end definition\nend law\n\nlaw \"|a number is within any tolerance of itself| is\n  definition :\n    for all (x :: Int32) (d :: Int32 where d >= 0) => x is within d of x end for all\n  end definition\nend law\n\nlaw \"|a regex value matches like a literal| is\n  definition :\n    for all (t :: Text) => (t matches regex \"[a-c]*\") = (t matches regex \"[a-c]*\") end for all\n  end definition\nend law\nend unit\n")
  , ("matching.lawspec", "unit example.matching\n\n-- Rebuilding values checks both constructor identity and every payload field.\nlaw \"|list patterns preserve the head and tail| is\n  definition :\n    for all (xs :: List Int8) =>\n      (first matching case of xs :\n        when Nil then []\n        when Cons head tail then Cons head tail\n      end case) = xs end for all\n  end definition\nend law\n\nlaw \"|nested Maybe patterns preserve each absence state| is\n  definition :\n    for all (value :: Maybe (Maybe Bool)) =>\n      (first matching case of value :\n        when Absent then Absent\n        when Present inner then Present (first matching case of inner :\n            when Absent then Absent\n            when Present payload then Present payload\n          end case)\n      end case) = value end for all\n  end definition\nend law\n\nlaw \"|Either patterns preserve their constructor| is\n  definition :\n    for all (value :: Either (List Int8) (Maybe Bool)) =>\n      (first matching case of value :\n        when Left items then Left items\n        when Right optional then Right optional\n      end case) = value end for all\n  end definition\nend law\n\n-- The annotation gives the empty-case literal the same primitive type as head.\nlaw \"|matching can provide a default value| is\n  definition :\n    for all (value :: Maybe Int8) =>\n      ((first matching case of value :\n        when Absent then 0\n        when Present payload then payload\n      end case) :: Int8) = ((first matching case of value :\n        when Present payload then payload\n        when Absent then 0\n      end case) :: Int8) end for all\n  end definition\nend law\nend unit\n")
  , ("mixed_inputs.lawspec", "unit example.mixed.inputs\n\nnormalize :: Text -> Text\nidentity :: Int32 -> Int32\n\nlaw \"|text normalization reaches a fixed point with an unused integer input| is\n  definition :\n    for all (text :: Text) (number :: Int32) =>\n      normalize text = normalize (normalize text) end for all\n  end definition\n  example \"|text normalization and integer identity have explicit results| :\n    text = \"Hello, World!\"\n    number = -42\n    expect normalize text = \"Hello,-World!\"\n    expect identity number = -42\n  end example\nend law\n\nlaw \"|integer identity with an unused text input| is\n  definition :\n    for all (text :: Text) (number :: Int32) =>\n      identity number = number end for all\n  end definition\n  example \"|text normalization and integer identity have explicit results| :\n    text = \"\x3bb\& \x1f600\&\"\n    number = 2147483647\n    expect normalize text = \"\x3bb\&-\x1f600\&\"\n    expect identity number = 2147483647\n  end example\nend law\n\nlaw \"|normalizing an empty literal| is\n  definition :\n    for all (text :: Text) =>\n      normalize \"\" = \"\" end for all\n  end definition\n  example \"|empty literal stays empty; quantified text is unused| :\n    text = \"unused context\"\n    expect normalize \"\" = \"\"\n  end example\nend law\nend unit\n")
  , ("models.lawspec", "unit example.models\n\n-- A stateful model pairs a system's commands with reference definitions over\n-- a simpler model state. LawSpec generates runs of commands, runs them\n-- against the adapters, and checks each result and state against the model.\n\n-- A linear model: the stack's size is in its type, so a run never pops an\n-- empty stack.\ntype Stack (n :: Whole) is one of\n  | Empty where n = 0\n  | Push of type record{ top :: Int8 rest :: Stack m} where n = m + 1\nend type\n\nempty :: Unit -> Stack 0\npush :: (x :: Int8) -> Stack n / Stack (n + 1) -> Unit\npop :: Stack (n + 1) / Stack n -> Int8\npeek :: Stack (n + 1) / Stack (n + 1) -> Int8\n\nfunction modelPush (x :: Int8) (xs :: List Int8) -> List Int8 is Cons x xs end function\n\nfunction modelPop (xs :: List Int8) -> Pair Int8 (List Int8) is\n  first matching case of xs :\n  when Nil then Pair 0 Nil\n  when Cons x rest then Pair x rest\n  end case\nend function\n\nfunction modelPeek (xs :: List Int8) -> Pair Int8 (List Int8) is\n  first matching case of xs :\n  when Nil then Pair 0 Nil\n  when Cons x rest then Pair x xs\n  end case\nend function\n\nfunction toList (s :: Stack n) -> List Int8 is\n  first matching case of s :\n  when Empty then Nil\n  when Push record{ top = top , rest = rest} then Cons top (toList rest)\n  end case\nend function\n\nmodel stack :: Stack n by List Int8 is\n  start empty by Nil\n  push by modelPush\n  pop by modelPop\n  peek by modelPeek\n  abstract toList\nend model\n\n-- A shared model: commands take one counter, whose type never changes, and\n-- may run at the same time, so each must be atomic. LawSpec also runs them\n-- in parallel and checks that every history is linearizable.\ntype Counter is a record{  id :: Int32} end type\n\nnewCounter :: Unit -> Counter\nasync increment :: Counter -> Int64\nasync decrement :: Counter -> Int64\nasync read :: Counter -> Int64\n\nfunction modelIncrement (n :: Int64 where n >= 0 && n <= 1000000) -> Pair Int64 Int64 is Pair (n + 1) (n + 1) end function\nfunction modelDecrement (n :: Int64 where n >= 0 && n <= 1000000) -> Pair Int64 Int64 is Pair (n - 1) (n - 1) end function\nfunction modelRead (n :: Int64) -> Pair Int64 Int64 is Pair n n end function\nfunction positive (n :: Int64) -> Bool is n > 0 end function\n\nmodel counter :: shared Counter by Int64 is\n  start newCounter ~ 0\n  increment ~ modelIncrement\n  decrement ~ modelDecrement when positive\n  read ~ modelRead\nend model\n\n-- A protocol lists what one end of a channel sends and receives; the other\n-- end does the reverse. Scenarios run a shared model's commands from\n-- processes that run at the same time and talk over channels; LawSpec checks\n-- that they cannot deadlock or race, then runs them on many schedules, and\n-- each run must agree with the model.\nprotocol Report is\n  send Int64\nend protocol\n\nprotocol Request is\n  send Report\nend protocol\n\nscenario `a count is passed on` in counter is\n  channel report :: Report\n  par\n    n <- increment\n    send report n\n  with\n    receive report m\n    expect m = 1\n  end par\nend scenario\n\n-- The asker hands its end of the answer channel to a worker, which replies\n-- to the listener directly.\nscenario `a reply is delegated` in counter is\n  channel ask :: Request\n  channel answer :: Report\n  par\n    send ask answer\n  with\n    receive ask reply\n    n <- increment\n    send reply n\n  with\n    receive answer m\n    expect m = 1\n  end par\nend scenario\n\nscenario `two counts at once` in counter is\n  par\n    a <- increment\n  with\n    b <- increment\n  end par\n  total <- read\n  expect total = 2\nend scenario\n\n-- Two channels between the same two processes close a cycle. That is\n-- accepted when no process waits for another in a cycle: here the first\n-- process sends before it waits, so the echo can always answer.\nprotocol Echo is\n  receive Int64\nend protocol\n\nscenario `a count is echoed back` in counter is\n  channel out :: Report\n  channel back :: Echo\n  par\n    n <- increment\n    send out n\n    receive back m\n    expect m = 1\n  with\n    receive out k\n    send back k\n  end par\nend scenario\nend unit\n")
  , ("mutual_recursion.lawspec", "unit example.mutualRecursion\n\n-- Two definitions that call each other. Each call passes a smaller number,\n-- so every chain of calls ends.\nfunction isEven (n :: Whole) -> Bool is\n  if n <= 0 then true else isOdd (n - 1) end if\nend function\n\nfunction isOdd (n :: Whole) -> Bool is\n  if n <= 0 then false else isEven (n - 1) end if\nend function\n\n-- An outline: an item, and the items under it.\ntype Item is a record{\n  label :: Text,\n  children :: List Item\n}\nend type\n\n-- One line for the item, then the lines of everything under it.\nfunction itemLine (item :: Item) -> Integer is\n  first matching case of item:\n    when record{children = children} then 1 + itemLines children\n  end case\nend function\n\nfunction itemLines (items :: List Item) -> Integer is\n  first matching case of items:\n    when Nil then 0\n    when Cons head tail then itemLine head + itemLines tail\n  end case\nend function\n\n-- The first argument gets smaller, or it stays and the second gets smaller.\nfunction ackermann (m :: Whole) (n :: Whole) -> Whole is\n  if m <= 0 then n + 1\n  else if n <= 0 then ackermann (m - 1) 1\n  else ackermann (m - 1) (ackermann m (n - 1)) end if end if\nend function\n\n-- The two lists change places on every call, and one loses an element.\nfunction interleaved (xs :: List Bool) (ys :: List Bool) -> Integer is\n  first matching case of xs:\n    when Nil then 0\n    when Cons head tail then 1 + interleaved ys tail\n  end case\nend function\n\n-- Neither bound moves the same way on every call, so the compiler is told\n-- what gets smaller: the distance between them. It proves that the distance\n-- shrinks and stays at least 0 on each call; the clause is never taken on trust.\n-- The result is promised to be at least 0, which the compiler also proves.\nfunction narrowing (low :: Integer) (high :: Integer) -> (result :: Integer where result >= 0)\ndecreases high - low\nis\n  if low >= high then 0\n  else if prelude.rem low 2 = 0 then 1 + narrowing (low + 1) high\n  else 1 + narrowing low (high - 1) end if end if\nend function\n\nlaw \"|parity alternates| is\n  definition:\n    for all (n :: UInt8) =>\n      isEven n != isOdd n\n    end for all\n  end definition\nend law\n\nlaw \"|ten is even| is\n  definition: isEven 10 && isOdd 9 end definition\nend law\n\nlaw \"|an outline has one line for each item| is\n  definition:\n    itemLine (Item record{label = \"root\", children = [\n      Item record{label = \"first\", children = [Item record{label = \"leaf\", children = []}]},\n      Item record{label = \"second\", children = []}\n    ]}) must be 4\n  end definition\nend law\n\nlaw \"|ackermann of two and three| is\n  definition: ackermann 2 3 must be 9 end definition\nend law\n\nlaw \"|narrowing takes one step for each unit of distance| is\n  definition: narrowing 3 10 must be 7 end definition\nend law\n\nlaw \"|interleaving stops when the first list is empty| is\n  definition: interleaved [true, false, true] [true] must be 3 end definition\nend law\nend unit\n")
  , ("native_agreement.lawspec", "unit example.nativeAgreement\n\n-- Each target runs the list operations with its own loops. These laws check\n-- that every one gives the result of its definition in lawspec.instances.\n\nimport lawspec.instances (mapList, mapEither, filterList, foldLeftList,\n  foldRightList, allList, anyList, lengthList, appendList, concatList)\n\nfunction double (n :: Integer) -> Integer is n * 2 end function\n\nfunction isEven (n :: Integer) -> Bool is prelude.rem n 2 = 0 end function\n\nfunction minus (a :: Integer) (b :: Integer) -> Integer is a - b end function\n\nfunction halved (n :: Integer) -> Either Text Integer is\n  if isEven n then Right (prelude.quot n 2) else Left \"odd\" end if\nend function\n\nlaw \"|the definitions give the expected results| is\n  definition :\n    mapList double [1, 2, 3] = [2, 4, 6]\n    and filterList isEven [1, 2, 3, 4] = [2, 4]\n    and foldLeftList minus 10 [1, 2, 3] = 4\n    and foldRightList minus 10 [1, 2, 3] = -8\n    and allList isEven [2, 4] and not allList isEven [2, 3]\n    and anyList isEven [1, 2] and not anyList isEven [1, 3]\n    and lengthList [7, 8, 9] = 3\n    and appendList [1] [2, 3] = [1, 2, 3]\n    and concatList [[1], [], [2, 3]] = [1, 2, 3]\n    and mapEither double (halved 4) = Right 4\n    and mapEither double (halved 3) = Left \"odd\"\n  end definition\nend law\n\nlaw \"|map agrees with its definition| is\n  definition :\n    for all (xs :: List Integer) =>\n      prelude.map double xs = mapList double xs\n    end for all\n  end definition\nend law\n\nlaw \"|map over an Either agrees with its definition| is\n  definition :\n    for all (n :: Integer) =>\n      prelude.map double (halved n) = mapEither double (halved n)\n    end for all\n  end definition\nend law\n\nlaw \"|filter agrees with its definition| is\n  definition :\n    for all (xs :: List Integer) =>\n      prelude.filter isEven xs = filterList isEven xs\n    end for all\n  end definition\nend law\n\nlaw \"|the folds agree with their definitions| is\n  definition :\n    for all (start :: Integer) (xs :: List Integer) =>\n      prelude.foldLeft minus start xs = foldLeftList minus start xs\n      and prelude.foldRight minus start xs = foldRightList minus start xs\n    end for all\n  end definition\nend law\n\nlaw \"|all and any agree with their definitions| is\n  definition :\n    for all (xs :: List Integer) =>\n      prelude.all isEven xs = allList isEven xs\n      and prelude.any isEven xs = anyList isEven xs\n    end for all\n  end definition\nend law\n\nlaw \"|length agrees with its definition| is\n  definition :\n    for all (xs :: List Integer) =>\n      prelude.length xs = lengthList xs\n    end for all\n  end definition\nend law\n\nlaw \"|append agrees with its definition| is\n  definition :\n    for all (xs :: List Integer) (ys :: List Integer) =>\n      xs ++ ys = appendList xs ys\n    end for all\n  end definition\nend law\n\nlaw \"|concat agrees with its definition| is\n  definition :\n    for all (xss :: List (List Integer)) =>\n      prelude.concat xss = concatList xss\n    end for all\n  end definition\nend law\nend unit\n")
  , ("parse_port.lawspec", "unit example.parse_port\n\nvalidPort :: Int32 -> Bool\nrender    :: Int32 -> Text\nparse     :: Text -> Int32\n\nlaw \"|valid ports round trip| is\n  definition :\n    for all (x :: Int32) =>\n      validPort x implies\n        parse (render x) = x end for all\n  end definition\n\n  description :\n    \"For ports in 1 through 65535, {parse} recovers the value written by {render}\"\n  end description\n\n  example \"|ordinary port| :\n    x = 443\n    expect validPort x = true\n    expect render x = \"443\"\n    expect parse (render x) = 443\n  end example\n\n  example \"|lowest port is accepted and round trips| :\n    x = 1\n    expect validPort x = true\n    expect render x = \"1\"\n    expect parse (render x) = 1\n  end example\n\n  example \"|highest port is accepted and round trips| :\n    x = 65535\n    expect validPort x = true\n    expect render x = \"65535\"\n    expect parse (render x) = 65535\n  end example\n\n  example \"|zero is rejected; rendering and parsing are skipped| :\n    x = 0\n    expect validPort x = false\n  end example\n\n  example \"|negative port is rejected; rendering and parsing are skipped| :\n    x = -1\n    expect validPort x = false\n  end example\n\n  example \"|65536 is rejected; rendering and parsing are skipped| :\n    x = 65536\n    expect validPort x = false\n  end example\nend law\n\nlaw \"|the same port contract via the prelude| is\n  definition :\n    apply law \"|left inverse when| validPort parse render\n  end definition\n\n  example \"|port 8080 satisfies the inherited condition and round trips| :\n    x = 8080\n    expect validPort x = true\n    expect render x = \"8080\"\n    expect parse (render x) = 8080\n  end example\nend law\nend unit\n")
  , ("payments.lawspec", "unit example.payments\n\n-- The executable acceptance model for native domain bindings in 0.10.\n-- Applications may call Money \"Price\", amount \"major\", and currency \"unit\";\n-- those representation choices must not alter these laws.\ntype Currency is one of USD | EUR | GBP end type\n\ntype Money is a record{\n   amount :: Decimal currency :: Currency}\nend type\n\ntype Payment is one of\n  Paid  of type Money\n  Declined  of type Text\nend type\n\n-- These are adapter functions supplied by the application.\naddFee :: Money -> Money\nroundTrip :: Payment -> Payment\narchive :: List (Maybe Payment) -> List (Maybe Payment)\n\n-- The model is exact, independent of host decimal rounding settings.\nfunction feeModel (money :: Money) -> Money is\n  first matching case of money :\n    when Money record{ amount = amount , currency = currency} then Money record{ amount = (amount + 0.2) , currency = currency}\n  end case\nend function\n\nlaw \"|fees preserve currency and exact decimal value| is\n  definition :\n    for all (money :: Money) => addFee money = feeModel money end for all\n  end definition\n  example \"|decimal tenths| :\n    money = Money record{ amount = 0.1 , currency = USD}\n    expect addFee money = Money record{ amount = 0.3 , currency = USD}\n  end example\n  example \"|small amount is not rounded away| :\n    money = Money record{ amount = 0.000000000000000000000000000001 , currency = EUR}\n    expect addFee money = Money record{ amount = 0.200000000000000000000000000001 , currency = EUR}\n  end example\n  example \"|beyond binary floating precision| :\n    money = Money record{ amount = 9007199254740993.1 , currency = GBP}\n    expect addFee money = Money record{ amount = 9007199254740993.3 , currency = GBP}\n  end example\nend law\n\nlaw \"|payment variants and payloads survive native conversion| is\n  definition :\n    for all (payment :: Payment) => roundTrip payment = payment end for all\n  end definition\n  example \"|successful payment| :\n    payment = Paid (Money record{ amount = 12.34 , currency = EUR})\n    expect roundTrip payment = Paid (Money record{ amount = 12.34 , currency = EUR})\n  end example\n  example \"|declined payment| :\n    payment = Declined \"card declined\"\n    expect roundTrip payment = Declined \"card declined\"\n  end example\nend law\n\nlaw \"|archives preserve order duplicates and absence| is\n  definition :\n    for all (payments :: List (Maybe Payment)) => archive payments = payments end for all\n  end definition\n  example \"|empty archive| :\n    payments = []\n    expect archive payments = []\n  end example\n  example \"|missing is different from a declined payment| :\n    payments = [Absent, Present (Declined \"\"), Present (Paid (Money record{ amount = 0.1 , currency = USD})),\n                Present (Paid (Money record{ amount = 0.1 , currency = USD}))]\n    expect archive payments = [Absent, Present (Declined \"\"),\n                              Present (Paid (Money record{ amount = 0.1 , currency = USD})),\n                              Present (Paid (Money record{ amount = 0.1 , currency = USD}))]\n  end example\nend law\nend unit\n")
  , ("railway.lawspec", "unit example.railway\n\n-- Railway combinators on Either. Each symbol has a prelude name, and both are\n-- rewritten into matches, so they work in laws and checked definitions alike.\n\ntype Problem is one of | TooSmall | TooLarge | Odd end type\n\nfunction positive (x :: Integer) -> Either Problem Integer is\n  prelude.select (x > 0) (Right x) (Left TooSmall)\nend function\n\nfunction small (x :: Integer) -> Either Problem Integer is\n  prelude.select (x < 100) (Right x) (Left TooLarge)\nend function\n\nfunction even (x :: Integer) -> Bool is prelude.rem x 2 = 0 end function\n\nfunction twice (x :: Integer) -> Integer is x + x end function\n\nfunction retry (p :: Problem) -> Either Problem Integer is Right 1 end function\n\n-- A checked pipeline written with symbols: positive, then small, then doubled.\nfunction checked (x :: Integer) -> Either Problem Integer is\n  twice <$> (positive x >>= small)\nend function\n\n-- The same pipeline in English.\nfunction checkedInWords (x :: Integer) -> Either Problem Integer is\n  prelude.map twice (prelude.bind (positive x) small)\nend function\n\nlaw \"|symbols and English agree| is\n  definition : for all (x :: Integer) => checked x = checkedInWords x end for all end definition\nend law\n\nlaw \"|binding associates| is\n  definition :\n    for all (x :: Integer) => ((positive x >>= small) >>= positive) = (positive x >>= (small >=> positive)) end for all\n  end definition\nend law\n\nlaw \"|a failure short-circuits| is\n  definition : for all (x :: Integer) => x <= 0 implies checked x = Left TooSmall end for all end definition\nend law\n\nlaw \"|recovery replaces a failure| is\n  definition : for all (x :: Integer) => (positive x <|> retry) = prelude.select (x > 0) (Right x) (Right 1) end for all end definition\nend law\n\nlaw \"|ensure keeps even values| is\n  definition :\n    for all (x :: Integer) =>\n      prelude.ensure even Odd (positive x) = prelude.select (x > 0) (prelude.select (even x) (Right x) (Left Odd)) (Left TooSmall) end for all\n  end definition\nend law\n\nlaw \"|both pairs successes| is\n  definition :\n    for all (x :: Integer) => prelude.isRight (positive x <*> small x) = (x > 0 && x < 100) end for all\n  end definition\nend law\n\n-- The prelude's railway laws, instantiated for these definitions.\nlaw \"|positive is a left identity case| is\n  definition : apply law \"|bind has a left identity| positive end definition\nend law\n\nlaw \"|positive, small and positive associate| is\n  definition : apply law \"|bind is associative| positive small positive end definition\nend law\n\nlaw \"|mapping twice fuses| is\n  definition : apply law \"|map fuses| positive twice twice end definition\nend law\n\nlaw \"|retry keeps successes| is\n  definition : apply law \"|recovery keeps successes| positive retry end definition\nend law\nend unit\n")
  , ("records.lawspec", "unit example.records\n\nimport example.records.inner as inner\n\n-- Records: a type with one constructor has fields that code reads by name\n-- (account.balance) and replaces by name (account with balance = 0).\n\ntype Account is a record{\n\n    owner :: Text\n    balance :: Int64\n    holds :: List Int64}\nend type\n\ntype Ledger is a record{\n\n    account :: Account\n    entries :: Int32}\nend type\n\nfunction deposit (a :: Account) (amount :: Int64 where amount >= 0 && amount <= 1000000) -> Account is\n  if a.balance >= 0 && a.balance <= 1000000000 then a with balance = prelude.Int64 (a.balance + amount) else a end if\nend function\n\nfunction rename (l :: Ledger) (name :: Text) -> Ledger is\n  l with account = (l.account with owner = name), entries = 0\nend function\n\nlaw \"|a deposit adds to the balance| is\n  definition :\n    for all (owner :: Text) (start :: Int64 where start >= 0 && start <= 1000000000) (amount :: Int64 where amount >= 0 && amount <= 1000000) =>\n      (deposit (Account record{ owner = owner , balance = start , holds = []}) amount).balance = start + amount end for all\n  end definition\nend law\n\nlaw \"|a deposit keeps the owner and holds| is\n  definition :\n    for all (a :: Account) (amount :: Int64 where amount >= 0 && amount <= 1000000) =>\n      (deposit a amount).owner = a.owner and (deposit a amount).holds = a.holds end for all\n  end definition\nend law\n\nlaw \"|renaming reads back| is\n  definition :\n    for all (l :: Ledger) (name :: Text) => (rename l name).account.owner = name and (rename l name).entries = 0 end for all\n  end definition\nend law\n\n-- A definition may fail without any ability, and another may attempt it.\ntype Refusal is one of | Overdrawn | Unfunded end type\n\nprocedure withdraw (a :: Account) (amount :: Int64) -> Account fails with Refusal is\n  if amount < 0 then raise Unfunded else\n    if amount > a.balance then raise Overdrawn else a with balance = prelude.Int64 (a.balance - amount) end if end if\nend procedure\n\nfunction settled (a :: Account) (amount :: Int64) -> Either Refusal Int64 is\n  first matching case of prelude.attempt (withdraw a amount) :\n  when Left refusal then Left refusal\n  when Right after then Right after.balance\n  end case\nend function\n\nlaw \"|a withdrawal within the balance leaves the rest| is\n  definition :\n    for all (owner :: Text) (start :: Int64 where start >= 0) (amount :: Int64 where amount >= 0 && amount <= start) =>\n      settled (Account record{ owner = owner , balance = start , holds = []}) amount = Right (prelude.Int64 (start - amount)) end for all\n  end definition\nend law\n\nlaw \"|a withdrawal beyond the balance is refused| is\n  definition :\n    for all (owner :: Text) (start :: Int64 where start >= 0 && start < 1000) (amount :: Int64 where amount >= 1000) =>\n      settled (Account record{ owner = owner , balance = start , holds = []}) amount = Left Overdrawn and settled (Account record{ owner = owner , balance = start , holds = []}) (0 - amount) = Left Unfunded end for all\n  end definition\nend law\n\n-- A refinement through a definition still guides generation: sample\n-- names come from the pattern, so the law does not starve its filter.\nfunction validOwner (name :: Text) -> Bool is\n  prelude.length name = 9 && name matches regex \"acct-[0-9]{4}\"\nend function\n\nlaw \"|a renamed ledger keeps a valid owner| is\n  definition :\n    for all (l :: Ledger) (name :: Text where validOwner name) => validOwner (rename l name).account.owner end for all\n  end definition\nend law\n\n-- A literal takes its type from where it is used: 0 is an Int64 here.\nfunction opening (a :: Maybe Account) -> Int64 is\n  let start = (first matching case of a : when Absent then 0 when Present account then account.balance end case) in\n  if start < 0 then 0 else start end if end let\nend function\n\nlaw \"|an absent account opens at zero| is\n  definition : opening Absent = 0 end definition\nend law\n\n-- Recursion on an integer that moves toward a bound is total.\nfunction countdown (n :: Whole) -> List Whole is\n  if n = 0 then [] else Cons n (countdown (n - 1)) end if\nend function\n\nfunction evensBelow (i :: Int32) (n :: Int32) -> List Int32 is\n  if i >= n || i < 0 then [] else\n    (if prelude.rem i 2 = 0 then Cons i (evensBelow (prelude.Int32 (i + 1)) n) else evensBelow (prelude.Int32 (i + 1)) n end if) end if\nend function\n\nlaw \"|a countdown has n items| is\n  definition : for all (n :: Whole where n <= 50) => prelude.length (countdown n) = n end for all end definition\nend law\n\nlaw \"|the evens below n are half of the range| is\n  definition :\n    for all (n :: Int32 where n >= 0 && n <= 40) =>\n      prelude.length (evensBelow 0 n) = prelude.quot (n + 1) 2 end for all\n  end definition\nend law\n\nlaw \"|range counts from the first up to the last| is\n  definition :\n    for all (n :: Int32 where n >= 0 && n <= 40) => prelude.length (prelude.range 0 n) = n end for all\n  end definition\n  example \"|three| :\n    n = 3\n    expect prelude.range 0 n = [0, 1, 2]\n  end example\nend law\n\n-- The prover keeps what guards say about calls, lengths and remainders.\nfunction clip (xs :: List Int32) -> Int32 is\n  if prelude.length xs <= 100 then prelude.Int32 (prelude.length xs) else 100 end if\nend function\n\nfunction owner (p :: Int32) (k :: Int32) -> Int32 is\n  if k >= 1 && p >= 0 then prelude.Int32 (prelude.rem p k) else 0 end if\nend function\n\nlaw \"|a clipped length is at most 100| is\n  definition : for all (xs :: List Int32) => (clip xs <= 100 && clip xs >= 0) = true end for all end definition\nend law\n\nlaw \"|an owner is one of the k| is\n  definition :\n    for all (p :: Int32 where p >= 0) (k :: Int32 where k >= 1 && k <= 64) => (owner p k >= 0 && owner p k < k) = true end for all\n  end definition\nend law\n\n-- Arithmetic into a bounded type, by name.\nfunction nextEpoch (e :: Int16) -> Int16 is prelude.wrapping (e + 1) end function\nfunction topUp (level :: UInt8) -> UInt8 is prelude.saturating (level + 10) end function\nfunction total (a :: Int32) (b :: Int32) -> Maybe Int32 is prelude.bounded (a + b) end function\n\nlaw \"|epochs wrap around| is\n  definition :\n    for all (e :: Int16) => nextEpoch e = (if e = Int16.max then Int16.min else prelude.Int16 (e + 1) end if) end for all\n  end definition\nend law\n\nlaw \"|a top up stops at the top| is\n  definition :\n    for all (level :: UInt8) => topUp level = (if level >= 245 then 255 else prelude.UInt8 (level + 10) end if) end for all\n  end definition\nend law\n\nlaw \"|a total that overflows is Absent| is\n  definition :\n    for all (a :: Int32) (b :: Int32) =>\n      total a b = (if a + b > Int32.max || a + b < Int32.min then Absent else Present (prelude.Int32 (a + b)) end if) end for all\n  end definition\nend law\n\n-- A refinement shapes generation: texts a regex must match are drawn from\n-- the regex, through the definition that says so, not filtered from any\n-- text.\nfunction validTopic (name :: Text) -> Bool is\n  let n = prelude.length name in\n  n >= 1 && n <= 249 && name != \".\" && name != \"..\" && name matches regex \"[a-zA-Z0-9._-]+\" end let\nend function\n\nlaw \"|a valid topic name keeps to its characters| is\n  definition :\n    for all (t :: Text where validTopic t) (n :: Int32 where n >= 1 && n <= 64) =>\n      (prelude.length t >= 1 && prelude.length t <= 249 && n <= 64) = true end for all\n  end definition\nend law\n\nlaw \"|a unit may sit above its package's other units| is\n  definition : for all (x :: Int32) => inner.doubled x = x + x end for all end definition\nend law\nend unit\n")
  , ("records_inner.lawspec", "unit example.records.inner\n\n-- A unit inside another unit's name: on Python, example.records is then its\n-- package's __init__.py, and this unit is example/records/inner.py.\n\nfunction doubled (x :: Int32) -> Integer is x * 2 end function\n\nlaw \"|doubling is even| is\n  definition : for all (x :: Int32) => prelude.rem (doubled x) 2 = 0 end for all end definition\nend law\nend unit\n")
  , ("recursive_refinements.lawspec", "unit example.recursive_refinements\n\n-- Refining a type argument follows its stored occurrences through recursion.\n-- The fixed Int8 field remains independent of the refined argument.\ntype Tree (a :: Type) is one of\n  Leaf of type record{ value :: a fixed :: Int8}\n  Fork of type record{ left :: Tree a right :: Tree a}\nend type\n\nrefinement Positive is (value :: Int8 where value > 0) end refinement\n\n-- The payload guarantee is available when proving recursive definitions.\nfunction positiveSum (tree :: Tree Positive) -> (total :: Integer where total > 0) is\n  first matching case of tree :\n    when Leaf record{ value = value , fixed = fixed} then value + 0\n    when Fork record{ left = left , right = right} then positiveSum left + positiveSum right\n  end case\nend function\n\nlaw \"|positive leaves have a positive total| is\n  definition :\n    for all (tree :: Tree Positive) => positiveSum tree > 0 end for all\n  end definition\n  example \"|fixed fields may be negative| :\n    tree = Fork record{ left = (Leaf record{ value = 1 , fixed = -128}) , right = (Fork record{ left = (Leaf record{ value = 2 , fixed = 0}) , right = (Leaf record{ value = 3 , fixed = -1})})}\n    expect positiveSum tree = 6\n  end example\nend law\n\n-- Dependent predicates retain the enclosing input, even below several forks.\nlaw \"|every stored argument exceeds the threshold| is\n  definition :\n    for all (threshold :: Int8 where threshold < 127)\n      (tree :: Tree (value :: Int8 where value > threshold)) => tree = tree end for all\n  end definition\n  example \"|nested threshold| :\n    threshold = 4\n    tree = Fork record{ left = (Leaf record{ value = 5 , fixed = -128}) , right = (Leaf record{ value = 6 , fixed = 0})}\n    expect tree = Fork record{ left = (Leaf record{ value = 5 , fixed = -128}) , right = (Leaf record{ value = 6 , fixed = 0})}\n  end example\nend law\nend unit\n")
  , ("refined_definitions.lawspec", "unit example.refined_definitions\n\nrefinement Nonzero (T :: Type) requires Integer T is\n  (value :: T where value != 0)\nend refinement\n\n-- The compiler proves division is defined under the input contract.\n-- Native callers are checked before the body runs.\nfunction reciprocal (x :: Nonzero a) -> Rational\nrequires Integer a\nis\n  1 / x\nend function\n\n-- Arithmetic promotes before this explicit, proved narrowing conversion.\nfunction increment (x :: Int8 where x < 127)\n  -> (result :: Int8 where result > x)\nis\n  prelude.Int8 (x + 1)\nend function\n\n-- Later argument refinements can depend on earlier arguments.\nfunction inverseGap (x :: Int8) (y :: Int8 where y > x) -> Rational is\n  1 / (y - x)\nend function\n\nlaw \"|exact reciprocal| is\n  definition : for all (x :: Nonzero Int8) => reciprocal x = 1 / x end for all end definition\n  example \"|one half| : x = 2 expect reciprocal x = rational(1, 2) end example\nend law\n\nlaw \"|checked increment| is\n  definition : for all (x :: Int8 where x < 127) => increment x = x + 1 end for all end definition\n  example \"|largest admitted input| : x = 126 expect increment x = 127 end example\nend law\n\nlaw \"|dependent gap| is\n  definition : for all (x :: Int8) (y :: Int8 where y > x) =>\n    inverseGap x y = 1 / (y - x) end for all\n  end definition\n  example \"|difference exceeds Int8| :\n    x = -128 y = 127 expect inverseGap x y = rational(1, 255)\n  end example\nend law\nend unit\n")
  , ("refinements.lawspec", "unit example.refinements\n\nrefinement Between (T :: Type) (minimum :: T) (maximum :: T)\n  requires Ordered T is\n  (value :: T where minimum <= value && value <= maximum)\nend refinement\n\nrefinement Positive (T :: Type) requires Integer T is\n  (value :: T where value > 0)\nend refinement\n\nrefinement AdditionOverflows (T :: Type) (left :: T)\n  requires Integer T Bounded T is\n  (right :: T where left + right > T.max)\nend refinement\n\nadd :: (x :: Int8)\n    -> (y :: AdditionOverflows Int8 x)\n    -> (result :: Integer where result = x + y)\nsuccessor :: (x :: Int8) -> (result :: Integer where result = x + 1)\ncount :: (text :: Text where prelude.length text > 0)\n      -> (result :: Integer where result = prelude.length text)\npreserve :: (x :: UInt64) -> (result :: Integer where result = x)\npositive :: (x :: Positive Int8) -> (result :: Positive Int8 where result = x)\n\nlaw \"|maximum input| is\n  definition : for all (x :: Int8) => successor x = x + 1 end for all end definition\n  example \"|beyond Int8| : x = 127 expect successor x = 128 end example\nend law\n\nlaw \"|overflow pairs| is\n  definition :\n    for all (x :: Int8) (y :: AdditionOverflows Int8 x) =>\n      add x y = x + y end for all\n  end definition\n  example \"|smallest overflowing sum| : x = 127 y = 1 expect add x y = 128 end example\n  example \"|largest sum| : x = 127 y = 127 expect add x y = 254 end example\nend law\n\nlaw \"|bounded input| is\n  definition : for all (x :: Between Int8 1 3) => positive x = x end for all end definition\n  example \"|middle| : x = 2 expect positive x = 2 end example\nend law\n\nlaws for positive are\n  partial because \"the laws check positive only from 1 to 3\"\nend laws\n\nlaw \"|large integer| is\n  definition : for all (x :: UInt64) => preserve x = x end for all end definition\n  example \"|maximum UInt64| : x = 18446744073709551615 expect preserve x = 18446744073709551615 end example\nend law\n\nabstractEcho :: (x :: Integer) -> (result :: Integer where result = x)\n\nlaw \"|nested presence| is\n  definition : for all (x :: Optional (Nullable (Positive Int8))) => x = x end for all end definition\nend law\n\nlaw \"|finite positive floats| is\n  definition :\n    for all (x :: Float32 where prelude.isFinite x && x > 0) =>\n      prelude.isFinite x end for all\n  end definition\n  example \"|positive| : x = 0.5 expect x = 0.5 end example\nend law\n\nlaw \"|raw byte length| is\n  definition : for all (x :: Bytes where prelude.length x = 3) => prelude.length x = 3 end for all end definition\n  example \"|arbitrary octets| : x = bytes([0,128,255]) expect prelude.length x = 3 end example\nend law\n\nlaw \"|guarded predicate arithmetic| is\n  definition : for all (x :: Int8) (y :: Int8 where x != 0 && y > 10 / x) => y > 10 / x end for all end definition\nend law\n\nlaw \"|machine bound| is\n  definition : for all (x :: IntSize where x = IntSize.max) => x = IntSize.max end for all end definition\nend law\n\nlaw \"|symbol fixture refinement| is\n  definition :\n    for all (x :: Symbol where x = symbol(\"selected\", \"fixture\")) =>\n      x = symbol(\"selected\", \"fixture\") end for all\n  end definition\n  example \"|selected identity| :\n    x = symbol(\"selected\", \"fixture\")\n    expect x = symbol(\"selected\", \"fixture\")\n  end example\nend law\nend unit\n")
  , ("resilience.lawspec", "unit example.resilience\n\nimport lawspec.resilience as r\nimport example.limits as limits\n\n-- Conformance of each target's workflow runtime with a reference model.\n-- The adapters call the runtime; the checked definitions are the reference.\n-- Delays are whole microseconds.\n\n-- The delay before attempt k (2 or more) of each retry strategy.\nfunction exponentialDelay (base :: Integer where base >= 0 && base <= 1000000)\n    (factor :: Integer where factor >= 1 && factor <= 4)\n    (attempt :: Integer where attempt >= 2 && attempt <= 10) -> Integer is\n  base * prelude.pow factor (attempt - 2)\nend function\n\nfunction linearDelay (base :: Integer where base >= 0 && base <= 1000000)\n    (step :: Integer where step >= 0 && step <= 1000000)\n    (attempt :: Integer where attempt >= 2 && attempt <= 10) -> Integer is\n  base + step * (attempt - 2)\nend function\n\nruntimeExponentialDelay :: Integer -> Integer -> Integer -> Integer\nruntimeLinearDelay :: Integer -> Integer -> Integer -> Integer\nruntimeFibonacciDelay :: Integer -> Integer -> Integer\n\n-- The first outputs of SplitMix64 for a seed, and full jitter.\nsplitMix :: UInt64 -> Int32 -> List UInt64\nfullJitter :: UInt64 -> Integer -> Integer\n\n-- A stage that always fails, retried exponentially from 100ms, doubling, for\n-- the given number of attempts: the waits the runtime makes.\nretriedWaits :: Int32 -> List Integer\n\n-- The same, with a when predicate that rejects the error: no waits.\nrejectedWaits :: Int32 -> List Integer\n\n-- Unrefined inputs are mapped into range, so every target generates them\n-- directly: a base up to 65535us, a factor of 1 to 4, and attempts 2 to 10.\nlaw \"|exponential delays match the reference| is\n  definition :\n    for all (base :: UInt16) (f :: UInt8) (a :: UInt8) =>\n      runtimeExponentialDelay (prelude.Integer base) (1 + prelude.rem (prelude.Integer f) 4) (2 + prelude.rem (prelude.Integer a) 9) =\n        exponentialDelay (prelude.Integer base) (1 + prelude.rem (prelude.Integer f) 4) (2 + prelude.rem (prelude.Integer a) 9) end for all\n  end definition\nend law\n\nlaw \"|the fifth exponential attempt| is\n  definition :\n    for all (base :: Integer where base = 100000) => runtimeExponentialDelay base 2 5 = 800000 end for all\n  end definition\nend law\n\nlaw \"|linear delays match the reference| is\n  definition :\n    for all (base :: UInt16) (step :: UInt16) (a :: UInt8) =>\n      runtimeLinearDelay (prelude.Integer base) (prelude.Integer step) (2 + prelude.rem (prelude.Integer a) 9) =\n        linearDelay (prelude.Integer base) (prelude.Integer step) (2 + prelude.rem (prelude.Integer a) 9) end for all\n  end definition\nend law\n\nlaw \"|fibonacci delays add the two before| is\n  definition :\n    for all (base :: UInt16) (a :: UInt8) =>\n      runtimeFibonacciDelay (prelude.Integer base) (4 + prelude.rem (prelude.Integer a) 27) =\n        runtimeFibonacciDelay (prelude.Integer base) (3 + prelude.rem (prelude.Integer a) 27) +\n        runtimeFibonacciDelay (prelude.Integer base) (2 + prelude.rem (prelude.Integer a) 27) end for all\n  end definition\nend law\n\nlaw \"|fibonacci delays start at the base| is\n  definition :\n    for all (base :: UInt16) =>\n      runtimeFibonacciDelay (prelude.Integer base) 2 = prelude.Integer base and\n        runtimeFibonacciDelay (prelude.Integer base) 3 = prelude.Integer base end for all\n  end definition\nend law\n\nlaw \"|SplitMix64 is the same everywhere| is\n  definition :\n    for all (count :: Int8 where count >= 0 && count <= 3) =>\n      prelude.length (splitMix 0 (prelude.Int32 count)) = prelude.Integer count end for all\n  end definition\n  example \"|seed zero| :\n    count = 3\n    expect splitMix 0 (prelude.Int32 count) = [16294208416658607535, 7960286522194355700, 487617019471545679]\n  end example\nend law\n\nlaw \"|full jitter stays within the delay| is\n  definition :\n    for all (seed :: UInt64) (delay :: UInt32) =>\n      (fullJitter seed (prelude.Integer delay) >= 0 && fullJitter seed (prelude.Integer delay) <= prelude.Integer delay) = true end for all\n  end definition\nend law\n\nlaw \"|a failing stage waits between its attempts| is\n  definition :\n    for all (attempts :: Int8 where attempts >= 1 && attempts <= 6) =>\n      prelude.length (retriedWaits (prelude.Int32 attempts)) = prelude.Integer attempts - 1 end for all\n  end definition\n  example \"|four attempts| :\n    attempts = 4\n    expect retriedWaits (prelude.Int32 attempts) = [100000, 200000, 400000]\n  end example\nend law\n\nlaw \"|a rejected error is not retried| is\n  definition :\n    for all (attempts :: Int8 where attempts >= 1 && attempts <= 6) =>\n      rejectedWaits (prelude.Int32 attempts) = [] end for all\n  end definition\nend law\n\n-- Calls limited at each time (microseconds, in order) under one runtime\n-- with its gates on: whether each call was admitted.\nlimitedAt :: List Integer -> List Bool\n\nfunction admits (gate :: r.Gate) -> Bool is\n  first matching case of gate :\n  when r.Admit then true\n  when r.WaitFor micros then false\n  when r.Reject then false\n  end case\nend function\n\n-- The reference: the resilience unit's token bucket, folded over the times.\nfunction bucketRun (state :: r.TokenBucket) (times :: List Integer) -> List Bool is\n  first matching case of times :\n  when Nil then Nil\n  when Cons t rest then\n      first matching case of r.tokenBucketAdmit 2 1000000 state t :\n      when r.Step next gate then Cons (admits gate) (bucketRun next rest)\n      end case\n  end case\nend function\n\n-- Times a millisecond apart and more, as a list of gaps.\nfunction timesFrom (start :: Integer) (gaps :: List UInt16) -> List Integer is\n  first matching case of gaps :\n  when Nil then Nil\n  when Cons gap rest then Cons start (timesFrom (start + prelude.Integer gap * 1000) rest)\n  end case\nend function\n\nlaw \"|the rate limit admits as the token bucket does| is\n  definition :\n    for all (gaps :: List UInt16) =>\n      limitedAt (timesFrom 0 gaps) = bucketRun (r.tokenBucketStart 2 1000000 0) (timesFrom 0 gaps) end for all\n  end definition\n  example \"|three calls at once| :\n    gaps = [0, 0, 0]\n    expect limitedAt (timesFrom 0 gaps) = [true, true, false]\n  end example\nend law\n\n-- The other state machines, which every target runs as generated code.\nlaw \"|an open breaker rejects until its cooldown ends| is\n  definition :\n    for all (t :: UInt16) =>\n      r.breakerAdmit (r.Open 1000) (prelude.Integer t) =\n        prelude.select (prelude.Integer t >= 1000) (r.Step r.HalfOpen r.Admit) (r.Step (r.Open 1000) r.Reject) end for all\n  end definition\nend law\n\nlaw \"|a breaker opens after enough failures in its window| is\n  definition :\n    for all (gap :: UInt8) =>\n      r.breakerRecord 2 1000 500 (r.breakerRecord 2 1000 500 (r.Closed []) 10 false) (10 + prelude.Integer gap) false =\n        r.Open (510 + prelude.Integer gap) end for all\n  end definition\nend law\n\nlaw \"|a breaker forgets failures outside its window| is\n  definition :\n    for all (gap :: UInt8) =>\n      r.breakerRecord 2 100 500 (r.breakerRecord 2 100 500 (r.Closed []) 0 false) (200 + prelude.Integer gap) false =\n        r.Closed [200 + prelude.Integer gap] end for all\n  end definition\nend law\n\nlaw \"|a successful trial closes the breaker| is\n  definition :\n    for all (t :: UInt16) => r.breakerRecord 2 1000 500 r.HalfOpen (prelude.Integer t) true = r.Closed [] end for all\n  end definition\nend law\n\nlaw \"|a bulkhead admits up to its limit| is\n  definition :\n    for all (running :: UInt8) =>\n      r.bulkheadAdmit 4 (r.Bulkhead (prelude.Integer running)) 0 =\n        prelude.select (prelude.Integer running < 4)\n          (r.Step (r.Bulkhead (prelude.Integer running + 1)) r.Admit)\n          (r.Step (r.Bulkhead (prelude.Integer running)) (r.WaitFor 1000)) end for all\n  end definition\nend law\n\nlaw \"|a sliding window admits n calls per period| is\n  definition :\n    for all (t :: UInt16) =>\n      r.slidingWindowAdmit 2 1000 (r.SlidingWindow [prelude.Integer t, prelude.Integer t]) (prelude.Integer t + 1) =\n        r.Step (r.SlidingWindow [prelude.Integer t, prelude.Integer t]) (r.WaitFor 999) end for all\n  end definition\nend law\n\n-- Books a ticket under a fresh runtime: the stages whose undos ran.\ncompensationsFor :: Int64 -> List Text\n\nlaw \"|a failed booking releases its seat| is\n  definition :\n    for all (n :: Int64) =>\n      compensationsFor n = prelude.select (n < 0) [\"reserveSeat\"] [] end for all\n  end definition\nend law\n\n-- Quotes a ticket under a runtime with the real clock: whether it timed out.\nasync quoteTimedOut :: Int64 -> Bool\n\nlaw \"|a slow quote times out| is\n  definition :\n    for all (n :: Int64) => quoteTimedOut n = (n = -1) end for all\n  end definition\n  example \"|a slow quote| :\n    n = -1\n    expect quoteTimedOut n = true\n  end example\n  example \"|a quick quote| :\n    n = 0\n    expect quoteTimedOut n = false\n  end example\nend law\n\n-- Quotes a ticket under a runtime with the real clock: whether it succeeded,\n-- for ticket -2 through a hedge that overtakes the stalled first attempt.\nasync quoteHedged :: Int64 -> Bool\n\nlaw \"|a stalled quote is hedged| is\n  definition :\n    for all (n :: Int64) => quoteHedged n = true end for all\n  end definition\n  example \"|a stalled quote| :\n    n = -2\n    expect quoteHedged n = true\n  end example\nend law\nend unit\n")
  , ("resources.lawspec", "unit example.resources\n\n-- A resource is something a law needs that lives outside the program: a\n-- store, a directory, a port. Each case of a law acquires its resources\n-- first and releases them after, even when the case fails, so every case\n-- starts afresh and nothing leaks.\n\n-- A store the tests open, use and close. Only adapters make one.\nhandle Store\n\nopenStore :: Unit -> Store\ncloseStore :: Store -> Unit\nclearStore :: Store -> Unit\nput :: Store -> Int32 -> Int32 -> Unit\nget :: Store -> Int32 -> Maybe Int32\nisOpen :: Store -> Bool\nsize :: Store -> Int32\n\nresource Store is\n  acquire is openStore unitValue end acquire\n  release store is closeStore store end release\n  reset store is clearStore store end reset\nend resource\n\nlaw \"|a stored value can be read back| for store :: Store is\n  definition :\n    for all (k :: Int32) (v :: Int32) => put store k v = unitValue and get store k = Present v end for all\n  end definition\n  example \"|the store is open while the case runs| :\n    k = 1\n    v = 2\n    expect isOpen store\n  end example\nend law\n\nlaw \"|every case gets an empty store| for store :: Store is\n  definition :\n    for all (k :: Int32) (v :: Int32) =>\n      size store = 0 and put store k v = unitValue and size store = 1 end for all\n  end definition\nend law\n\n-- Built-in resources: a temporary directory, a free port, and the\n-- environment, saved and restored.\nwriteNote :: Text -> Int32 -> Unit\nreadNote :: Text -> Maybe Int32\ncanListen :: Int32 -> Bool\nsetGreeting :: Int32 -> Unit\ngreeting :: Unit -> Maybe Int32\n\nlaw \"|a note reads back| for dir :: TemporaryDirectory is\n  definition :\n    for all (n :: Int32) =>\n      writeNote (directoryPath dir) n = unitValue and readNote (directoryPath dir) = Present n end for all\n  end definition\nend law\n\nlaw \"|a new directory has no note| for dir :: TemporaryDirectory is\n  definition :\n    readNote (directoryPath dir) = Absent\n  end definition\nend law\n\nlaw \"|a free port can be listened on| for port :: FreePort is\n  definition :\n    canListen (portNumber port) = true\n  end definition\nend law\n\nlaw \"|the greeting is the one set| for saved :: SavedEnvironment is\n  definition :\n    for all (n :: Int32) => setGreeting n = unitValue and greeting unitValue = Present n end for all\n  end definition\nend law\n\nlaw \"|the environment is restored after each case| for saved :: SavedEnvironment is\n  definition :\n    greeting unitValue = Absent\n  end definition\nend law\n\n-- A pool is costly to open, so the harness shares one between the cases of\n-- this unit's laws. Sharing is allowed only because Pool declares reset:\n-- every case after the first gets the pool drained, so no case sees what\n-- another left in it, and the law means the same as with a fresh pool.\nhandle Pool\n\nopenPool :: Unit -> Pool\ndrainPool :: Pool -> Unit\nclosePool :: Pool -> Unit\nfill :: Pool -> Int32 -> Unit\nlevel :: Pool -> Int32\n\nresource Pool is\n  acquire is openPool unitValue end acquire\n  release pool is closePool pool end release\n  reset pool is drainPool pool end reset\nend resource\n\nlaw \"|a pool starts each case empty| for pool :: Pool is\n  definition :\n    for all (n :: Int32 where n > 0 && n <= 100) =>\n      level pool = 0 and fill pool n = unitValue and level pool = n end for all\n  end definition\nend law\n\nlaw \"|filling twice adds up| for pool :: Pool is\n  definition :\n    for all (a :: Int32 where a > 0 && a <= 100) (b :: Int32 where b > 0 && b <= 100) =>\n      fill pool a = unitValue and fill pool b = unitValue and level pool = a + b end for all\n  end definition\nend law\n\nharness example.resources.testing for example.resources is\n  share Pool per unit\nend harness\nend unit\n")
  , ("restarts.lawspec", "unit example.restarts\n\n-- A tab keeps its total across a crash: `restart keeps state` says that a\n-- restarted actor resumes with the state it had before the crash, as an\n-- event-sourced actor recovers its state from its journal. Runs crash the\n-- tab between messages, and its total, and the model's, must survive.\ntype Tab is a record{  total :: Int64} end type\n\nopenTab :: Unit -> Tab\nadd :: Tab -> UInt8 -> Pair Int64 Tab\ntotal :: Tab -> Pair Int64 Tab\n\nfunction modelAdd (amount :: UInt8) (n :: Int64 where n >= 0 && n <= 1000000) -> Pair Int64 Int64 is\n  Pair (n + amount) (n + amount)\nend function\n\nfunction modelTotal (n :: Int64) -> Pair Int64 Int64 is Pair n n end function\n\nactor tab :: Tab by Int64 is\n  start openTab by 0\n  restart keeps state\n  on add by modelAdd\n  on total by modelTotal\nend actor\n\n-- A supervisor restarts the tab after a crash, keeping its total.\nsupervisor bar is\n  one for one\n  permanent tab\nend supervisor\n\n-- keepsTotal starts the bar, adds to the tab, crashes it, and reads its total\n-- through the same handle.\nkeepsTotal :: UInt8 -> Int64\n\nlaw \"|a crashed tab keeps its total| is\n  definition : for all (x :: UInt8) => keepsTotal x = x end for all end definition\nend law\nend unit\n")
  , ("scalar_adapters.lawspec", "unit example.scalar_adapters\nechoChar :: Char -> Char\nechoCodePoint :: CodePoint -> CodePoint\nechoCodeUnit :: CodeUnit16 -> CodeUnit16\nechoBytes :: Bytes -> Bytes\nechoComplex :: Complex64 -> Complex64\nsuccessor :: Int8 -> Integer\nnarrow :: Int8 -> Int8\naddDecimal :: Decimal -> Decimal -> Decimal\nsameSymbol :: Symbol -> Symbol -> Bool\nechoRaw :: Utf16Text -> Utf16Text\nechoPresence :: Optional (Nullable Int8) -> Optional (Nullable Int8)\nfinish :: Unit -> Unit\npreserveBig :: UInt64 -> UInt64\nmachineEcho :: IntSize -> IntSize\n\nlaw \"|promoted successor| is\n  definition : for all (x :: Int8) => successor x = x + 1 end for all end definition\n  example \"|no overflow| : x = 127 expect successor x = 128 end example\nend law\nlaw \"|checked bridge| is\n  definition : for all (x :: Int8) => narrow (x + 0) = x end for all end definition\n  example \"|maximum| : x = 127 expect narrow (x + 0) = 127 end example\nend law\nlaw \"|exact decimal adapter| is\n  definition : for all (x :: Decimal) (y :: Decimal) => addDecimal x y = x + y end for all end definition\n  example \"|tenths| : x = 0.1 y = 0.2 expect addDecimal x y = 0.3 end example\nend law\nlaw \"|symbol identity adapter| is\n  definition : for all (x :: Symbol) (y :: Symbol) => sameSymbol x x and sameSymbol y y end for all end definition\n  example \"|same description distinct identities| :\n    x = symbol(\"a\", \"same\") y = symbol(\"b\", \"same\")\n    expect sameSymbol x y = false\n    expect sameSymbol x x = true\n  end example\nend law\nlaw \"|raw adapter| is\n  definition : for all (x :: Utf16Text) => echoRaw x = x end for all end definition\n  example \"|lone surrogate| : x = utf16([55296]) expect echoRaw x = utf16([55296]) end example\nend law\nlaw \"|presence adapter| is\n  definition : for all (x :: Optional (Nullable Int8)) => echoPresence x = x end for all end definition\n  example \"|missing| : x = undefined expect echoPresence x = undefined end example\n  example \"|null present| : x = optional(null) expect echoPresence x = optional(null) end example\nend law\nlaw \"|unit adapter| is\n  definition : for all (x :: Unit) => finish x = unitValue end for all end definition\n  example \"|completed| : x = unitValue expect finish x = unitValue end example\nend law\n\nlaw \"|no safe-number truncation| is\n  definition : for all (x :: UInt64) => preserveBig x = x end for all end definition\n  example \"|unsigned maximum| : x = 18446744073709551615 expect preserveBig x = 18446744073709551615 end example\nend law\nlaw \"|machine profile binding| is\n  definition : for all (x :: IntSize) => machineEcho x = x end for all end definition\n  example \"|portable width| : x = 2147483647 expect machineEcho x = 2147483647 end example\nend law\n\nlaw \"|Char native bridge| is\n  definition : for all (x :: Char) => echoChar x = x end for all end definition\n  example \"|native value| : x = char(128512) expect echoChar x = char(128512) end example\nend law\n\nlaw \"|CodePoint native bridge| is\n  definition : for all (x :: CodePoint) => echoCodePoint x = x end for all end definition\n  example \"|native value| : x = codePoint(55296) expect echoCodePoint x = codePoint(55296) end example\nend law\n\nlaw \"|CodeUnit16 native bridge| is\n  definition : for all (x :: CodeUnit16) => echoCodeUnit x = x end for all end definition\n  example \"|native value| : x = codeUnit16(65535) expect echoCodeUnit x = codeUnit16(65535) end example\nend law\n\nlaw \"|Bytes native bridge| is\n  definition : for all (x :: Bytes) => echoBytes x = x end for all end definition\n  example \"|native value| : x = bytes([0,128,255]) expect echoBytes x = bytes([0,128,255]) end example\nend law\n\nlaw \"|Complex64 native bridge| is\n  definition : for all (x :: Complex64) => prelude.isNaN (prelude.real (echoComplex x)) = prelude.isNaN (prelude.real x) end for all end definition\n  example \"|native value| : x = complex64(1,2) expect echoComplex x = complex64(1,2) end example\nend law\nend unit\n")
  , ("scalar_catalog.lawspec", "unit example.scalar_catalog\n\nlaw \"|Bool representation| is\n  definition : for all (x :: Bool) => x = x end for all end definition\n  example \"|explicit value| : x = true expect x = true end example\nend law\n\nlaw \"|Int8 representation| is\n  definition : for all (x :: Int8) => x = x end for all end definition\n  example \"|explicit value| : x = -128 expect x = -128 end example\nend law\n\nlaw \"|Int16 representation| is\n  definition : for all (x :: Int16) => x = x end for all end definition\n  example \"|explicit value| : x = 32767 expect x = 32767 end example\nend law\n\nlaw \"|Int32 representation| is\n  definition : for all (x :: Int32) => x = x end for all end definition\n  example \"|explicit value| : x = 2147483647 expect x = 2147483647 end example\nend law\n\nlaw \"|Int64 representation| is\n  definition : for all (x :: Int64) => x = x end for all end definition\n  example \"|explicit value| : x = 9223372036854775807 expect x = 9223372036854775807 end example\nend law\n\nlaw \"|UInt8 representation| is\n  definition : for all (x :: UInt8) => x = x end for all end definition\n  example \"|explicit value| : x = 255 expect x = 255 end example\nend law\n\nlaw \"|UInt16 representation| is\n  definition : for all (x :: UInt16) => x = x end for all end definition\n  example \"|explicit value| : x = 65535 expect x = 65535 end example\nend law\n\nlaw \"|UInt32 representation| is\n  definition : for all (x :: UInt32) => x = x end for all end definition\n  example \"|explicit value| : x = 4294967295 expect x = 4294967295 end example\nend law\n\nlaw \"|UInt64 representation| is\n  definition : for all (x :: UInt64) => x = x end for all end definition\n  example \"|explicit value| : x = 18446744073709551615 expect x = 18446744073709551615 end example\nend law\n\nlaw \"|IntSize representation| is\n  definition : for all (x :: IntSize) => x = x end for all end definition\n  example \"|explicit value| : x = 2147483647 expect x = 2147483647 end example\nend law\n\nlaw \"|UIntSize representation| is\n  definition : for all (x :: UIntSize) => x = x end for all end definition\n  example \"|explicit value| : x = 4294967295 expect x = 4294967295 end example\nend law\n\nlaw \"|UIntPtr representation| is\n  definition : for all (x :: UIntPtr) => x = x end for all end definition\n  example \"|explicit value| : x = 4294967295 expect x = 4294967295 end example\nend law\n\nlaw \"|BigInt representation| is\n  definition : for all (x :: Integer) => x = x end for all end definition\n  example \"|explicit value| : x = -1234567890123456789012345678901234567890 expect x = -1234567890123456789012345678901234567890 end example\nend law\n\nlaw \"|BigUInt representation| is\n  definition : for all (x :: Whole) => x = x end for all end definition\n  example \"|explicit value| : x = 1234567890123456789012345678901234567890 expect x = 1234567890123456789012345678901234567890 end example\nend law\n\nlaw \"|Decimal representation| is\n  definition : for all (x :: Decimal) => x = x end for all end definition\n  example \"|explicit value| : x = 0.000000000000000000000000000000000001 expect x = 0.000000000000000000000000000000000001 end example\nend law\n\nlaw \"|Rational representation| is\n  definition : for all (x :: Rational) => x = x end for all end definition\n  example \"|explicit value| : x = rational(-7, 11) expect x = rational(-7, 11) end example\nend law\n\nlaw \"|Float32 representation| is\n  definition : for all (x :: Float32) => prelude.isNaN x = prelude.isNaN x end for all end definition\n  example \"|explicit value| : x = float32Bits(\"80000000\") expect x = float32Bits(\"80000000\") end example\nend law\n\nlaw \"|Float64 representation| is\n  definition : for all (x :: Float64) => prelude.isNaN x = prelude.isNaN x end for all end definition\n  example \"|explicit value| : x = float64Bits(\"7ff0000000000000\") expect x = float64Bits(\"7ff0000000000000\") end example\nend law\n\nlaw \"|Complex64 representation| is\n  definition : for all (x :: Complex64) => prelude.isNaN (prelude.real x) = prelude.isNaN (prelude.real x) end for all end definition\n  example \"|explicit value| : x = complex64(1, -2) expect x = complex64(1, -2) end example\nend law\n\nlaw \"|Complex128 representation| is\n  definition : for all (x :: Complex128) => prelude.isNaN (prelude.real x) = prelude.isNaN (prelude.real x) end for all end definition\n  example \"|explicit value| : x = complex128(0.5, -3.5) expect x = complex128(0.5, -3.5) end example\nend law\n\nlaw \"|Char representation| is\n  definition : for all (x :: Char) => x = x end for all end definition\n  example \"|explicit value| : x = char(128512) expect x = char(128512) end example\nend law\n\nlaw \"|CodePoint representation| is\n  definition : for all (x :: CodePoint) => x = x end for all end definition\n  example \"|explicit value| : x = codePoint(55296) expect x = codePoint(55296) end example\nend law\n\nlaw \"|CodeUnit16 representation| is\n  definition : for all (x :: CodeUnit16) => x = x end for all end definition\n  example \"|explicit value| : x = codeUnit16(65535) expect x = codeUnit16(65535) end example\nend law\n\nlaw \"|Text representation| is\n  definition : for all (x :: Text) => x = x end for all end definition\n  example \"|explicit value| : x = \"\x3bb\&\x65e5\&\x672c\&\x8a9e\&\x1f600\&\" expect x = \"\x3bb\&\x65e5\&\x672c\&\x8a9e\&\x1f600\&\" end example\nend law\n\nlaw \"|CodePointText representation| is\n  definition : for all (x :: CodePointText) => x = x end for all end definition\n  example \"|explicit value| : x = codePoints([55296, 1114111]) expect x = codePoints([55296, 1114111]) end example\nend law\n\nlaw \"|Utf16Text representation| is\n  definition : for all (x :: Utf16Text) => x = x end for all end definition\n  example \"|explicit value| : x = utf16([55296, 0, 65535]) expect x = utf16([55296, 0, 65535]) end example\nend law\n\nlaw \"|Bytes representation| is\n  definition : for all (x :: Bytes) => x = x end for all end definition\n  example \"|explicit value| : x = bytes([0, 128, 255]) expect x = bytes([0, 128, 255]) end example\nend law\n\nlaw \"|Symbol representation| is\n  definition : for all (x :: Symbol) => x = x end for all end definition\n  example \"|explicit value| : x = symbol(\"catalog\", \"same\") expect x = symbol(\"catalog\", \"same\") end example\nend law\n\nlaw \"|Unit representation| is\n  definition : for all (x :: Unit) => x = x end for all end definition\n  example \"|explicit value| : x = unitValue expect x = unitValue end example\nend law\n\nlaw \"|Null representation| is\n  definition : for all (x :: Null) => x = x end for all end definition\n  example \"|explicit value| : x = null expect x = null end example\nend law\n\nlaw \"|Undefined representation| is\n  definition : for all (x :: Undefined) => x = x end for all end definition\n  example \"|explicit value| : x = undefined expect x = undefined end example\nend law\n\nlaw \"|Nullable Int8 representation| is\n  definition : for all (x :: Nullable Int8) => x = x end for all end definition\n  example \"|explicit value| : x = nullable(127) expect x = nullable(127) end example\nend law\n\nlaw \"|Optional Int8 representation| is\n  definition : for all (x :: Optional Int8) => x = x end for all end definition\n  example \"|explicit value| : x = undefined expect x = undefined end example\nend law\nend unit\n")
  , ("scalars.lawspec", "unit example.scalars\n\nlaw \"|integer promotion| is\n  definition : for all (x :: Int8) => x + 1 = 1 + x end for all end definition\n  example \"|overflow is preserved| :\n    x = 127\n    expect x + 1 = 128\n  end example\nend law\n\nlaw \"|unsigned precision| is\n  definition : for all (x :: UInt64) => x + 0 = x end for all end definition\n  example \"|maximum| :\n    x = 18446744073709551615\n    expect x + 1 = 18446744073709551616\n  end example\nend law\n\nlaw \"|decimal exactness| is\n  definition : for all (x :: Decimal) => x + 0.1 = 0.1 + x end for all end definition\n  example \"|tenths| :\n    x = 0.1\n    expect x + 0.2 = 0.3\n  end example\nend law\n\nlaw \"|exact division| is\n  definition : for all (x :: Int16) => x / 2 = x / 2 end for all end definition\n  example \"|one half| :\n    x = 1\n    expect x / 2 = rational(1, 2)\n    expect prelude.quot -7 3 = -2\n    expect prelude.rem -7 3 = -1\n    expect prelude.round rational(125, 100) 1 = 1.2\n  end example\nend law\n\nlaw \"|IEEE classification| is\n  definition : for all (x :: Float32) => prelude.isNaN x = prelude.isNaN x end for all end definition\n  example \"|NaN| :\n    x = float32Bits(\"7fc00000\")\n    expect prelude.isNaN x = true\n  end example\n  example \"|negative zero| :\n    x = float32Bits(\"80000000\")\n    expect prelude.isNegativeZero x = true\n    expect x = (0 :: Float32)\n  end example\n  example \"|infinity| :\n    x = float32Bits(\"7f800000\")\n    expect prelude.isInfinite x = true\n    expect prelude.Float32 0.1 = (0.1 :: Float32)\n  end example\nend law\n\nlaw \"|complex arithmetic| is\n  definition : for all (x :: Unit) => complex64(1, 2) * complex64(3, 4) = complex64(-5, 10) end for all end definition\n  example \"|product| :\n    x = unitValue\n    expect complex64(1, 2) * complex64(3, 4) = complex64(-5, 10)\n  end example\nend law\n\nlaw \"|raw units survive| is\n  definition : for all (x :: Utf16Text) => x = x end for all end definition\n  example \"|unpaired surrogate| :\n    x = utf16([55296, 0, 56320])\n    expect x = utf16([55296, 0, 56320])\n  end example\nend law\n\nlaw \"|arbitrary bytes| is\n  definition : for all (x :: Bytes) => x = x end for all end definition\n  example \"|octets| :\n    x = bytes([0, 128, 255])\n    expect x = bytes([0, 128, 255])\n  end example\nend law\n\nlaw \"|symbol fixture identity| is\n  definition : for all (x :: Symbol) => x = x end for all end definition\n  example \"|same reference| :\n    x = symbol(\"first\", \"description\")\n    expect x = symbol(\"first\", \"description\")\n  end example\nend law\n\nlaw \"|nested absence| is\n  definition : for all (x :: Optional (Nullable Int8)) => x = x end for all end definition\n  example \"|undefined| :\n    x = undefined\n    expect x = undefined\n  end example\n  example \"|present null| :\n    x = optional(null)\n    expect x = optional(null)\n  end example\n  example \"|present integer| :\n    x = optional(nullable(7))\n    expect x = optional(nullable(7))\n  end example\nend law\n\nlaw \"|supplementary scalar| is\n  definition : for all (x :: Char) => x = x end for all end definition\n  example \"|emoji| :\n    x = char(128512)\n    expect x = char(128512)\n  end example\nend law\n\nlaw \"|surrogate code point| is\n  definition : for all (x :: CodePointText) => x = x end for all end definition\n  example \"|surrogate| :\n    x = codePoints([55296, 128512])\n    expect x = codePoints([55296, 128512])\n  end example\nend law\n\nlaw \"|explicit float rounding| is\n  definition : for all (x :: Unit) => x = x end for all end definition\n  example \"|IEEE halfway cases| :\n    x = unitValue\n    expect prelude.Complex128 complex64(1, 2) = complex128(1, 2)\n    expect prelude.Complex64 complex128(1.25, -2.5) = complex64(1.25, -2.5)\n    expect prelude.Float32 rational(16777217, 16777216) = float32Bits(\"3f800000\")\n    expect prelude.Float32 rational(1208925891672223212634113, 1208925819614629174706176) = float32Bits(\"3f800001\")\n    expect prelude.Float64 rational(9007199254740993, 9007199254740992) = float64Bits(\"3ff0000000000000\")\n    expect prelude.Float64 rational(1606938044258990453947923680586147734807949174969684883144705, 1606938044258990275541962092341162602522202993782792835301376) = float64Bits(\"3ff0000000000001\")\n    expect prelude.Float32 rational(1, 1427247692705959881058285969449495136382746624) = float32Bits(\"00000000\")\n    expect prelude.Float32 rational(1125899906842625, 1606938044258990275541962092341162602522202993782792835301376) = float32Bits(\"00000001\")\n  end example\nend law\n\nlaw \"|short circuit exact failures| is\n  definition : for all (x :: Unit) => false implies 1 / 0 = rational(1, 2) end for all end definition\n  example \"|guard prevents division| : x = unitValue expect x = unitValue end example\nend law\nend unit\n")
  , ("scheduling_order.lawspec", "unit example.sequencing\n\n-- How a harness orders a unit's laws never changes what they mean. The\n-- scheduling acceptance suite checks that `order random` follows the run's\n-- seed: the same seed gives the same order, and other seeds other orders.\n-- pause notes when it is called (when the suite asks it to) and gives true.\npause :: Int32 -> Bool\n\nlaw \"|the first pause ends| is definition : pause 1 = true end definition end law\nlaw \"|the second pause ends| is definition : pause 2 = true end definition end law\nlaw \"|the third pause ends| is definition : pause 3 = true end definition end law\nlaw \"|the fourth pause ends| is definition : pause 4 = true end definition end law\nlaw \"|the fifth pause ends| is definition : pause 5 = true end definition end law\nlaw \"|the sixth pause ends| is definition : pause 6 = true end definition end law\n\nharness example.sequencing.testing for example.sequencing is\n  order random\nend harness\nend unit\n")
  , ("scheduling_overlap.lawspec", "unit example.overlap\n\n-- How a harness runs a unit's laws never changes what they mean. The\n-- scheduling acceptance suite checks that `parallel` runs them at the same\n-- time: each nap sleeps, and their sleeps overlap.\nasync nap :: Int32 -> Bool\n\nlaw \"|the first nap ends| is definition : nap 101 = true end definition end law\nlaw \"|the second nap ends| is definition : nap 102 = true end definition end law\nlaw \"|the third nap ends| is definition : nap 103 = true end definition end law\n\nharness example.overlap.testing for example.overlap is\n  parallel\nend harness\nend unit\n")
  , ("sequences.lawspec", "unit example.sequences\n\n-- Text, Bytes and List are sequences: joined with ++, sliced, and read by\n-- index. Bytes give their octets, and Text its UTF-8 encoding.\n\n-- A record key's hash: FNV-1a over the key's octets, in 32 bits.\nfunction fnv (octets :: List UInt8) (hash :: UInt32) -> UInt32 is\n  first matching case of octets :\n  when Nil then hash\n  when Cons o rest then fnv rest (prelude.wrapping ((xorByte hash o) * 16777619))\n  end case\nend function\n\n-- hash xor o, for an octet o, by its low eight bits.\nfunction xorByte (hash :: UInt32) (o :: UInt8) -> Integer is\n  let low = prelude.rem hash 256 in\n  hash - low + xorBits low o 128 end let\nend function\n\nfunction xorBits (a :: Integer) (b :: Integer) (bit :: Integer) -> Integer is\n  if bit <= 0 || a < 0 || b < 0 then 0 else\n    (if prelude.quot a bit != prelude.quot b bit then bit else 0 end if)\n      + xorBits (prelude.rem a bit) (prelude.rem b bit) (prelude.quot bit 2) end if\nend function\n\nfunction keyHash (key :: Bytes) -> UInt32 is fnv (prelude.octets key) 2166136261 end function\n\nfunction partitionFor (key :: Bytes) (n :: Int32) -> Int32 is\n  if n >= 1 then prelude.Int32 (prelude.rem (keyHash key) n) else 0 end if\nend function\n\nlaw \"|a key's partition exists| is\n  definition :\n    for all (key :: Bytes) (n :: Int32 where n >= 1 && n <= 64) =>\n      (partitionFor key n >= 0 && partitionFor key n < n) = true end for all\n  end definition\nend law\n\nlaw \"|the hash follows FNV-1a| is\n  definition : keyHash (prelude.utf8 \"a\") = 3826002220 and keyHash (prelude.utf8 \"\") = 2166136261 end definition\nend law\n\n-- Member ids, made by the coordinator from a client id and a counter.\nfunction memberId (client :: Text) (n :: Int32) -> Text is client ++ \"-\" ++ prelude.textOf n end function\n\nlaw \"|a member id starts with its client| is\n  definition :\n    for all (client :: Text) (n :: Int32) => memberId client n starts with client end for all\n  end definition\n  example \"|the third| :\n    client = \"consumer\"\n    n = 3\n    expect memberId client n = \"consumer-3\"\n  end example\nend law\n\nlaw \"|joining text adds lengths| is\n  definition :\n    for all (a :: Text) (b :: Text) => prelude.length (a ++ b) = prelude.length a + prelude.length b end for all\n  end definition\nend law\n\nlaw \"|octets and bytes round trip| is\n  definition : for all (b :: Bytes) => prelude.bytesOf (prelude.octets b) = b end for all end definition\nend law\n\nlaw \"|a slice is a part| is\n  definition :\n    for all (xs :: List Int32) (k :: Int32 where k >= 0 && k <= 10) =>\n      prelude.take k xs ++ prelude.drop k xs = xs end for all\n  end definition\nend law\n\nlaw \"|at reads the item an index names| is\n  definition :\n    for all (x :: Int32) (xs :: List Int32) => prelude.at 0 (Cons x xs) = Present x and prelude.at (prelude.length xs + 1) (Cons x xs) = Absent end for all\n  end definition\nend law\n\nlaw \"|texts join with a separator| is\n  definition : prelude.join \", \" [\"a\", \"b\", \"c\"] = \"a, b, c\" and prelude.slice 1 3 \"kafka\" = \"af\" end definition\nend law\n\nlaw \"|utf8 encodes code points| is\n  definition : prelude.utf8 \"\xe9\&\" = prelude.bytesOf [195, 169] and prelude.length (prelude.utf8 \"\xe9\&\") = 2 end definition\nend law\nend unit\n")
  , ("sessions.lawspec", "unit example.sessions\n\n-- Protocols become typed channel ends on every target, for implementation\n-- code: each step is its own type, so steps out of order do not compile,\n-- and an end used twice fails. The adapters below implement adding with a\n-- server process they talk to through those generated types.\n\n-- What a server does: receive two numbers, send their sum. Its client holds\n-- the other end, which does the reverse.\nprotocol Serve is\n  receive Int32\n  receive Int32\n  send Int64\nend protocol\n\n-- Handing a server's end to a worker (delegation).\nprotocol Hire is\n  send Serve\nend protocol\n\n-- Adds through a server process. Processes that talk over channels wait for\n-- each other, so these adapters are asynchronous.\nasync add :: Int32 -> Int32 -> Integer\n\n-- Adds through a worker that is handed the server's end over a Hire channel.\nasync addHired :: Int32 -> Int32 -> Integer\n\nlaw \"|a server adds| is\n  definition :\n    for all (a :: Int32) (b :: Int32) => add a b = prelude.Integer a + prelude.Integer b end for all\n  end definition\nend law\n\nlaw \"|a hired worker adds| is\n  definition :\n    for all (a :: Int32) (b :: Int32) => addHired a b = prelude.Integer a + prelude.Integer b end for all\n  end definition\nend law\nend unit\n")
  , ("slug.lawspec", "unit example.slug\n\nnormalize :: Text -> Text\nreferenceNormalize :: Text -> Text\n\nlaw \"|normalizers agree| is\n  definition :\n    apply law \"|equivalent| normalize referenceNormalize\n  end definition\n  description :\n    \"{normalize} and {referenceNormalize} replace ASCII spaces with hyphens\"\n  end description\n  example \"|spaces become hyphens; punctuation is preserved| :\n    x = \"Hello, World!\"\n    expect normalize x = \"Hello,-World!\"\n    expect referenceNormalize x = \"Hello,-World!\"\n  end example\n  example \"|empty text remains empty| :\n    x = \"\"\n    expect normalize x = \"\"\n    expect referenceNormalize x = \"\"\n  end example\n  example \"|Unicode is preserved while spaces become hyphens| :\n    x = \"caf\xe9\& \x65e5\&\x672c\&\x8a9e\& \x1f600\&\"\n    expect normalize x = \"caf\xe9\&-\x65e5\&\x672c\&\x8a9e\&-\x1f600\&\"\n    expect referenceNormalize x = \"caf\xe9\&-\x65e5\&\x672c\&\x8a9e\&-\x1f600\&\"\n  end example\n  example \"|quotes, backslashes and controls survive space replacement| :\n    x = \"quote: \\\" slash: \\\\ newline: \\n tab: \\t dollar: $\"\n    expect normalize x = \"quote:-\\\"-slash:-\\\\-newline:-\\n-tab:-\\t-dollar:-$\"\n    expect referenceNormalize x = \"quote:-\\\"-slash:-\\\\-newline:-\\n-tab:-\\t-dollar:-$\"\n  end example\nend law\nend unit\n")
  , ("sum_refinements.lawspec", "unit example.sum_refinements\n\nlaw \"|positive Maybe payloads| is\n  definition : for all (x :: Maybe (value :: Int8 where value > 0)) =>\n    (first matching case of x : when Absent then true when Present payload then payload >= 1 end case) = true end for all\n  end definition\n  example \"|absent| : x = Absent expect x = Absent end example\n  example \"|present| : x = Present 1 expect x = Present 1 end example\nend law\n\nlaw \"|selected Either payload| is\n  definition : for all\n    (x :: Either (value :: Int8 where value > 0) (value :: Int8 where value < 0)) =>\n    (first matching case of x : when Left payload then payload >= 1 when Right payload then payload <= -1 end case) = true end for all\n  end definition\n  example \"|left| : x = Left 1 expect x = Left 1 end example\n  example \"|right| : x = Right -1 expect x = Right -1 end example\nend law\n\nlaw \"|nested Maybe states| is\n  definition : for all (x :: Maybe (Maybe (value :: Bool where value))) =>\n    (first matching case of x : when Absent then true when Present inner then\n      first matching case of inner : when Absent then true when Present payload then payload end case\n    end case) = true end for all\n  end definition\n  example \"|outer absent| : x = Absent expect x = Absent end example\n  example \"|inner absent| : x = Present Absent expect x = Present Absent end example\n  example \"|present| : x = Present (Present true) expect x = Present (Present true) end example\nend law\n\nlaw \"|finite Either variants| is\n  definition : for all\n    (x :: Either (value :: Bool where value) (value :: Bool where !value)) =>\n    (first matching case of x : when Left payload then payload when Right payload then !payload end case) = true end for all\n  end definition\nend law\n\nlaw \"|dependent payload keeps outer binding| is\n  definition : for all (lawspecElement :: Int8)\n    (x :: Maybe (value :: Int8 where value > lawspecElement)) =>\n    (first matching case of x : when Absent then true when Present payload then payload - lawspecElement >= 1 end case) = true end for all\n  end definition\n  example \"|maximum prefix has absent continuation| :\n    lawspecElement = 127 x = Absent expect x = Absent\n  end example\n  example \"|present continuation| :\n    lawspecElement = 0 x = Present 1 expect x = Present 1\n  end example\nend law\nend unit\n")
  , ("tables.lawspec", "unit example.tables\n\n-- Examples three ways: as rows of a table, as examples written in a law's\n-- description, and as values recorded in the project.\n\nshippingCost :: Int32 -> Int32 -> Int32\nlabel :: Int32 -> Text\n\n-- Each row is its own example. The column on the right of an expect's =\n-- holds the expected values; the other columns bind the law's inputs.\nlaw \"|shipping cost grows with weight and distance| is\n  definition :\n    for all (kilograms :: Int32 where kilograms >= 0 && kilograms <= 1000)\n      (kilometres :: Int32 where kilometres >= 0 && kilometres <= 1000) =>\n      shippingCost kilograms kilometres >= 0 end for all\n  end definition\n  expect shippingCost kilograms kilometres = cost\n  in table (kilograms, kilometres, cost) :\n    row 0, 0, 0\n    row 1, 10, 15\n    row 2, 10, 30\n    row 10, 100, 1050\n    end table\nend law\n\n-- Examples in a description are fenced, and become examples of the law.\nlaw \"|a label names the parcel| is\n  definition :\n    for all (parcel :: Int32 where parcel >= 0) => label parcel starts with \"parcel \" end for all\n  end definition\n  description :\n    \"Every label starts with the word parcel and the parcel's number.\n\n    ```example\n    parcel = 7\n    expect label parcel = \\\"parcel 7\\\"\n    ```\n\n    ```example `a large number`\n    parcel = 123456\n    expect label parcel = \\\"parcel 123456\\\"\n    ```\"\n  end description\nend law\n\n-- A recorded value is stored in the project, under\n-- recorded/example.tables/<name>, in the portable rendering every target\n-- shares. lawspec test --update-recorded records it again; until then, a\n-- changed value fails.\nlaw \"|the first label is recorded| is\n  definition :\n    label 1 = recorded \"first label\"\n  end definition\nend law\n\nlaw \"|labels are short| is\n  definition :\n    for all (parcel :: Int32 where parcel >= 0) => prelude.length (label parcel) <= 20 end for all\n  end definition\n  example \"|parcel 42| :\n    parcel = 42\n    expect label parcel = recorded \"parcel 42\"\n  end example\nend law\nend unit\n")
  , ("text_pieces.lawspec", "unit example.textPieces\n\n-- A text divides into pieces: at a separator, at white space, or at line\n-- ends. The same pieces come back on every target.\n\n-- A setting is a name, an equals sign and a value, with spaces allowed\n-- around each.\nfunction settingName (line :: Text) -> Text is\n  first matching case of prelude.split \"=\" line :\n  when Nil then \"\"\n  when Cons name rest then prelude.trim name\n  end case\nend function\n\n-- How many words a text has.\nfunction wordCount (text :: Text) -> Integer is\n  prelude.length (prelude.words text)\nend function\n\n-- A key as a Java service reads it: String.trim() removes the code points\n-- up to U+0020 from both ends and nothing else.\nfunction hostTrimmedKey (line :: Text) -> Text is\n  prelude.trimAsciiControl line\nend function\n\nlaw \"|joining the pieces gives the text back| is\n  definition :\n    for all (separator :: Text) (text :: Text) =>\n      prelude.join separator (prelude.split separator text) = text end for all\n  end definition\nend law\n\nlaw \"|split keeps empty pieces| is\n  definition :\n    prelude.split \",\" \"a,,b,\" = [\"a\", \"\", \"b\", \"\"] and prelude.split \"\" \"ab\" = [\"ab\"] and prelude.split \"ab\" \"cabab\" = [\"c\", \"\", \"\"]\n  end definition\nend law\n\nlaw \"|a trimmed text stays trimmed| is\n  definition : for all (text :: Text) => prelude.trim (prelude.trim text) = prelude.trim text end for all end definition\nend law\n\nlaw \"|trim removes white space at both ends only| is\n  definition : prelude.trim \"  a b\\t\\n\" = \"a b\" and prelude.trim \"   \" = \"\" and prelude.trim \"\xe9\& \" = \"\xe9\&\" end definition\nend law\n\nlaw \"|white space is the Unicode property| is\n  definition :\n    prelude.isUnicodeWhitespace \" \\t\\n\\133\\160\\12288\" and prelude.isUnicodeWhitespace \"\" and\n    not prelude.isUnicodeWhitespace \" a \" and not prelude.isUnicodeWhitespace \"\\31\" and not prelude.isUnicodeWhitespace \"\\0\"\n  end definition\nend law\n\nlaw \"|a text is white space exactly when it trims to nothing| is\n  definition : for all (text :: Text) => prelude.isUnicodeWhitespace text = (prelude.trim text == \"\") end for all end definition\nend law\n\nlaw \"|trimAsciiControl removes code points up to U+0020 at both ends only| is\n  definition :\n    prelude.trimAsciiControl \"\\0\\31 a\\tb \\n\" = \"a\\tb\" and prelude.trimAsciiControl \" \\t \" = \"\" and\n    prelude.trimAsciiControl \"\\160a\\160\" = \"\\160a\\160\" and prelude.trimAsciiControl \"\\133\" = \"\\133\" and\n    prelude.trimAsciiControl \"\xe9\& \" = \"\xe9\&\"\n  end definition\nend law\n\nlaw \"|a text trimmed of ASCII controls stays trimmed| is\n  definition :\n    for all (text :: Text) => prelude.trimAsciiControl (prelude.trimAsciiControl text) = prelude.trimAsciiControl text end for all\n  end definition\nend law\n\nlaw \"|a host-trimmed key keeps its no-break space| is\n  definition :\n    for all (key :: Text) => hostTrimmedKey (\"\\160\" ++ key ++ \"\\160 \\31\") = \"\\160\" ++ key ++ \"\\160\" end for all\n  end definition\nend law\n\nlaw \"|words have no white space and are never empty| is\n  definition :\n    prelude.words \" one  two\\tthree\\n\" = [\"one\", \"two\", \"three\"] and prelude.words \"  \" = []\n  end definition\nend law\n\nlaw \"|words are the same after trimming| is\n  definition : for all (text :: Text) => prelude.words (prelude.trim text) = prelude.words text end for all end definition\nend law\n\nlaw \"|lines end at line feeds| is\n  definition :\n    prelude.lines \"a\\n\\nb\\n\" = [\"a\", \"\", \"b\"] and prelude.lines \"a\\nb\" = [\"a\", \"b\"] and prelude.lines \"\" = [] and prelude.lines \"\\n\" = [\"\"]\n  end definition\nend law\n\nlaw \"|a setting's name has no spaces around it| is\n  definition :\n    for all (name :: Text) (value :: Text) =>\n      settingName (\" \" ++ prelude.trim name ++ \" =\" ++ value) = settingName (prelude.trim name ++ \"=\") end for all\n  end definition\n  example \"|spaces around the name| :\n    name = \"retries\"\n    value = \" 3\"\n    expect settingName (\" \" ++ name ++ \" =\" ++ value) = \"retries\"\n    expect wordCount (\" \" ++ name ++ \" =\" ++ value) = 3\n  end example\nend law\nend unit\n")
  , ("total_functions.lawspec", "unit example.total_functions\n\n-- These functions are implemented in the specification. LawSpec checks their\n-- bodies and emits reusable source; they do not need adapter implementations.\nfunction increment (x :: a) -> Integer\nrequires Integer a\nis\n  x + 1\nend function\n\nfunction count (xs :: List a) -> Integer is\n  first matching case of xs :\n    when Nil then 0\n    when Cons head tail then 1 + count tail\n  end case\nend function\n\nfunction nonempty (xs :: List a) -> Bool is\n  first matching case of xs :\n    when Nil then false\n    when Cons head tail then true\n  end case\nend function\n\nlaw \"|nonempty lists have positive length| is\n  definition :\n    for all (xs :: List Int8 where nonempty xs) => count xs > 0 end for all\n  end definition\n  example \"|singleton| : xs = [0] expect count xs = 1 end example\nend law\n\n-- The exact guard proves that the promoted denominator cannot be zero.\nfunction positiveReciprocal (x :: a) -> Bool\nrequires Integer a\nis\n  x >= 0 && 1 / (x + 1) > 0\nend function\n\nlaw \"|guarded exact arithmetic| is\n  definition :\n    for all (x :: Int8) => positiveReciprocal x = (x >= 0) end for all\n  end definition\n  example \"|skip zero denominator| :\n    x = -1 expect positiveReciprocal x = false\n  end example\n  example \"|promote before division| :\n    x = 127 expect positiveReciprocal x = true\n  end example\nend law\n\nfunction guardedNarrow (x :: Int8) -> Bool is\n  x < 127 && prelude.Int8 (x + 1) > x\nend function\n\nlaw \"|narrow only after proving the range| is\n  definition :\n    for all (x :: Int8) => guardedNarrow x = (x < 127) end for all\n  end definition\n  example \"|largest valid conversion| : x = 126 expect guardedNarrow x = true end example\n  example \"|overflow branch is skipped| : x = 127 expect guardedNarrow x = false end example\nend law\n\nfunction same (xs :: List a) (ys :: List a) -> Bool\nrequires Eq a\nis\n  xs = ys\nend function\n\n-- The same checked template produces independent concrete instances.\nlaw \"|count also accepts text| is\n  definition :\n    for all (xs :: List Text) => count xs = prelude.length xs end for all\n  end definition\n  example \"|two words| : xs = [\"hello\", \"world\"] expect count xs = 2 end example\nend law\n\nlaw \"|increment preserves the mathematical result| is\n  definition :\n    for all (x :: Int8) => increment x = x + 1 end for all\n  end definition\n  example \"|maximum input| :\n    x = 127 expect increment x = 128\n  end example\nend law\n\nlaw \"|recursive count agrees with length| is\n  definition :\n    for all (xs :: List Int8) => count xs = prelude.length xs end for all\n  end definition\n  example \"|empty| : xs = [] expect count xs = 0 end example\n  example \"|duplicates still count| : xs = [7, 7, 7] expect count xs = 3 end example\nend law\n\nlaw \"|list equality preserves duplicates and order| is\n  definition :\n    for all (xs :: List Int8) (ys :: List Int8) => same xs ys = (xs = ys) end for all\n  end definition\n  example \"|different order| :\n    xs = [1, 2] ys = [2, 1] expect same xs ys = false\n  end example\nend law\nend unit\n")
  , ("vacuity.lawspec", "unit example.vacuity\n\n-- Laws whose claim sits behind a guard. A generated case that fails the guard\n-- says nothing about the claim, so each law's tests count the cases that\n-- reach it (see docs/reference/refinements.md, \"Guards and reach\").\n\ntype Proposal is a record{\n\n    code :: Text\n    amount :: Int32}\nend type\n\ntype Kind is one of | Short | Long end type\n\ntype Stage is a record{\n\n    token :: Text\n    meaning :: Text}\nend type\n\nmapping stagesOf of type Kind -> List Stage is\n  row Short, [Stage record{ token = \"A\" , meaning = \"Act\"}]\n  row Long, [Stage record{ token = \"P\" , meaning = \"Plan\"}, Stage record{ token = \"D\" , meaning = \"Do\"}]\nend mapping\n\nshout :: (name :: Text) -> Text\nabbreviate :: (stage :: Stage) -> Text\naccepts :: (offer :: Proposal) -> Bool\ndescribe :: (offer :: Proposal) -> Text\nkeep :: (key :: Text) -> Text\n\n-- A regex guard on a quantified input: the compiler reads the guard and\n-- draws texts it matches, so generated cases reach the claim.\nlaw \"|a guarded name keeps its length| is\n  definition :\n    for all (name :: Text) =>\n      name matches regex \"[A-Za-z]{2,40}\" implies prelude.length (shout name) = prelude.length name\n    end for all\n  end definition\nend law\n\n-- A guard that calls an adapter: the compiler cannot see what it accepts, and\n-- no random record satisfies it. Only the example reaches the claim, so the\n-- generated tests are reported vacuous.\nlaw \"|an accepted offer is described by its code| is\n  definition :\n    for all (offer :: Proposal) => accepts offer implies describe offer = offer.code end for all\n  end definition\n  example \"|a well-formed offer| :\n    offer = Proposal record{ code = \"OFFER-2026-AB\" , amount = 5}\n    expect describe offer = \"OFFER-2026-AB\"\n  end example\nend law\n\n-- A literal list as a refinement is the input's domain.\nlaw \"|a listed key is kept| is\n  definition :\n    for all (key :: Text where key in [\"a\", \"b\", \"c\"]) => keep key = key end for all\n  end definition\nend law\n\n-- Membership in a list computed from an earlier input: the stages of each\n-- kind are the whole domain, so the law is checked on every pair.\nlaw \"|a stage is abbreviated by its token| is\n  definition :\n    for all (kind :: Kind) (stage :: Stage where stage in stagesOf kind) =>\n      abbreviate stage = stage.token\n    end for all\n  end definition\nend law\n\n-- The same list as a guard seeds generation with its members.\nlaw \"|a guarded key is kept| is\n  definition :\n    for all (key :: Text) => key in [\"north\", \"south\"] implies keep key = key end for all\n  end definition\nend law\nend unit\n")
  , ("validation.lawspec", "unit example.validation\n\n-- A record's rules are the restrictions its fields carry and its named\n-- rules. Each has a stable id: the field and the kind of restriction\n-- (age.min), the name `as` gives it (number.digits), or a rule's own name\n-- (vatForPro). LawSpec generates SignupDraft, validateSignup and\n-- violationsOfSignup because this unit names them.\n\nfunction validName (name :: Text) -> Bool is name matches regex \"[A-Za-z][A-Za-z '-]{0,63}\"\nend function\n\ntype Signup is a record{\n  name :: (v :: Text where validName v),\n  email :: (v :: Text where v matches format email),\n  age :: (v :: Int32 where 18 <= v && v <= 120),\n  plan :: (v :: Text where v in [\"free\", \"pro\"]),\n  code :: (v :: Text where v matches regex \"[A-Z]{2}[0-9]{2,8}\" as shape && prelude.length v <= 6),\n  vatId :: Text}\n  rule vatForPro is plan != \"pro\" || vatId != \"\"\nend type\n\nfunction ann (u :: Unit) -> SignupDraft is\n  SignupDraft record{name = \"Ann Lee\", email = \"ann@example.org\", age = 30, plan = \"pro\", code = \"GB1234\", vatId = \"GB123456\"}\nend function\n\nlaw \"|a valid draft passes| is\n  definition :\n    violationsOfSignup (ann ()) = []\n    and validateSignup (ann ()) = Right (Signup record{name = \"Ann Lee\", email = \"ann@example.org\", age = 30, plan = \"pro\", code = \"GB1234\", vatId = \"GB123456\"})\n  end definition\nend law\n\nlaw \"|each broken rule is named| is\n  definition :\n    validateSignup (ann () with name = \"4nn\") fails with name.validName\n    and validateSignup (ann () with email = \"ann.example.org\") fails with email.email\n    and validateSignup (ann () with age = 17) fails with age.min\n    and validateSignup (ann () with age = 121) fails with age.max\n    and validateSignup (ann () with plan = \"gold\") fails with plan.oneOf\n    and validateSignup (ann () with code = \"gb1234\") fails with code.shape\n    and validateSignup (ann () with code = \"GB12345\") fails with code.maxLength\n    and validateSignup (ann () with vatId = \"\") fails with vatForPro\n  end definition\nend law\n\nlaw \"|every broken rule is reported, in order| is\n  definition :\n    prelude.violatedRules (violationsOfSignup (ann () with age = 17, plan = \"gold\", email = \"\")) = [\"email.email\", \"age.min\", \"plan.oneOf\"]\n  end definition\nend law\n\nlaw \"|a violation says what is wrong| is\n  definition :\n    violationsOfSignup (ann () with age = 17) = [Violation record{rule = \"age.min\", field = Present \"age\", message = \"age must be at least 18, but was 17\"}]\n  end definition\nend law\nend unit\n")
  , ("workflows.lawspec", "unit example.workflows\n\n-- Workflows compose steps written by hand on each target. LawSpec generates\n-- the composition itself, so a workflow behaves the same everywhere: every\n-- stage below is a keyword, and each has a symbol too (>>=, <$>, <!>, <|>, ??).\n\ntype Signup is a record{  name :: Text age :: Int32} end type\ntype Account is a record{  name :: Text age :: Int32 level :: Int32} end type\ntype SignupError is one of | MissingName | TooYoung | NameTooLong | Unavailable end type\n\n-- Checked definitions: LawSpec writes these on every target.\nfunction explain (reason :: Text) -> SignupError is TooYoung end function\n\nfunction promote (a :: Account) -> Account is\n  first matching case of a :\n  when Account record{ name = name , age = age , level = level} then Account record{ name = name , age = age , level = 2}\n  end case\nend function\n\nfunction brief (a :: Account) -> Bool is\n  first matching case of a :\n  when Account record{ name = name , age = age , level = level} then prelude.length name <= 8\n  end case\nend function\n\nfunction tooLong (a :: Account) -> SignupError is NameTooLong end function\n\nfunction nameOf (s :: Signup) -> Text is\n  first matching case of s :\n  when Signup record{ name = name , age = age} then name\n  end case\nend function\n\n-- Side steps and recovery handlers, also written by hand.\naudit :: Account -> Bool\nwaitlist :: SignupError -> Either SignupError Account\n\n-- The workflow's error type is declared, so every step must fail with\n-- SignupError; checkAge fails with a reason, which mapError turns into one.\nworkflow register :: Signup -> Either SignupError Account is\n  checkName :: Signup -> Either SignupError Signup\n    retry exponential 100ms 2 3 max 1s jitter full\n  then checkAge :: Signup -> Either Text Signup\n  mapError explain\n  then openAccount :: Signup -> Either SignupError Account\n  map promote\n  tap audit\n  ensure brief else tooLong\n  orElse waitlist\nend workflow\n\n-- With the error written as _, LawSpec generates GreetError, with one\n-- constructor per step that can fail: GreetCheckNameFailed and GreetCheckAgeFailed.\nworkflow greet :: Signup -> Either _ Text is\n  checkName :: Signup -> Either SignupError Signup\n  >>= checkAge :: Signup -> Either Text Signup\n  <$> nameOf\n  ?? anonymous\nend workflow\n\nfunction anonymous (e :: GreetError) -> Text is \"guest\" end function\n\nlaw \"|registering an account| is\n  definition :\n    for all (s :: Signup) =>\n      prelude.isRight (register s) = (first matching case of s :\n        when Signup record{ name = name , age = age} then\n            prelude.length name > 0 && age >= 18 && prelude.length name <= 8\n        end case) end for all\n  end definition\n  example \"|a new account is promoted| :\n    s = Signup record{ name = \"ada\" , age = 30}\n    expect register s = Right (Account record{ name = \"ada\" , age = 30 , level = 2})\n  end example\n  example \"|a name is required| :\n    s = Signup record{ name = \"\" , age = 30}\n    expect register s = Left MissingName\n  end example\n  example \"|seventeen is too young| :\n    s = Signup record{ name = \"bob\" , age = 17}\n    expect register s = Left TooYoung\n  end example\n  example \"|a long name is rejected| :\n    s = Signup record{ name = \"bartholomew\" , age = 30}\n    expect register s = Left NameTooLong\n  end example\n  example \"|a taken name joins the waitlist| :\n    s = Signup record{ name = \"taken\" , age = 30}\n    expect register s = Right (Account record{ name = \"waitlist\" , age = 18 , level = 0})\n  end example\nend law\n\nlaw \"|greeting never fails| is\n  definition :\n    for all (s :: Signup) => prelude.isRight (greet s) = true end for all\n  end definition\n  example \"|a named greeting| :\n    s = Signup record{ name = \"ada\" , age = 30}\n    expect greet s = Right \"ada\"\n  end example\n  example \"|an anonymous greeting| :\n    s = Signup record{ name = \"\" , age = 30}\n    expect greet s = Right \"guest\"\n  end example\nend law\n\n-- An all group runs its steps on the same state and combines their results.\n-- With accumulate, every failing step's error is reported, in a generated\n-- VetFailures constructor.\nfunction firstName (a :: Signup) (b :: Signup) -> Text is nameOf a end function\n\nworkflow vet :: Signup -> Either _ Text is\n  all accumulate\n    then checkName\n    then checkAge\n  end all\n  combine firstName\nend workflow\n\nlaw \"|vetting reports every problem| is\n  definition :\n    for all (s :: Signup) =>\n      prelude.isRight (vet s) = (first matching case of s :\n        when Signup record{ name = name , age = age} then prelude.length name > 0 && age >= 18\n        end case) end for all\n  end definition\n  example \"|no problems| :\n    s = Signup record{ name = \"ada\" , age = 30}\n    expect vet s = Right \"ada\"\n  end example\nend law\n\nlaw \"|vetting a nameless child reports both problems| is\n  definition :\n    for all (age :: Int8 where age >= 0 && age < 18) =>\n      vet (Signup record{ name = \"\" , age = (prelude.Int32 age)}) = Left (VetFailures [VetCheckNameFailed MissingName, VetCheckAgeFailed \"too young\"]) end for all\n  end definition\nend law\n\nlaw \"|vetting a named child reports its age| is\n  definition :\n    for all (age :: Int8 where age >= 0 && age < 18) =>\n      vet (Signup record{ name = \"ada\" , age = (prelude.Int32 age)}) = Left (VetFailures [VetCheckAgeFailed \"too young\"]) end for all\n  end definition\nend law\n\n-- In a workflow with asynchronous steps, an all group runs them at the same\n-- time. Order -1's checks are slow: the stock check takes 400ms and the\n-- credit check 250ms, so run in turn they would take 650ms. Every order with\n-- a negative number fails both checks.\ntype Order is a record{  number :: Int64} end type\n\nasync checkStock :: Order -> Either Text Order\nasync checkCredit :: Order -> Either Text Order\n\nfunction firstOrder (a :: Order) (b :: Order) -> Order is a end function\n\nworkflow approve :: Order -> Either _ Order is\n  all accumulate\n    then checkStock\n    then checkCredit\n  end all\n  combine firstOrder\nend workflow\n\n-- The failures are in the order the steps are declared, not the order they\n-- finish in.\nlaw \"|approval reports failures in declaration order| is\n  definition :\n    for all (n :: Int64) =>\n      approve (Order record{ number = n}) = prelude.select (n < 0)\n        (Left (ApproveFailures [ApproveCheckStockFailed \"no stock\", ApproveCheckCreditFailed \"no credit\"]))\n        (Right (Order record{ number = n})) end for all\n  end definition\nend law\nend unit\n")
  ]

-- | examples/rc1/native-payments.lawspec.
paymentsSpecification :: String
paymentsSpecification = "unit example.payments\n\n-- Executable acceptance model for canonical native domain bindings.\n-- Applications may call Money \"Price\", amount \"major\", and currency \"unit\";\n-- those representation choices must not alter these laws.\ntype Currency is one of\n  | USD\n  | EUR\n  | GBP\nend type\n\ntype Money is a record{\n  amount of type Decimal\n  currency of type Currency\n}\nend type\n\ntype Payment is one of\n  | Paid of type Money\n  | Declined of type Text\nend type\n\naddFee of type Money -> Money\nroundTrip of type Payment -> Payment\narchive of type List (Maybe Payment) -> List (Maybe Payment)\n\nfunction feeModel (money of type Money) -> Money is\n  first matching case of money:\n    when Money record{amount = amount, currency = currency} then\n      Money record{amount = amount + 0.2, currency = currency}\n  end case\nend function\n\nlaw \"|fees preserve currency and exact decimal value| is\n  definition:\n    for all (money of type Money) =>\n      addFee money must be feeModel money\n    end for all\n  end definition\n\n  example \"|decimal tenths|:\n    money = Money record{amount = 0.1, currency = USD}\n    expect addFee money = Money record{amount = 0.3, currency = USD}\n  end example\n\n  example \"|small amount is not rounded away|:\n    money = Money record{\n      amount = 0.000000000000000000000000000001, currency = EUR\n    }\n    expect addFee money = Money record{\n      amount = 0.200000000000000000000000000001, currency = EUR\n    }\n  end example\n\n  example \"|beyond binary floating precision|:\n    money = Money record{amount = 9007199254740993.1, currency = GBP}\n    expect addFee money = Money record{\n      amount = 9007199254740993.3, currency = GBP\n    }\n  end example\nend law\n\nlaw \"|payment variants and payloads survive native conversion| is\n  definition:\n    for all (payment of type Payment) =>\n      roundTrip payment must be payment\n    end for all\n  end definition\n\n  example \"|successful payment|:\n    payment = Paid (Money record{amount = 12.34, currency = EUR})\n    expect roundTrip payment = Paid (Money record{\n      amount = 12.34, currency = EUR\n    })\n  end example\n\n  example \"|declined payment|:\n    payment = Declined \"card declined\"\n    expect roundTrip payment = Declined \"card declined\"\n  end example\nend law\n\nlaw \"|archives preserve order duplicates and absence| is\n  definition:\n    for all (payments of type List (Maybe Payment)) =>\n      archive payments must be payments\n    end for all\n  end definition\n\n  example \"|empty archive|:\n    payments = []\n    expect archive payments = []\n  end example\n\n  example \"|missing is different from a declined payment|:\n    payments = [\n    Absent, Present (Declined \"\"),\n    Present (Paid (Money record{amount = 0.1, currency = USD})),\n    Present (Paid (Money record{amount = 0.1, currency = USD}))\n    ]\n    expect archive payments = [\n    Absent, Present (Declined \"\"),\n    Present (Paid (Money record{amount = 0.1, currency = USD})),\n    Present (Paid (Money record{amount = 0.1, currency = USD}))\n    ]\n  end example\nend law\nend unit\n"

-- | Each target's examples/native-payments project: its files by relative
-- path, in readdir order.
paymentsProjects :: [(String, [(FilePath, String)])]
paymentsProjects =
  [ ("clojure",
      [ ("lawspec.edn", "{\n  :manifest-version 1\n  :component {\n    :name \"clojure\"\n    :version \"0.1.0\"\n  }\n  :sources [\"laws\"]\n  :machine-bits 64\n  :targets [\n    {\n      :language :clojure\n      :root \".\"\n      :native-bindings {\n        :functions [\n          {\n            :declaration \"example.payments::addFee\"\n            :native [\"domain\" \"payments\" \"apply_fee\"]\n          }\n          {\n            :declaration \"example.payments::roundTrip\"\n            :native [\"domain\" \"payments\" \"restore\"]\n          }\n          {\n            :declaration \"example.payments::archive\"\n            :native [\"domain\" \"payments\" \"store\"]\n          }\n        ]\n        :generators [\n          {\n            :type \"example.payments::type::Money\"\n            :factory [\"domain\" \"payment_generators\" \"prices\"]\n          }\n        ]\n      }\n    }\n  ]\n  :language-profile \"1.0-rc.2\"\n  :verification {\n    :layers [\n      :proof\n      :exhaustive\n      :property\n      :examples\n      :runtime\n      :model\n    ]\n  }\n}\n")
      , ("src/domain/payments.clj", ";; Application code over the model's payment data: Clojure binds functions,\n;; not types, so money is {:lawspec/tag :money/money :amount 1.20M\n;; :currency :currency/eur}.\n(ns domain.payments\n  \"Payments: the functions lawspec.edn binds.\")\n\n(defn apply-fee [money] (update money :amount + 0.2M))\n\n(defn restore [payment] payment)\n\n(defn store [payments] payments)\n")
      , ("test/domain/payment_generators.clj", ";; Application generators lawspec.edn binds: test.check generators of the\n;; model's tagged values.\n(ns domain.payment-generators\n  \"Prices between 1.00 and 2.00 euros.\"\n  (:require [clojure.test.check.generators :as gen]))\n\n(defn prices []\n  (gen/fmap (fn [cents] {:lawspec/tag :money/money :amount (BigDecimal/valueOf (long cents) 2) :currency :currency/eur})\n            (gen/choose 100 200)))\n")
      ]
    )
  , ("csharp",
      [ ("lawspec.edn", "{\n  :manifest-version 1\n  :component {\n    :name \"csharp\"\n    :version \"0.1.0\"\n  }\n  :sources [\"laws\"]\n  :machine-bits 64\n  :targets [\n    {\n      :language :csharp\n      :root \".\"\n      :native-bindings {\n        :functions [\n          {\n            :declaration \"example.payments::addFee\"\n            :native [\"Domain\" \"Payments\" \"ApplyFee\"]\n          }\n          {\n            :declaration \"example.payments::roundTrip\"\n            :native [\"Domain\" \"Payments\" \"Restore\"]\n          }\n          {\n            :declaration \"example.payments::archive\"\n            :native [\"Domain\" \"Payments\" \"Store\"]\n          }\n        ]\n        :generators [\n          {\n            :type \"example.payments::type::Money\"\n            :factory [\"Domain\" \"PaymentGenerators\" \"Prices\"]\n          }\n        ]\n      }\n    }\n  ]\n  :language-profile \"1.0-rc.2\"\n  :verification {\n    :layers [\n      :proof\n      :exhaustive\n      :property\n      :examples\n      :runtime\n      :model\n    ]\n  }\n}\n")
      , ("src/Domain/Payments.cs", "// Application code over the generated payment types: C# binds functions,\n// not types, so it uses LawSpec.Data's Money, Currency and Payment.\nnamespace Domain;\n\nusing LawSpec;\nusing LawSpec.Data;\nusing Microsoft.FSharp.Collections;\nusing Microsoft.FSharp.Core;\n\npublic static class Payments\n{\n    private static readonly ExactDecimal Fee = new(2, -1);\n\n    public static Money ApplyFee(Money money) => new(money.Amount + Fee, money.Currency);\n\n    public static Payment Restore(Payment payment) => payment;\n\n    public static FSharpList<FSharpOption<Payment>> Store(FSharpList<FSharpOption<Payment>> payments) => payments;\n}\n")
      , ("tests/Native/PaymentGenerators.cs", "// Prices the application considers representative: 1.00 to 2.00 euros.\nnamespace Domain;\n\nusing System.Numerics;\nusing FsCheck;\nusing FsCheck.Fluent;\nusing LawSpec;\nusing LawSpec.Data;\n\npublic static class PaymentGenerators\n{\n    public static Arbitrary<Money> Prices() =>\n        Arb.From(Gen.Choose(100, 200).Select(cents => new Money(new ExactDecimal(new BigInteger(cents), -2), Currency.EUR)));\n}\n")
      ]
