      , ("lawspec.edn", "{\n  :manifest-version 1\n  :component {\n    :name \"erlang\"\n    :version \"0.1.0\"\n  }\n  :sources [\"laws\"]\n  :machine-bits 64\n  :targets [\n    {\n      :language :erlang\n      :root \".\"\n      :native-bindings {\n        :types [\n          {\n            :type \"example.payments::type::Currency\"\n            :native [\"payments_domain\" \"currency_code\"]\n            :constructors [\n              {\n                :constructor \"USD\"\n                :native [\"dollars\"]\n                :style \"unit\"\n                :fields []\n              }\n              {\n                :constructor \"EUR\"\n                :native [\"euros\"]\n                :style \"unit\"\n                :fields []\n              }\n              {\n                :constructor \"GBP\"\n                :native [\"pounds\"]\n                :style \"unit\"\n                :fields []\n              }\n            ]\n          }\n          {\n            :type \"example.payments::type::Money\"\n            :native [\"payments_domain\" \"price\"]\n            :constructors [\n              {\n                :constructor \"Money\"\n                :native [\"price\"]\n                :style \"record\"\n                :fields [\n                  {\n                    :field \"amount\"\n                    :native \"major\"\n                  }\n                  {\n                    :field \"currency\"\n                    :native \"unit\"\n                  }\n                ]\n              }\n            ]\n          }\n          {\n            :type \"example.payments::type::Payment\"\n            :native [\"payments_domain\" \"payment_status\"]\n            :constructors [\n              {\n                :constructor \"Paid\"\n                :native [\"settled\"]\n                :style \"variant\"\n                :fields [\n                  {\n                    :field \"value\"\n                    :native \"price\"\n                  }\n                ]\n              }\n              {\n                :constructor \"Declined\"\n                :native [\"rejected\"]\n                :style \"variant\"\n                :fields [\n                  {\n                    :field \"value\"\n                    :native \"explanation\"\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n        :functions [\n          {\n            :declaration \"example.payments::addFee\"\n            :native [\"payments_domain\" \"apply_fee\"]\n          }\n          {\n            :declaration \"example.payments::roundTrip\"\n            :native [\"payments_domain\" \"restore\"]\n          }\n          {\n            :declaration \"example.payments::archive\"\n            :native [\"payments_domain\" \"store\"]\n          }\n        ]\n        :generators [\n          {\n            :type \"example.payments::type::Money\"\n            :factory [\"payment_generators\" \"prices\"]\n          }\n        ]\n        :erlang-includes [\n          {\n            :path \"payments_domain.hrl\"\n          }\n        ]\n      }\n    }\n  ]\n  :language-profile \"1.0-rc.2\"\n  :verification {\n    :layers [\n      :proof\n      :exhaustive\n      :property\n      :examples\n      :runtime\n      :model\n    ]\n  }\n}\n")
      , ("src/payments_domain.erl", "%% Application-owned payment types; no generated domain declarations.\n-module(payments_domain).\n-export([apply_fee/1, restore/1, store/1]).\n-export_type([currency_code/0, price/0, payment_status/0]).\n-include(\"payments_domain.hrl\").\n\n-type currency_code() :: dollars | euros | pounds.\n-type price() :: #price{unit :: currency_code(), major :: lawspec_beam_scalar:decimal()}.\n-type payment_status() :: {settled, price()} | {rejected, binary()}.\n\n-spec apply_fee(price()) -> price().\napply_fee(#price{major = Amount} = Price) ->\n    Fee = lawspec_beam_scalar:decimal(2, -1),\n    Price#price{major = lawspec_beam_scalar:binary(\n        <<\"+\">>, Amount, Fee, <<\"Decimal\">>, <<\"Decimal\">>)}.\n\n-spec restore(payment_status()) -> payment_status().\nrestore(Payment) -> Payment.\n\n-spec store([absent | {present, payment_status()}]) -> [absent | {present, payment_status()}].\nstore(Payments) -> Payments.\n")
