         :native [\"Domain\" \"PaymentsDomain\" \"PaymentStatus\" \"Settled\"]\n                :style \"variant\"\n                :fields [\n                  {\n                    :field \"value\"\n                    :native \"price\"\n                  }\n                ]\n              }\n              {\n                :constructor \"Declined\"\n                :native [\"Domain\" \"PaymentsDomain\" \"PaymentStatus\" \"Rejected\"]\n                :style \"variant\"\n                :fields [\n                  {\n                    :field \"value\"\n                    :native \"explanation\"\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n        :functions [\n          {\n            :declaration \"example.payments::addFee\"\n            :native [\"Domain\" \"PaymentsDomain\" \"apply_fee\"]\n          }\n          {\n            :declaration \"example.payments::roundTrip\"\n            :native [\"Domain\" \"PaymentsDomain\" \"restore\"]\n          }\n          {\n            :declaration \"example.payments::archive\"\n            :native [\"Domain\" \"PaymentsDomain\" \"store\"]\n          }\n        ]\n        :generators [\n          {\n            :type \"example.payments::type::Money\"\n            :factory [\"Domain\" \"PaymentGenerators\" \"prices\"]\n          }\n        ]\n      }\n    }\n  ]\n  :language-profile \"1.0-rc.2\"\n  :verification {\n    :layers [\n      :proof\n      :exhaustive\n      :property\n      :examples\n      :runtime\n      :model\n    ]\n  }\n}\n")
      , ("src/Native/Types/PaymentsDomain.fs", "/// Application types, independent of generated LawSpec domain declarations.\nmodule Domain.PaymentsDomain\n\nopen LawSpec\n\ntype CurrencyCode =\n    | Dollars\n    | Euros\n    | Pounds\n\ntype Price = { major: ExactDecimal; unit: CurrencyCode }\n\ntype PaymentStatus =\n    | Settled of price: Price\n    | Rejected of explanation: string\n\nlet private fee: ExactDecimal = { Coefficient = 2I; Exponent = -1 }\n\nlet apply_fee (price: Price) : Price = { price with major = price.major + fee }\n\nlet restore (payment: PaymentStatus) : PaymentStatus = payment\n\nlet store (payments: PaymentStatus option list) : PaymentStatus option list = payments\n")
      , ("tests/Native/PaymentGenerators.fs", "/// Prices the application considers representative: 1.00 to 2.00 euros.\nmodule Domain.PaymentGenerators\n\nopen FsCheck\nopen FsCheck.FSharp\nopen Domain.PaymentsDomain\n\nlet prices () : Arbitrary<Price> =\n    Gen.choose (100, 200)\n    |> Gen.map (fun cents -> { major = { Coefficient = bigint cents; Exponent = -2 }; unit = Euros })\n    |> Arb.fromGen\n")
