      [ ("lawspec.edn", "{\n  :manifest-version 1\n  :component {\n    :name \"gleam\"\n    :version \"0.1.0\"\n  }\n  :sources [\"laws\"]\n  :machine-bits 64\n  :targets [\n    {\n      :language :gleam\n      :root \".\"\n      :native-bindings {\n        :types [\n          {\n            :type \"example.payments::type::Currency\"\n            :native [\"payments_domain\" \"CurrencyCode\"]\n            :constructors [\n              {\n                :constructor \"USD\"\n                :native [\"payments_domain\" \"Dollars\"]\n                :style \"unit\"\n                :fields []\n              }\n              {\n                :constructor \"EUR\"\n                :native [\"payments_domain\" \"Euros\"]\n                :style \"unit\"\n                :fields []\n              }\n              {\n                :constructor \"GBP\"\n                :native [\"payments_domain\" \"Pounds\"]\n                :style \"unit\"\n                :fields []\n              }\n            ]\n          }\n          {\n            :type \"example.payments::type::Money\"\n            :native [\"payments_domain\" \"Price\"]\n            :constructors [\n              {\n                :constructor \"Money\"\n                :native [\"payments_domain\" \"Price\"]\n                :style \"record\"\n                :fields [\n                  {\n                    :field \"amount\"\n                    :native \"major\"\n                  }\n                  {\n                    :field \"currency\"\n                    :native \"unit\"\n                  }\n                ]\n              }\n            ]\n          }\n          {\n            :type \"example.payments::type::Payment\"\n            :native [\"payments_domain\" \"PaymentStatus\"]\n            :constructors [\n              {\n                :constructor \"Paid\"\n                :native [\"payments_domain\" \"Settled\"]\n                :style \"variant\"\n                :fields [\n                  {\n                    :field \"value\"\n                    :native \"price\"\n                  }\n                ]\n              }\n              {\n                :constructor \"Declined\"\n                :native [\"payments_domain\" \"Rejected\"]\n                :style \"variant\"\n                :fields [\n                  {\n                    :field \"value\"\n                    :native \"explanation\"\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n        :functions [\n          {\n            :declaration \"example.payments::addFee\"\n            :native [\"payments_domain\" \"apply_fee\"]\n          }\n          {\n            :declaration \"example.payments::roundTrip\"\n            :native [\"payments_domain\" \"restore\"]\n          }\n          {\n            :declaration \"example.payments::archive\"\n            :native [\"payments_domain\" \"store\"]\n          }\n        ]\n        :generators [\n          {\n            :type \"example.payments::type::Money\"\n            :factory [\"payment_generators\" \"prices\"]\n          }\n        ]\n      }\n    }\n  ]\n  :language-profile \"1.0-rc.2\"\n  :verification {\n    :layers [\n      :proof\n      :exhaustive\n      :property\n      :examples\n      :runtime\n      :model\n    ]\n  }\n}\n")
      , ("prepare.mjs", "// Compile dependencies before LawSpec generates the runtime imported by the app.\nimport {execFile} from 'node:child_process';\nimport {promisify} from 'node:util';\nimport {cp, mkdir, mkdtemp, readFile, readdir, rm} from 'node:fs/promises';\nimport path from 'node:path';\nimport {fileURLToPath} from 'node:url';\n\nconst exec = promisify(execFile);\nconst root = path.dirname(fileURLToPath(import.meta.url));\nawait mkdir(path.join(root, '.lawspec'), {recursive: true});\nconst temporary = await mkdtemp(path.join(root, '.lawspec/dependencies-'));\ntry {\n  // Use the project's actual dependency requirements and lock file, with empty\n  // application roots. Application code remains in place throughout setup.\n  await mkdir(path.join(temporary, 'src'), {recursive: true});\n  await mkdir(path.join(temporary, 'test-support/src'), {recursive: true});\n  for (const file of ['gleam.toml', 'test-support/gleam.toml'])\n    await cp(path.join(root, file), path.join(temporary, file));\n  try { await cp(path.join(root, 'manifest.toml'), path.join(temporary, 'manifest.toml')); }\n  catch (error) { if (error.code !== 'ENOENT') throw error; }\n  // Reuse downloaded packages when available, including fully offline setups.\n  try { await cp(path.join(root, 'build/packages'), path.join(temporary, 'build/packages'), {recursive: true}); }\n  catch (error) { if (error.code !== 'ENOENT') throw error; }\n\n  const {stdout, stderr} = await exec('gleam', ['build'], {cwd: temporary,\n    timeout: 300000, maxBuffer: 8 * 1024 * 1024});\n  process.stdout.write(stdout);\n  process.stderr.write(stderr);\n  const information = path.join(temporary, 'package.json');\n  await exec('gleam', ['export', 'package-information', '--out', information], {cwd: temporary});\n  const application = JSON.parse(await readFile(information, 'utf8'))['gleam.toml'].name;\n\n  await mkdir(path.join(root, 'build/dev/erlang'), {recursive: true});\n  await cp(path.join(temporary, 'build/packages'), path.join(root, 'build/packages'), {recursive: true});\n  for (const entry of await readdir(path.join(temporary, 'build/dev/erlang'), {withFileTypes: true})) {\n    if (!entry.isDirectory() || [application, 'lawspec_test_support'].includes(entry.name)) continue;\n    await cp(path.join(temporary, 'build/dev/erlang', entry.name),\n      path.join(root, 'build/dev/erlang', entry.name), {recursive: true});\n  }\n  await cp(path.join(temporary, 'manifest.toml'), path.join(root, 'manifest.toml'));\n  console.log('Dependencies compiled. Run lawspec generate, then gleam test.');\n} catch (error) {\n  process.stderr.write(error.stdout ?? '');\n  process.stderr.write(error.stderr ?? '');\n  throw error;\n} finally {\n  await rm(temporary, {recursive: true, force: true});\n}\n")
      , ("src/payments_domain.gleam", "//// Application-owned payment types; no generated domain declarations.\nimport gleam/option.{type Option}\nimport lawspec/scalar\nimport lawspec/types\n\npub type CurrencyCode {\n  Dollars\n  Euros\n  Pounds\n}\n\n// Field order deliberately differs from the specification and binding JSON.\npub type Price {\n  Price(unit: CurrencyCode, major: types.Decimal)\n}\n\npub type PaymentStatus {\n  Settled(price: Price)\n  Rejected(explanation: String)\n}\n\npub fn apply_fee(price: Price) -> Price {\n  Price(..price, major: scalar.decimal_add(price.major, scalar.decimal(2, -1)))\n}\n\npub fn restore(payment: PaymentStatus) -> PaymentStatus {\n  payment\n}\n\npub fn store(payments: List(Option(PaymentStatus))) -> List(Option(PaymentStatus)) {\n  payments\n}\n")
      , ("test/payment_generators.gleam", "import lawspec/scalar\nimport payments_domain\nimport qcheck\n\n// qcheck.map preserves the integer generator's native shrink tree.\npub fn prices() -> qcheck.Generator(payments_domain.Price) {\n  qcheck.map(qcheck.bounded_int(100, 200), fn(cents) {\n    payments_domain.Price(\n      unit: payments_domain.Euros,\n      major: scalar.decimal(cents, -2),\n    )\n  })\n}\n")
