              :constructor \"Declined\"\n                :native [\"Rejected\"]\n                :style \"variant\"\n                :fields [\n                  {\n                    :field \"value\"\n                    :native \"Explanation\"\n                  }\n                ]\n              }\n            ]\n          }\n        ]\n        :functions [\n          {\n            :declaration \"example.payments::addFee\"\n            :native [\"AddFee\"]\n          }\n          {\n            :declaration \"example.payments::roundTrip\"\n            :native [\"Restore\"]\n          }\n          {\n            :declaration \"example.payments::archive\"\n            :native [\"Store\"]\n          }\n        ]\n        :generators [\n          {\n            :type \"example.payments::type::Money\"\n            :factory [\"NativePrices\"]\n          }\n        ]\n      }\n    }\n  ]\n  :language-profile \"1.0-rc.2\"\n  :verification {\n    :layers [\n      :proof\n      :exhaustive\n      :property\n      :examples\n      :runtime\n      :model\n    ]\n  }\n}\n")
