      , ("src/domain/payments.pl", "/** <module> Application-owned payments over canonical constructor terms.\n\nThe fee uses Prolog integer arithmetic, independently of the checked model's\ndecimal arithmetic. Aligning decimal exponents preserves every input digit.\n*/\n:- module('domain.payments', [apply_fee/2, restore/2, store/2]).\n\napply_fee(value(Tag, [decimal(Sign, Digits, Exponent), Currency]),\n          value(Tag, [decimal(ResultSign, ResultDigits, Scale), Currency])) :-\n    foldl(decimal_digit, Digits, 0, Magnitude),\n    Coefficient is (1 - 2*Sign)*Magnitude,\n    Scale is min(Exponent, -1),\n    Sum is Coefficient*10**(Exponent-Scale) + 2*10**(-1-Scale),\n    ( Sum < 0 -> ResultSign=1 ; ResultSign=0 ),\n    Absolute is abs(Sum),\n    number_codes(Absolute, Codes),\n    maplist(digit_code, ResultDigits, Codes).\n\ndecimal_digit(Digit, Previous, Result) :- Result is Previous*10 + Digit.\ndigit_code(Digit, Code) :- Digit is Code - 0'0.\n\nrestore(Payment, Payment).\nstore(Payments, Payments).\n")
      , ("tests/domain/payment_generators.pl", "/** <module> Native strategy factory with Hypothesis's ordinary shrinker.\n\nJanus retains child and result strategies as Python objects. The generated\nschema validates every generated native value and every candidate shrink.\n*/\n:- module('domain.payment_generators', [prices/1]).\n:- use_module(library(janus)).\n\nprices(Strategy) :-\n    py_call('hypothesis.strategies':integers(100, 200), Cents, [py_object(true)]),\n    py_call('hypothesis.strategies':just(-2), Exponent, [py_object(true)]),\n    py_call(lawspec_runtime:make_decimal, Decimal, [py_object(true)]),\n    py_call('hypothesis.strategies':builds(Decimal, Cents, Exponent), Amounts, [py_object(true)]),\n    py_call(lawspec_data:'CurrencyEUR'(), Euro, [py_object(true)]),\n    py_call('hypothesis.strategies':just(Euro), Currencies, [py_object(true)]),\n    py_call(lawspec_data:'Money', Money, [py_object(true)]),\n    py_call('hypothesis.strategies':builds(Money, Amounts, Currencies), Strategy, [py_object(true)]).\n")
      ]
