      , ("src/payments_domain.py", "\"\"\"Application-owned payment types; no generated domain declarations.\"\"\"\n\nfrom dataclasses import dataclass\nfrom decimal import Decimal\nfrom fractions import Fraction\n\nimport lawspec_runtime as ls\n\n\nclass CurrencyCode:\n    pass\n\n\n@dataclass(frozen=True)\nclass Dollars(CurrencyCode):\n    pass\n\n\n@dataclass(frozen=True)\nclass Euros(CurrencyCode):\n    pass\n\n\n@dataclass(frozen=True)\nclass Pounds(CurrencyCode):\n    pass\n\n\n@dataclass(frozen=True, kw_only=True)\nclass Price:\n    # Order differs deliberately; bridges must use the mapped field names.\n    unit: CurrencyCode\n    major: Decimal\n\n\nclass PaymentStatus:\n    pass\n\n\n@dataclass(frozen=True, kw_only=True)\nclass Settled(PaymentStatus):\n    price: Price\n\n\n@dataclass(frozen=True, kw_only=True)\nclass Rejected(PaymentStatus):\n    explanation: str\n\n\ndef apply_fee(price):\n    amount = ls.finite_decimal(Fraction(price.major) + Fraction(1, 5))\n    return Price(major=amount, unit=price.unit)\n\n\ndef restore(payment):\n    return payment\n\n\ndef store(payments):\n    return payments\n")
      , ("tests/lawspec_generators.py", "\"\"\"Application strategies retain ordinary Hypothesis shrinking.\"\"\"\n\nfrom decimal import Decimal\n\nfrom hypothesis import strategies as st\n\nfrom payments_domain import Euros, Price\n\n\ndef prices():\n    def price(cents):\n        digits = tuple(map(int, str(cents)))\n        return Price(major=Decimal((0, digits, -2)), unit=Euros())\n\n    return st.integers(min_value=100, max_value=200).map(price)\n")
